window.__D("text/torat-menachem/c082",{"p":[[1400350023,"<h3>בס\"ד. רשימת<sup data-n=\"1370\">*</sup><b> כ\"ק אדמו\"ר שליט\"א</b></h3>\nשנת המאתים<sup data-n=\"1371\">1</sup>.\nהשם גן יש'<sup data-n=\"1372\">2</sup>. – שייכות במיוחד – ההתחלה בחינוך ילדים קטנים שנות התענוג שלו<sup data-n=\"1373\">3</sup>.\n[מסר] עד\"ז כמובן הנהגת ת'<sup data-n=\"1374\">4</sup>.\nסיפר כ\"ק מו\"ח אדמו\"ר (שיום הגאולה<sup data-n=\"1375\">5</sup>) כמה סיפ<sup data-n=\"1376\">6</sup>\nעיקר החינוך – לעשות הת' בפ\"ע<sup data-n=\"1377\">7</sup>. כללים בלימוד. היותר כולל – הבעש\"ט<sup data-n=\"1378\">8</sup> איזהו חכ' הלומד – סומוע\"ט וע\"ט\nמאמר עשו לקש<sup data-n=\"1379\">9</sup>\n[עדיין קטן ומה יכול לפעול – משל הה\"מ<sup data-n=\"1380\">10</sup> דאב מרכין א\"ע<sup data-n=\"1381\">11</sup> לבנו התינוק כו'<sup data-n=\"1382\">12</sup>].\n– מובן ביותר עפ\"ד<sup data-n=\"1383\">13</sup> הבעש\"ט דאהבת ישראל [יותר מלבן יחיד] – אבל הת'<sup data-n=\"1384\">14</sup> צ\"ל נוגע לו ולעשות בכל לבו ואז יותר מתפלת הגדול<sup data-n=\"1385\">15</sup>וכמ\"ר<sup data-n=\"1386\">16</sup> אדה\"ז [להרים התינוק<sup data-n=\"1387\">17</sup>] בלא דו\"ר<sup data-n=\"1388\">18</sup>.\nועד\"ז הבעש\"ט (קוקוריקו) 19.\n– ואיך יפעול הת'<sup data-n=\"1389\">20</sup> זה בעצמו – אדהאמ\"צ היפך הפרי\"ע<sup data-n=\"1390\">21</sup>\nהבעש\"ט שויתי<sup data-n=\"1391\">22</sup> (אינו ירא ביער<sup data-n=\"1392\">23</sup>.\nמזה שאפילו שכשרונותיו טובין. להוסיף על הפרוגרם צ\"צ שרוצה [<sup data-n=\"1393\">24</sup>] ביגיעה דוקא<sup data-n=\"1394\">25</sup>\nוע\"ד הבעש\"ט שחסר'<sup data-n=\"1395\">26</sup> ההתלהבות<sup data-n=\"1396\">27</sup>\nביותר ההתלהבות – מהר\"ש<sup data-n=\"1397\">28</sup> יפה ש\"א<sup data-n=\"1398\">29</sup> תענוג הבורא עד\"ז הבעש\"ט שלוקחים העוה\"ב ושמח<sup data-n=\"1397\">28</sup>.\n[והבחינה המעשה אדנ\"ע (היום יום<sup data-n=\"1399\">30</sup> ) ועד\"ז הבעש\"ט]\nושבהתלהבות בזה מוצאים בכ\"מ<sup data-n=\"1400\">31</sup> אויפטאן וע\"ד אדנ\"ע להכנסת כלה בויין שנסע וכו'<sup data-n=\"1401\">32</sup>\nועד\"ז הבעש\"ט ששלח הר\"ח רפפורט לעשות ברכה<sup data-n=\"1401\">32</sup>.\n– הנהגה כהנ\"ל – מפי עוללים ויונקים שלפני המאסר<sup data-n=\"1402\">33</sup> והרי נצח<sup data-n=\"1403\">34</sup>.\nמאבע\"ש<sup data-n=\"1404\">35</sup> להה\"מ ע\"ח אור מלאכים<sup data-n=\"1396\">27</sup>.\n**********",[["1370","*","ראשי-פרקים ונקודות שרשם לעצמו לקראת ההתוועדות במחנה-קיץ \"גן ישראל\" ביום א' פ' פינחס, ט\"ו תמוז (בהערות דלקמן צויין לחלק השיחה שבהם נתבאר ענין זה). – נעתקה מצילום כתי\"ק שבספריית אגודת חסידי חב\"ד (צילומה, לעיל ע' V (התיבות שהועבר עליהן קולמוס, באו בחצאי-ריבוע))."],["1371","1","של הבעש\"ט – ראה לקמן ס\"ב (ע' 237)."],["1372","2","= ישראל (שמו של הבעש\"ט). – לקמן ס\"ב (ע' 236)."],["1373","3","ראה לקמן ס\"ג."],["1374","4","= תלמידיו. – לקמן ס\"ב (ע' 236)."],["1375","5","י\"ב י\"ג תמוז."],["1376","6","= סיפורים. – לקמן רס\"ג."],["1377","7","= התלמידים (שיוכלו לעמוד כו') בפני עצמם."],["1378","8","תורת הבעש\"ט בפירוש מארז\"ל \"איזהו חכם הלומד מכל אדם\", שמהצדיק לומדים \"עשה טוב\", ומהרשע – \"סור מרע\" (לקמן ס\"ד)."],["1379","9","ראה לקמן ס\"ה – תורת הה\"מ עה\"פ \"והי' בית עשו לקש\"."],["1380","10","ראה או\"ת פ' בראשית בתחילתה. פה, סע\"ד. – נתבאר בד\"ה לכה דודי תרפ\"ט ס\"ב-ג (סה\"מ תרפ\"ט ע' 83 ואילך). תשי\"ד (תו\"מ סה\"מ אלול ע' רלו ואילך)."],["1381","11","= את עצמו."],["1382","12","ענין זה לא נזכר בהשיחה. – ולהעיר משיחת ט\"ו תמוז תשי\"ז במחנה-קיץ \"גן ישראל\" ס\"ד (תו\"מ ח\"כ ע' 173)."],["1383","13","= על פי דברי הבעש\"ט – כתר שם טוב (הוצאת תשנ\"ט) בהוספות סימן קסז."],["1384","14","= התלמיד, או התינוק. ואולי: התפלה."],["1385","15","ענין זה לא נזכר בהשיחה."],["1386","16","= וכמעשה רב."],["1387","17","אולי הכוונה להסיפור שאדה\"ז הרים את התינוק שנפל ובכה (ראה בארוכה לקו\"ש ח\"ג ע' 802). – ענין זה לא נזכר בהשיחה."],["1388","18","= דחילו ורחימו. – ראה לקמן ס\"ז ע\"ד העבודה בדחילו ורחימו דוקא.\n&lt;19&gt; ) ראה לקמן ס\"ח."],["1389","20","= התלמיד. – ראה לקמן ס\"י."],["1390","21","= הפריקת-עול (ראה שם)."],["1391","22","הענין ד\"שויתי\" – לא נזכר בהשיחה."],["1392","23","ראה לקמן סי\"א."],["1393","24","כאן יש תיבה שאינה ברורה בכתי\"ק, ואולי העביר קולמוס ע\"ז."],["1394","25","ראה לקמן סי\"ב."],["1395","26","= שחסרה."],["1396","27","ראה לקמן סי\"ג."],["1397","28","ראה לקמן סי\"ד."],["1398","29","= שעה אחת."],["1399","30","אולי הכוונה ל\"היום יום\" כג סיון. – ראה אגרות-קודש חט\"ז ע' רכב, ובהנסמן שם. – ענין זה לא נזכר בהשיחה."],["1400","31","= בכל מקום. – ראה לקמן סט\"ז."],["1401","32","ראה לקמן סט\"ו."],["1402","33","ראה ד\"ה וקבל היהודים תרפ\"ז פ\"ב – סה\"מ תרפ\"ז ע' קיא ואילך. וראה ב\"מכתב אחד הרבנים\" – שם ע' רפט."],["1403","34","ענין זה לא נתפרש להדיא בהשיחה (וראה לקמן ס\"ג)."],["1404","35","= מאמר הבעש\"ט."]]],[1400350024,"(הנחה בלתי מוגה)\n<b>ברוך</b><sup data-n=\"1405\">1</sup> שעשה נסים לאבותינו בימים ההם בזמן הזה<sup data-n=\"1406\">2</sup>. הנה<sup data-n=\"1407\">3</sup> מ\"ש נסים לשון רבים הרי זה כולל (נוסף על ריבוי הנסים) גם ריבוי בנוגע לסוגי נסים, שנחלקים בכללות לב' סוגים, וכמשנת\"ל במאמר שלפנ\"ז<sup data-n=\"1408\">4</sup> שיש נסים המלובשים בדרכי הטבע, ע\"ד הנס דמרדכי ואסתר, שהי' הנס בהתלבשות בלבושי הטבע, שתחילה גזר אחשורוש גזירה ואח\"כ ביטל בעצמו את הגזירה כו', ומ\"מ יודעים שהי' זה ענין של נס, אלא הי' זה באמצעות דרכי וכלי הטבע, אך יש עוד סוג נסים שלמעלה מדרך הטבע, ע\"ד הנס דקריעת ים סוף, וכן הנס דמן ושליו, כמ\"ש הרמב\"ם<sup data-n=\"1409\">5</sup> שמקום המדבר לא הי' מוכשר כלל למן ושליו, ולא הי' זה בטבע כלל, כי אם נס שלמעלה מדרך הטבע. והחילוק ביניהם הוא אם המשכת הנס היא משם הוי' או משם שדי. דהנה, פירוש שם שדי הוא לא רק שאמר לעולמו די<sup data-n=\"1410\">6</sup>, שהו\"ע הגבלת העולם, אלא ישנו גם הפירוש שדי באלקותו לכל ברי'<sup data-n=\"1411\">7</sup>, שהו\"ע המשכת וגילוי אלקות באופן שיהי' די ומספיק לכל ברי'. וזהו ענין נס המלובש בטבע, היינו, שהנס מתלבש בשם כזה שיש בו גם הפירוש שאמר לעולמו די. אך ישנו נס שנמשך משם הוי', דכתיב בי'<sup data-n=\"1412\">8</sup> כי שמש ומגן הוי' אלקים, היינו, ששם הוי' לגבי שם אלקים הוא כמו אור השמש לגבי המגן ונרתק, שהוא למעלה מהטבע לגמרי, וממנו נמשכים הנסים שהם למעלה מהטבע לגמרי. ונת\"ל<sup data-n=\"1407\">3</sup> שהכוונה היא שב' סוגי הנסים יומשכו מזה לזה כו', וע\"ד מ\"ש<sup data-n=\"1413\">9</sup> ברוך הוי' אלקי ישראל מן העולם ועד העולם<sup data-n=\"1414\">10</sup>, שצ\"ל המשכת אלקות, שם הוי', מן העולם, עלמא דאתכסיא, עד העולם, עלמא דאתגליא, היינו, שענין האלקות לא ישאר כפי שהואלמעלה מכל העולמות, וגם לא יהי' הגילוי בעלמא דאתכסיא בפ\"ע ובעלמא דאתגליא בפ\"ע, אלא שיומשך גילוי שם הוי' מעלמא דאתכסיא לעלמא דאתגליא (ועד\"ז בנוגע לענינים שלמעלה מהעולם – ב' סוגי הנסים, נסים שלמעלה מן הטבע לגמרי, ונסים המלובשים בדרכי ולבושי הטבע). ובעבודת האדם הו\"ע עירוב רשויות, דהיינו, שאע\"פ ששניהם רשות היחיד, עניני קדושה, מ\"מ, להיותם ענינים ודרכים שונים זמ\"ז, כגון קו החסד וקו הגבורה, הרי עדיין אין זה תכלית השלימות, דכיון שקו אחד אינו מתאים לקו השני, אין כל קו יכול להיות בשלימותו, לפי שיש לו מנגד. וכדי שיהי' ענין השלימות צריך להיות קו האמצעי, תפארת, שענינו בעבודת האדם הוא מדת הרחמים, שמצדה נמשכת השפעת החסד גם במקום כזה שמצד מדת הגבורה לא היתה יכולה להיות השפעת החסד, ונמצא, שזהו ענין שאין עליו מנגד, והיינו לפי שענינו של קו האמצעי (קו התפארת), שכולל הן את הטעמים דקו הגבורה והן את הטעמים דקו החסד, ולאח\"ז בא לידי הכרעת המסקנא באופן של החלטה אחת הכוללת את ב' הקוים. וזהו כללות הענין דעירוב רשויות, כמרומז גם בתיבת עירוב שהיא תיבה אחת שכוללת האותיות ע\"ב רי\"ו<sup data-n=\"1415\">11</sup>, ע\"ב בגימטריא חסד (ולמעלה יותר, כידוע ששם ע\"ב הוא בחכמה<sup data-n=\"1416\">12</sup>, מקור החסד, ולכן חסד עם הכולל בגימטריא חכמה<sup data-n=\"1417\">13</sup>), ורי\"ו בגימטריא גבורה<sup data-n=\"1418\">14</sup> (כולל גם בינה שהיא שורש הגבורה), ותיבת עירוב שכוללת שניהם הו\"ע קו האמצעי, דעת ותפארת, שמאחד (חכמה ובינה, ואח\"כ גם) חסד וגבורה. וזהו גם מ\"ש ברוך הוי' אלקי ישראל מן העולם ועד העולם, ישראל דייקא, כיון שענין זה הוא עבודת יעקב, בחיר שבאבות<sup data-n=\"1419\">15</sup>, קו האמצעי, שהוא בריח<sup data-n=\"1420\">16</sup> התיכון המבריח מן הקצה אל הקצה<sup data-n=\"1421\">17</sup> (כמשנת\"ל בארוכה במאמר שלפנ\"ז).\nב) <b>וזהו</b><sup data-n=\"1422\">18</sup> גם מ\"ש<sup data-n=\"1423\">19</sup> מגיד דבריו ליעקב חוקיו ומשפטיו לישראל גו', ומבואר בסידור<sup data-n=\"1424\">20</sup>, שכאשר ישנה העבודה דיעקב (הנ\"ל), אזי מגיד דבריו גו', היינו, שכל ההמשכות שנימנו לפנ\"ז, הנותן שלג כצמרכפור כאפר גו'<sup data-n=\"1425\">21</sup>, הנה כל זה ה\"ה מגיד וממשיך ליעקב דוקא, להיותו בריח התיכון המבריח מן הקצה אל הקצה (וכנ\"ל שהוא ממשיך ומאחד עלמא דאתכסיא ועלמא דאתגליא), משא\"כ לב' הקצוות דחו\"ג, הרי יצא מהם פסולת<sup data-n=\"1426\">22</sup>, כי רק מקו האמצעי אין מקום ליניקת החיצונים כלל. וממשיך לבאר&lt;20&gt;, שגם בסופו של קו האמצעי שהוא בחי' יסוד, שהי' מקום ליניקת החיצונים מבחי' קליפת הערלה שביסוד, הנה ע\"י מצות מילה הרי נכרתת קליפת הערלה, וא\"כ אין לחיצונים אחיזה כלל בקו האמצעי. וזהו גם מ\"ש<sup data-n=\"1427\">23</sup> ויעקב איש תם יושב אהלים, יושב אהלים הו\"ע החיבור והאחדות דבינה ומלכות<sup data-n=\"1428\">24</sup> (שהם עלמא דאתכסיא ועלמא דאתגליא), וענין זה נעשה ע\"י היותו איש תם, שנולד מהול<sup data-n=\"1429\">25</sup>, כי, ענין המילה, הסרת הערלה, פועל שלא תהי' יניקת החיצונים אפילו מסופו של קו האמצעי שהוא בחי' היסוד. ולהעיר, שאצל יעקב עצמו לא היתה צריכה להיות העבודה דמילה, שהרי נולד מהול, אלא שאח\"כ בעבודה הרי זה ענין מצות מילה, שנעשה איש תם ע\"י עבודתו בהסרת הערלה.\n<b>אמנם</b> ע\"פ האמור לעיל הרי ענין המילה הוא רק כדי שלא תהי' יניקת החיצונים אפילו מסופו של קו האמצעי, ואין זה שייך לעצם הענין דחיבור ואחדות דעלמא דאתכסיא ועלמא דאתגליא. אבל מלשון הכתוב איש תם יושב אהלים, משמע, שמה שהי' איש תם זהו סיבת היותו יושב אהלים, ושיהי' בכוחו לחבר עלמא דאתכסיא ועלמא דאתגליא.\n<b>ויובן</b> בהקדם כללות הביאור בענין מצות מילה שנצטווה אברהם אבינו, כמ\"ש<sup data-n=\"1430\">26</sup> התהלך לפני והי' תמים, דלכאורה, הרי מצינו שהיו כמה צדיקים ונביאים גם קודם שניתנה מצות מילה, וגם אצל אברהם עצמו מצינו כמה ענינים של נבואה עוד קודם שנימול. ומבואר בזה<sup data-n=\"1431\">27</sup>, שכאשר הוצרך להיות גילוי אור עליון נעלה ביותר, הנה בשביל זה הי' צ\"ל הסרת הערלה, והיינו, שאפילו עור הערלה דאברהם שלא העלים והסתיר על הגילויים שלפנ\"ז, ה\"ה מעלים ומסתיר על גילוי אור עליון יותר, שאינו יכול להתגלות אלא ע\"י הסרת ההעלם וההסתר כו', שזהו\"ע המילה. וזהו גם ענין איש תם יושב אהלים, שמצד גודל מעלת הענין דיושב אהלים,שהו\"ע עירוב רשויות, חיבור ואחדות עלמא דאתכסיא ועלמא דאתגליא, צ\"ל תחילה הסרת הערלה (איש תם).\nג) <b>וביאור</b> הענין, דהנה, איתא במדרש<sup data-n=\"1432\">28</sup>, ששאל מין אחד את ר' עקיבא, אם כדבריך שהקב\"ה מכבד את השבת, אל ישב בה רוחות, אל יוריד בה גשמים, אל יצמיח בה עשב, והשיב לו משל לשנים שהיו דרין בחצר אחת שצריכים עירוב, אבל אם הי' אחד דר בחצר הרי הוא מותר בכל החצר כולה, אף כאן הקב\"ה לפי שאין רשות אחרת עמו וכל העולם כולו שלו, מותר בכל העולם כולו. ולכאורה אינו מובן, הרי שאלתו היתה (לא רק על הוצאה והכנסה, אלא) על כל ל\"ט המלאכות, שאינן תלויות בחילוק רשויות כלל. אך הביאור בזה, שענין ל\"ט המלאכות הוא בירור הניצוצות דתהו, וזהו ענין ששת ימים תעבוד<sup data-n=\"1433\">29</sup>, כדאיתא במכילתא<sup data-n=\"1434\">30</sup> זו מצות עשה, שזהו\"ע עבודת הבירורים. ובשבת צ\"ל השביתה ממלאכה, כי בשבת בורר אסור<sup data-n=\"1435\">31</sup>. אמנם, בבחי' שלמעלה מתהו לא שייך כלל ענין הבירורים, ושם מותרים כל המלאכות. וזהו שהשיב לו ר\"ע משל מחילוק רשויות, כי, בבחי' שלא שייך בה חילוק רשויות (שזוהי בחי' א\"ק, שכולל את כללות הבריאה), לא שייך גם ענין הבירורים, ושם מותרים כל המלאכות, ולכן הקב\"ה משיב רוחות ומוריד גשמים ומצמיח כו'. ומזה מובן גודל העילוי דעירוב רשויות, שהו\"ע המשכת אור עליון ביותר שלמעלה אפילו מהגילוי אור דיום השבת, שמבטל את חילוקי הרשויות, ועושה מכולם רשות אחת שנקראת רשות היחיד, ליחידו של עולם<sup data-n=\"1436\">32</sup>.\n<b>וזהו</b> גם ענין המילה<sup data-n=\"1437\">33</sup> שדוחה שבת (שכל המלאכות הקשורות עם מילה מותרות בשבת)<sup data-n=\"1438\">34</sup>, היינו, שמילה היא למעלה משבת, כי, יום השבת הוא אחד מהשבעה ימים שנקראים שבעת ימי הבנין<sup data-n=\"1439\">35</sup>, שיש להם שייכות לסדר השתלשלות, משא\"כ מילה היא ביום השמיני<sup data-n=\"1440\">36</sup>, שזוהי בחינהשלמעלה מכל סדר ההשתלשלות. וזהו שאמרו רז\"ל<sup data-n=\"1441\">37</sup> בהטעם על מילה בשמיני כדי שיעבור עליו שבת אחת, דפירוש לשון יעבור הוא ע\"ד המבואר<sup data-n=\"1442\">38</sup> בענין עד יעבור עמך הוי'<sup data-n=\"1443\">39</sup>, שהוא למעלה משם הוי', וזהו גם שיעבור עליו שבת אחת, שהמילה היא למעלה מהשבת. וכדי שיאיר גילוי אור היותר נעלה שלמעלה מהשתלשלות (בחי' שמיני), הנה על זה צריך להיות הסרת הערלה, כי, לגבי האור היותר נעלה נחשבת הערלה לענין של העלם והסתר. וזהו ענין איש תם יושב אהלים, שע\"י הסרת הערלה (איש תם), יכול להיות נמשך הגילוי היותר נעלה דיושב אהלים, שהו\"ע עירוב רשויות, כנ\"ל.\nד) <b>אך</b> עדיין צריך להבין בביאור הנ\"ל שענין המילה הוא מצד עוצם מעלת גילוי האור, דלכאורה, הרי מבואר בסידור&lt;20&gt; בפירוש מגיד דבריו ליעקב גו', שענין המילה הוא בכדי שלא יומשך תוספת יניקה לחיצונים. ונקודת הביאור בזה, שיניקת החיצונים מהקדושה (בהוספה על מה שניתן להם מצד הבריאה) יכולה להיות גם מצד עוצם מעלת גילוי האור, כי, מצד גודל מעלת האור הרי זה באופן דכחשיכה כאורה<sup data-n=\"1444\">40</sup>, ואם צדקת מה תתן לו<sup data-n=\"1445\">41</sup>, ולכן יכולה להיות יניקה גם לחיצונים, כידוע בענין שממית בידים תתפש והיא בהיכלי מלך<sup data-n=\"1446\">42</sup>. ולכן, הצורך בענין המילה הוא לא רק כדי שיהי' אפשר לקבל את עוצם האור והגילוי (ע\"י הסרת העלם והסתר הערלה), אלא גם כדי לשלול יניקת החיצונים.\n<b>ויובן</b> בהקדם הביאור בענין איסור מלאכה בשבת, שהו\"ע השביתה מהמלאכה דעבודת הבירורים כיון שבשבת בורר אסור (כנ\"ל ס\"ג), שזהו לפי שבשבת נמשך ומתגלה אור עליון ביותר, ואם תהי' אז איזה מציאות לקליפות וחיצונים, אפילו באופן שפועלים בהם ענין של <b>בירור</b> (שזהו אופן מציאותם בימות החול ע\"פ התורה), אזי יהיו יכולים לקבל יניקה מהאור העליון שמתגלה בשבת. אך יש בחינה ששם לא אסרה תורה עשיית מלאכה (שזוהי הבחינה שלא שייך בה חילוק רשויות), שזהו מצד גילוי אור עליון נעלה עוד יותר, ששם אין תפיסת מקום כלל למציאות החיצונים. וזהו כללות החילוק שבין שבת למילה, שגילוי האור דיום השבת, עם היותו גילוי אור נעלה ביותר, הרי זה שייך עדיין לסדרהשתלשלות (שבעת ימי הבנין), ולכן מבחי' זו יש אפשרות שיהיו החיצונים יכולים לקבל יניקה (אם יהי' ענין של מלאכה), משא\"כ ענין המילה הוא גילוי אור נעלה יותר שלמעלה מכל סדר השתלשלות (שמיני), ששם אין תפיסת מקום כלל למציאות החיצונים. וזהו שמילה דוחה שבת, שנעשים אז כל המלאכות דמילה, כי, מצד גודל מעלת האור שאין בו תפיסת מקום כלל למציאות החיצונים, אין מקום לחשוש לענין של יניקה ע\"י מלאכת הבירור, ולאידך גיסא, מצד גודל מעלת האור, הרי המשכתו היא בדרך אתערותא דלעילא, ולא מצד עבודת התחתונים, וענין המלאכה (פעולת המילה) אינו אלא הסרת ההעלם וההסתר שיהי' אפשר לקבל את גודל האור.\n<b>וביאור</b> הענין בפרטיות יותר, דהנה, נתבאר לעיל (ס\"ג) שהבחי' שלא שייך בה חילוק רשויות היא בחי' א\"ק, שכולל את כללות העולמות. אך בבחי' א\"ק גופא יש חיצוניות א\"ק ופנימיות א\"ק, שהם כמו חיצוניות הכתר ופנימיות הכתר<sup data-n=\"1447\">43</sup>. דהנה, בחי' א\"ק הוא אדם דבריאה דכללות<sup data-n=\"1448\">44</sup>, וכפי שמביא רבינו הזקן<sup data-n=\"1449\">45</sup> בשם הרב המגיד, שענין א\"ק הוא מחשבה קדומה, מחשבה כללית ורצון כללי על כל העולמות. ומובן שענין זה (ששייך לעולמות) הוא רק בחי' החיצוניות. ועל בחי' זו נאמר כחשיכה כאורה, שלכן יכולה להיות משם יניקת החיצונים, כיון שבחי' זו הו\"ע הרצון על כללות העולמות, שבזה נכלל גם ענין הקליפות והחיצונים. אמנם, תכלית העבודה היא שתהי' גם המשכת בחי' פנימיות א\"ק ופנימיות הכתר, שמצד בחי' זו מתבטלת מציאות החיצונים לגמרי, כמ\"ש<sup data-n=\"1450\">46</sup> וכל אויביך יכרתו. ועז\"נ<sup data-n=\"1451\">47</sup> אם תגבי' כנשר גו' קינך משם אורידך נאום הוי', שגם כאשר תגבי' כנשר, שהו\"ע הגבהת החיצונים לקבל יניקה מחיצוניות הכתר וחיצוניות א\"ק (בחי' המחשבה הכללית על כל העולמות, שגם החיצונים בכלל זה), הנה משם אורידך, והיינו ע\"י העבודה דתורה ומצוות, שזהו שמסיים נאום הוי', דקאי על המצוות שנכללים ונרמזים בשם הוי', כדאיתא בתקו\"ז<sup data-n=\"1452\">48</sup> שהמצוות תלויות באותיות דשם הוי' כענבין באתכלא, שיש מצוות התלויות באות יו\"ד של שם הוי' וכו' עד לאות ה\"א אחרונהשל שם הוי', ולכן ע\"י המצוות ממשיכים מבחי' פנימיות הכתר ופנימיות א\"ק, ועי\"ז משם אורידך, להיות כל אויביך יכרתו. אמנם, כדי שתוכל להיות ההמשכה מבחי' פנימיות הכתר ופנימיות א\"ק, צריך להיות תחילה ענין הסרת הערלה, והיינו, שאע\"פ שהערלה אינה מבלבלת ואינה מונעת את הגילוי דבחי' חיצוניות א\"ק וחיצוניות הכתר (שהרי בבחי' זו נאמר כחשיכה כאורה, שלכן יכולה להיות משם יניקת החיצונים), מ\"מ, כאשר צריך להמשיך מבחי' פנימיות א\"ק ופנימיות הכתר (שזוהי התכלית כנ\"ל), הנה מצד עוצם מעלת גילוי זה אי אפשר להיות המשכתו אלא לאחרי הסרת הערלה.\n<b>וזהו</b> כללות ענין המילה, שהיא בבחי' היסוד, קו האמצעי, שמבריח מן הקצה אל הקצה, מהקצה העליון, בחי' פנימיות הכתר, עד לקצה התחתון, בחי' המלכות, וגם כפי שרגלי' יורדות מות<sup data-n=\"1453\">49</sup>, ולכן צריכים לשלול ב' האופנים דיניקת החיצונים, הן היניקה מחיצוניות המקיף, והן היניקה מצד ריבוי הצמצומים, שזהו סוף סדר ההשתלשלות. ומ\"ש בסידור שענין המילה מבטל יניקת החיצונים <b>מסוף</b> קו האמצעי (שזוהי היניקה שמצד ריבוי הצמצומים, ולא היניקה מחיצוניות המקיף), הרי זה לפי שגם היניקה מחיצוניות המקיף היא ע\"י ריבוי הצמצומים<sup data-n=\"1454\">50</sup>, כי, מצד חיצוניות המקיף, הרי אע\"פ שבבחי' זו נאמר כחשיכה כאורה, מ\"מ, אין החיצונים יכולים לקבל משם, מצד תוקף האור שמבטל את מציאותם, כי אם ע\"י ריבוי הצמצומים, שהאור יורד ומתצמצם בצמצום אחר צמצום עד שנמשך גם ללעו\"ז, קליפה וסט\"א.\nה) <b>ויש</b> להוסיף ולבאר הענין דב' סוגי הנסים והחיבור שביניהם (שזהו ע\"ד הענין דעירוב רשויות, החיבור וההמשכה מעלמא דאתכסיא לעלמא דאתגליא שנעשה ע\"י קו האמצעי, כנ\"ל), דהנה, מצינו גבי אחז (שאחז בתי כנסיות ובתי מדרשות כו'<sup data-n=\"1455\">51</sup>, היינו, שהי' אז מצב של העלם והסתר ביותר), שאמר לו ישעי', שאל<sup data-n=\"1456\">52</sup> לך אות מעם הוי' אלקיך (על ההבטחה בנוגע למפלה של צוררי ירושלים<sup data-n=\"1457\">53</sup>, באמרו, שיכול לבחור בא' מב' האופנים) העמק שאלה או הגבה למעלה. ואיתא בזהר<sup data-n=\"1458\">54</sup>, העמק שאלה דא אות ה' בתראה דבשמא קדישא, או הגבה למעלה דא את יו\"ד רישאדבשמא קדישא. וידוע המבואר בזה בארוכה בביאורי הזהר<sup data-n=\"1459\">55</sup> (ובתוספת ביאור ברשימות אדמו\"ר הצ\"צ<sup data-n=\"1460\">56</sup>), שישעי' הנביא נתן הברירה לאחז שיברור לו באיזה אופן יהי' לו הנס והישועה, אם ע\"י נס המלובש בטבע, שזהו\"ע העמק שאלה, מצד אות ה' אחרונה דשם הוי', או ע\"י נס שלמעלה מהטבע, שזהו\"ע הגבה למעלה, מצד אות יו\"ד דשם הוי', כדלקמן.\n<b>והענין</b> בזה, כמבואר שם<sup data-n=\"1461\">57</sup> שענין הנס המלובש בטבע נמשך מאות ה' אחרונה של שם הוי', ספירת המלכות, שהרי ענין הטבע נתהווה ע\"י ספירת המלכות שרגלי' יורדות מות, שיורדת ומתלבשת בבי\"ע לברר בירורים, וכמ\"ש<sup data-n=\"1462\">58</sup> ותקם בעוד לילה ותתן טרף לביתה, והיינו כמו עד\"מ הזאב שטורף הבהמה בשדה ומביאה לחורו, וקאי על ספירת המלכות שרגלי' יורדות לטרוף טרף, שהו\"ע בירור רפ\"ח ניצוצים, רפ\"ח עם הכולל בגימטריא טרף<sup data-n=\"1463\">59</sup>, ואח\"כ היא מעלה אותם למעלה. ולכן נקרא העמק שאלה, שיורדת ומתלבשת למטה מטה בעומק תחת עד לשאול (שאָלה (בקמץ), מלשון שאול). אך הנסים שלמעלה מדרך הטבע נמשכים מהקצה היותר נעלה, שזהו אות יו\"ד של שם הוי', שהוא הנקרא הגבה למעלה (ע\"ד שמים לרום<sup data-n=\"1464\">60</sup>), כי, אות ה' ראשונה של שם הוי', בחי' בינה<sup data-n=\"1465\">61</sup>, כיון שמתלבשת בעולם הבריאה<sup data-n=\"1466\">62</sup> (התחלת סדר השתלשלות עולמות בי\"ע), הרי אין זה הגובה האמיתי, אך אמיתית ענין הגובה (הגבה למעלה) הו\"ע אות יו\"ד דשם הוי', ספירת החכמה, שהיא נקודה בלבד, להיותה למעלה מסדר ההשתלשלות, ועד לקוצו של יו\"ד, שורש החכמה.\n[<b>ויש</b> לתווך עם משנת\"ל (ס\"א) שהנסים שלמעלה מדרך הטבע נמשכים משם הוי', כי, כללות שם הוי' הוא האות יו\"ד שבו, וכללות היו\"ד הוא קוצו של יו\"ד, שממנה מתחילה כתיבת היו\"ד. גם יש לתווך עם משנת\"ל בהשייכות דב' סוגי הנסים לענין מן העולם ועד העולם, עלמא דאתכסיא ועלמא דאתגליא, שהם בינה ומלכות, והיינו, שהנסים שלמעלהמהטבע שייכים לבחי' בינה, כי, ידוע בענין אימא עילאה מקננא בכורסיא בתלת ספירן עילאין<sup data-n=\"1467\">63</sup>, שבבינה מאירה גם ספירת החכמה, ועד שהתגלות עתיק היא בבינה<sup data-n=\"1468\">64</sup>].\n<b>וכללות</b> הענין בזה, שאע\"פ שבזמנו של אחז הי' העלם והסתר ביותר (כנ\"ל), מ\"מ, אמר לו ישעי' שיכול לשאול ולבחור לו ענין של נס, מלשון הרמה<sup data-n=\"1469\">65</sup>, כמו הרימו נס<sup data-n=\"1470\">66</sup>, שהו\"ע של התרוממות בגילוי אלקות, לא רק מבחי' האלקות המלובש ונעלם ומוסתר בטבע, אלא גם מבחי' האלקות כפי שהוא למעלה מן הטבע.\n<b>ומסיים</b> בביאורי הזהר שם, שאחז לא רצה שיתקדש שם שמים, ועל כן לא רצה כלל לשאול אות, ולא בחר בא' מב' אופנים הנ\"ל (וכמשנת\"ל שבזמנו של אחז הי' העלם והסתר גדול ביותר, ולא רצה להניח שיהי' גילוי אלקות באיזה אופן שהוא), ולכן אמר לו ישעי' שבעל כרחם יתן להם הקב\"ה אות, אלא שיהי' האות מבחי' שם אד', שלכן יהי' הנס ע\"י התלבשות בנוהג העולם כו', וכסיום הנבואה<sup data-n=\"1471\">67</sup>: לכן יתן אד' הוא לכם אות הנה העלמה הרה ויולדת בן וגו', דעלמה היינו בחי' העלם, והיינו, שהנס נמשך באופן של העלם והסתר.\nו) <b>וביאור</b> הענין בפרטיות יותר, דהנה, גם בנסים המלובשים בטבע, שנמשכים מבחי' העמק שאלה, יש כמה אופנים<sup data-n=\"1472\">68</sup>. וכידוע שיש ניסים המלובשים בטבע באופן שאין בעל הנס מכיר בניסו, כדאיתא בגמרא<sup data-n=\"1473\">69</sup> מאי דכתיב<sup data-n=\"1474\">70</sup> עושה נפלאות (גדולות) לבדו כו' אפילו בעל הנס אינו מכיר בנסו, והם הנסים שבכל יום ויום שאין מכירים בהם, וכפי שרואים בפרטיות בענין עסק הפרנסה, כמאמר אדמו\"ר מהר\"ש<sup data-n=\"1475\">71</sup> שכאשר מתבוננים בענין הפרנסה בזמן הזה רואים שהוא כמו ענין המן, שבאמת הרי זה ענין שלמעלה מדרך הטבע, אלא שהוא מכוסה בדרך הטבע. אמנם, בנסים אלו ההתלבשות בדרך הטבע היא באופן של העלם והסתר ביותר (עוד יותר מהנס דמרדכי ואסתר שהי' בפורים שהי' ג\"כ מלובש בטבע),שהנס מושקע לגמרי בלבושי הטבע. ולמעלה מזה הם הנסים המלובשים בטבע ע\"ד נס פורים, דאף שביטול הגזירה הי' באופן שאחשורוש עצמו ביטל האגרות הראשונות כו', ע\"י דרכים טבעיים, מ\"מ, הי' <b>ניכר</b> בזה ענין הנס, ועד שראו כל אפסי ארץ גו'<sup data-n=\"1476\">72</sup>, שלכן הלא הם כתובים על ספר דברי הימים למלכי מדי ופרס<sup data-n=\"1477\">73</sup>. אך ישנו סוג נסים נעלה יותר מב' סוגי נסים הנ\"ל המלובשים בטבע, הגבה למעלה, שהו\"ע הנסים שלמעלה מדרך הטבע, כנ\"ל.\n<b>אמנם</b> תכלית הכוונה היא שלא ישארו שני סוגי נסים, נסים לשון רבים, נפרדים זמ\"ז, העמק שאלה בפ\"ע או הגבה למעלה בפ\"ע, אלא באופן שגם בהעמק שאלה יומשך הגבה למעלה. ובפרט ע\"פ מ\"ש הרמ\"ז<sup data-n=\"1478\">74</sup> בפירוש העמק שאלה, שלשון העמק הוא מלשון עמיקא דבירא<sup data-n=\"1479\">75</sup>, והיינו, שהכח לירידה דספירת המלכות (העמק שאלה כפשוטו) הוא מבחי' החכמה כו' (עמיקא דבירא), וכידוע שאבא יסד ברתא<sup data-n=\"1480\">76</sup>. והצ\"צ מוסיף<sup data-n=\"1481\">77</sup>, שענין שאלה י\"ל ע\"ד אימא אוזיפת מאנהא לברתא<sup data-n=\"1482\">78</sup> (כמבואר הענין במ\"א בארוכה<sup data-n=\"1483\">79</sup>). והיינו, שבנסים המלובשים בטבע יש גם ענין שלמעלה מהטבע, כי לולי זאת לא יתכן שיהי' בטבע ענין של נס. ועד כדי כך, שבהנס המלובש בטבע באופן של העלם והסתר שמושקע לגמרי בלבושי הטבע, נמשכת ומתגלה בחי' נעלית יותר אפילו מהגבה למעלה, כמרומז בהנבואה הנה העלמה הרה ויולדת בן גו', דאף שהנס הוא באופן של העלם והסתר (כנ\"ל), הנה לאח\"ז נעשה הענין דיולדת בן, שנקרא בכו\"כ שמות ותוארים, פלא יועץ אל גיבור אבי עד שר שלום לםרבה המשרה וגו'<sup data-n=\"1484\">80</sup>, שזהו ענינו של משיח<sup data-n=\"1485\">81</sup>.\nז) <b>וביאור</b> הענין בעבודת האדם יובן ע\"פ משנ\"ת במאמר שלפנ\"ז<sup data-n=\"1486\">82</sup> בענין כי מראש צורים אראנו ומגבעות אשורנו<sup data-n=\"1487\">83</sup>, שכללות ענין העבודה צריך להיות בהקדמת ענין המסירת נפש, מראש צורים,וכפתגם<sup data-n=\"1488\">84</sup> כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע דענין המס\"נ הוא אַזוי און ניט אַנדערש, שזוהי החלטה קיימת והחלטית ונצבת לעד, באופן של אמת לאמיתו, שזהו ענינו של קו האמצעי<sup data-n=\"1489\">85</sup>, שנמשך מפנימיות הכתר, ובעבודת האדם הו\"ע פנימיות הנפש, בחי' היחידה. אמנם, לאחרי הקדמת המס\"נ צריכה להיות עבודה מסודרת בכחות הפנימיים, שזהו\"ע מגבעות אשורנו, באופן של הסתכלות וכוונה וסדר מסודר במעשה בפועל (שהמעשה הוא העיקר<sup data-n=\"1490\">86</sup>), ודוקא ע\"י עבודה זו נעשה הענין דאשורנו, מקרוב. וכן הוא גם בנוגע לגילוי המשיח שנעשה ע\"י כללות העבודה, דכתיב בי'<sup data-n=\"1491\">87</sup> הנה ישכיל עבדי ירום ונשא וגבה מאד, דקאי על חמש העליות שבספירת המלכות<sup data-n=\"1492\">88</sup>, עד לגבה <b>מאד</b>, שזהו למעלה מבחי' הגבה למעלה, כי, אף שמאד הוא אותיות אדם, הרי זה בצירוף דמאד<sup data-n=\"1493\">89</sup>, שלכן הרי זה למעלה מאדה\"ר, והו\"ע בחי' היחידה<sup data-n=\"1494\">90</sup>. ומ\"מ נאמר הנה ישכיל עבדי<sup data-n=\"1495\">91</sup>, שמגיעים לזה דוקא ע\"י העבודה דבחי' עבדי, וכמ\"ש<sup data-n=\"1496\">92</sup> אל תירא עבדי יעקב, שזהו ע\"ד הענין דמגבעות אשורנו דוקא. וזהו גם הדיוק בכתוב מגיד דבריו ליעקב חוקיו ומשפטיו לישראל, כמשנת\"ל (ס\"ב) שהו\"ע ההמשכה בקו האמצעי, שגם בזה הדיוק הוא יעקב דוקא (אף שמוסיף אח\"כ גם ישראל), שהו\"ע עבודת עבד. וכן הוא גם בפסוק שבו מדובר אודות גילוי אור המשיח, כמ\"ש<sup data-n=\"1497\">93</sup> אראנו ולא עתה אשורנו ולא קרוב דרך כוכב מיעקב וקם שבט מישראל, דאף שסוכ\"ס יהי' וקם שבט מישראל, כמ\"ש התרגום<sup data-n=\"1498\">94</sup> ויתרבא משיחא מישראל (שאז יהי' העולם כולו במדריגת ישראל), הרי כל זה נעשה ע\"י הקדמת הענין דדרך כוכב מיעקב דוקא, שזוהי העבודה דעבד (יעקב עבדי), הנה ישכיל עבדי. וכן הוא בכללות העבודה בכל יום מימי הגלות [שהרי בכל יום ויום חייב אדם לראות את עצמו כאילו הוא יצא היום ממצרים<sup data-n=\"1499\">95</sup>, וכיון שכימי צאתך מארץ מצרים אראנו נפלאות<sup data-n=\"1500\">96</sup>,הרי מובן שזהו ענין ביאת המשיח שישנו בעבודת כל יום], שתחילה צ\"ל מראש צורים אראנו, שהו\"ע המסירת נפש, אבל אח\"כ צ\"ל מגבעות אשורנו, שהו\"ע עבודה מסודרת דוקא, כנ\"ל.\nח) <b>וע\"י</b> העבודה דמראש צורים אראנו ומגבעות אשורנו, פועלים שיהי' גילוי המשיח (דרך כוכב מיעקב וקם שבט מישראל) באופן דאראנו ואשורנו, אע\"פ שבזמן ההוא (כשנאמרה נבואה זו) נאמר על זה אראנו ולא עתה אשורנו ולא קרוב. ובפרט שנוסף על כל עניני העבודה שהיו במשך כל הדורות, היו בינתיים גם עניני נסים כו', ועד להאותות ומופתים שהיו בזמנו של כ\"ק מו\"ח אדמו\"ר נשיא דורנו, כמבואר בתניא<sup data-n=\"1501\">97</sup> (בפירוש מארז\"ל<sup data-n=\"1502\">98</sup> בתחלה עלה במחשבה לברוא את העולם במדת הדין ראה שאין העולם מתקיים שיתף עמו מדת הרחמים) ענין התגלות אלקות ע\"י צדיקים ואותות ומופתים שבתורה, דהגם שהנסים היו בדרכי הטבע, מ\"מ, הי' זה באופן שראו כל אפסי ארץ שזהו\"ע שלמעלה מן הטבע לגמרי, וכדברי כ\"ק מו\"ח אדמו\"ר<sup data-n=\"1503\">99</sup>, בעל השמחה, שזהו\"ע של הצלת התורה, שהוא למעלה משמחת תורה ולמעלה משמחת בני תורה, ובזה הכל שוין, ומצד זה נדרש ענין של מס\"נ, שיהי' לימוד התורה ללא פשרות, וכיון שהלימוד מביא לידי מעשה, נעשה גם קיום המצוות ללא פשרות, אַזוי און ניט אַנדערש (כנ\"ל ס\"ז). ועל זה אומרים ברוך שעשה נסים לאבותינו בימים ההם בזמן הזה, היינו, שמבקשים שעד\"ז יהי' גם בזמן הזה. ועוד זאת, דכיון שניתוספה העבודה בינתיים, יהי' זה באופן נעלה יותר, שיהי' העירוב של כל סוגי הנסים להיות מהם נס אחד וסוג אחד, שעם היותו בטבע, הנה בטבע גופא נעשה ענין של הצלת התורה, שלמעלה משמחת תורה ושמחת בני תורה, שמעורר וממשיך מס\"נ בפועל, כפי שהי' בימים ההם, ובמילא פעל גם על כל ההולכים בעקבותיו וכל השייכים אליו, בתוככי כלל ישראל, שתהי' העבודה ללא פשרות, אַזוי און ניט אַנדערש. ועי\"ז פועלים שעתה וקרוב יהי' דרך כוכב מיעקב, הנה ישכיל עבדי, ולאח\"ז וקם שבט מישראל, עד וגבה מאד, בביאת מלכא משיחא, בעגלא דידן, למטה מעשרה טפחים.\n**********",[["1405","1","מאמר זה הוא המשך למאמר שלפניו ד\"ה כי מראש צורים די\"ב תמוז (לעיל ע' 172 ואילך)."],["1406","2","נוסח ברכת הנסים דחנוכה ופורים."],["1407","3","ראה ד\"ה ברוך שעשה נסים תרס\"ד (סה\"מ תרס\"ד (הוצאת קה\"ת תשנ\"ד) ע' קכט. שם ע' קמב ואילך). וש\"נ. וראה גם ד\"ה הנ\"ל תשט\"ו (תו\"מ סה\"מ כסלו ע' קז ואילך)."],["1408","4","ד\"ה כי מראש צורים הנ\"ל (לעיל ע' 182 ואילך)."],["1409","5","מורה נבוכים ח\"ג פ\"נ."],["1410","6","חגיגה יב, א. ב\"ר פ\"ה, ח. פמ\"ו, ג."],["1411","7","ב\"ר פמ\"ו, ג. פרש\"י לך יז, א."],["1412","8","תהלים פד, יב. וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא שעהיוה\"א פ\"ד</a>. אוה\"ת לתהלים (יהל אור) עה\"פ. ובכ\"מ."],["1413","9","תהלים קו, מח."],["1414","10","בהבא לקמן – ראה המשך מצה זו תר\"ם פנ\"ד (סה\"מ תר\"ם ח\"א ע' רלח ואילך)."],["1415","11","ראה מאורי אור מערכת ע אות כז."],["1416","12","עץ חיים שער יח (שער רפ\"ח ניצוצין) פ\"ב."],["1417","13","ראה מגלה עמוקות אופן קמד."],["1418","14","ראה תקו\"ז תכ\"ב (סז, ב)."],["1419","15","ראה ב\"ר רפע\"ו. ועוד."],["1420","16","ע\"פ תרומה כו, כח."],["1421","17","זהר ח\"ב קעה, ב."],["1422","18","בהבא לקמן – ראה המשך מצה זו תר\"ם פנ\"ה* (סה\"מ תר\"ם ח\"א ע' רמ ואילך)."],["1423","19","תהלים קמז, יט."],["1424","20","עם דא\"ח סה, א.\n*) <b>להעיר</b>,<b> שמאמר זה נאמר </b>\"<b>על ברית מילה</b>\"<b> של כ\"ק אדמו\"ר מוהריי\"צ – י\"ט תמוז תר\"ם </b>(המו\"ל)."],["1425","21","תהלים שם, טז."],["1426","22","ראה פסחים נו, א."],["1427","23","תולדות כה, כז."],["1428","24","זח\"א קסז, ב – הובא בהמשך הנ\"ל רפנ\"ב (ע' רלד)."],["1429","25","אדר\"נ פ\"ב."],["1430","26","לך יז, א. וראה תוספתא נדרים פ\"ב. תנחומא לך טז-יז."],["1431","27","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380164\" data-slug=\"likkutei-torah\" data-id=\"4001380164\">לקו\"ת תזריע כא, א</a>."],["1432","28","ב\"ר פי\"א, ה."],["1433","29","יתרו כ, ט. תשא לד, כא."],["1434","30","הובאה בדרשות ר' יהושע אבן שועב פ' וישב, ובספר מנחה בלולה. וראה מכילתא דרשב\"י יתרו כ, ט. וראה גם ד\"ה ויקהל תשי\"ב (תו\"מ ח\"ה ע' 70). <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171245\" data-slug=\"likkutei-sichot\" data-id=\"1300171245\">לקו\"ש חי\"ז ע' 245</a> הערה 20. וש\"נ."],["1435","31","משנה שבת עג, א. גמרא שם עד, א. ראה תו\"א חיי שרה טו, ג. בשלח סה, סע\"ב ואילך."],["1436","32","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310038\" data-slug=\"tanya\" data-id=\"3401310038\">תניא ספל\"ג</a>."],["1437","33","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380162\" data-slug=\"likkutei-torah\" data-id=\"4001380162\">לקו\"ת שם כ, סע\"ג</a> ואילך. סידור (עם דא\"ח) שער המילה קלט, א ואילך. אוה\"ת ויקרא ח\"ב ע' תקב ואילך. סהמ\"צ להצ\"צ מצות מילה ט, ב ואילך."],["1438","34","משנה שבת קל, א. גמרא שם קלב, א."],["1439","35","סה\"מ תרע\"ח ע' ער."],["1440","36","תזריע יב, ג."],["1441","37","ראה זהר ח\"ג מד, א (ברע\"מ). וראה גם ויק\"ר פכ\"ז, י."],["1442","38","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381010\" data-slug=\"likkutei-torah\" data-id=\"4001381010\">לקו\"ת האזינו עא, ד</a>. ועוד."],["1443","39","בשלח טו, טז."],["1444","40","תהלים קלט, יב."],["1445","41","איוב לה, ז."],["1446","42","משלי ל, כח. ראה ב\"ר פס\"ו בסופה. עמק המלך שער ו פמ\"ה. שער יד פ\"ט ופצ\"ח."],["1447","43","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380163\" data-slug=\"likkutei-torah\" data-id=\"4001380163\">לקו\"ת תזריע כ, ד</a>."],["1448","44","ראה עץ חיים שער א (דרוש עגולים ויושר) ענף ד. לקו\"ת בהר מג, ד. מאמרי אדה\"ז ענינים ע' א ואילך. אוה\"ת ענינים ע' עז ואילך."],["1449","45","ראה אוה\"ת ענינים ע' פד."],["1450","46","מיכה ה, ח. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370486\" data-slug=\"torah-or\" data-id=\"3901370486\">תו\"א יתרו קט, ד</a>. לקו\"ת חוקת נט, א."],["1451","47","עובדי' א, ד. וראה תו\"א מקץ לו, ד."],["1452","48","בהקדמה (ב, א). שם ריש תיקון ב (יח, סע\"א). וראה לקו\"ת פקודי ג, ב."],["1453","49","משלי ה, ה."],["1454","50","ראה המשך תער\"ב ח\"א ע' שמז."],["1455","51","פתיחתא דאסת\"ר יא."],["1456","52","ישעי' ז, יא."],["1457","53","שם, ד ואילך."],["1458","54","ח\"ג בתחלתו (ב, א)."],["1459","55","לאדמו\"ר האמצעי – סג, סע\"א."],["1460","56","ביאורי הזהר ח\"א ע' שטו ואילך. וראה גם מאמרי אדמו\"ר הזקן תקס\"ה ח\"א ע' שסח ואילך. מאמרי אדמו\"ר האמצעי הנחות תקע\"ז ע' יב ואילך."],["1461","57","ראה גם ביאורי הזהר שם ע' שיז – שע\"י ב' אופני נסים אלו רצה ישעי' לתקן את אחז ממה שפנה לצד החיצונים כו', ששרש יניקתם הוא מב' האופנים שנתבארו לעיל (<b>המו\"ל</b>)."],["1462","58","משלי לא, טו."],["1463","59","מקדש מלך לזח\"ג ס, א. הוספות לתו\"א קי, א."],["1464","60","משלי כה, ג."],["1465","61","ראה עץ חיים שער ג (שער סדר אצילות למהרח\"ו) פ\"א. שער מב (שער דרושי אבי\"ע) פ\"א. ובכ\"מ."],["1466","62","ראה עץ חיים שער ג שם."],["1467","63","תקו\"ז ת\"ו (כג, א)."],["1468","64","זח\"ג קעח, א."],["1469","65","פרש\"י יתרו כ, יז. ד\"ה הנ\"ל תרס\"ד (סה\"מ תרס\"ד (הוצאת קה\"ת תשנ\"ד) ע' קלב). וש\"נ."],["1470","66","ישעי' סב, ט."],["1471","67","שם ז, יד."],["1472","68","ראה אוה\"ת לתהלים (יהל אור) ע' קנד. ד\"ה כימי צאתך תשל\"ח פ\"ג (סה\"מ מלוקט ח\"ה ע' שו ואילך)."],["1473","69","נדה לא, א."],["1474","70","תהלים עב, יח."],["1475","71","סה\"מ תרנ\"א ע' קצו. תש\"ט ע' 21."],["1476","72","תהלים צח, ג. מגילה יא, רע\"א. וראה אוה\"ת מג\"א ע' קמב."],["1477","73","אסתר יו\"ד, ב."],["1478","74","לזהר שבהערה 53."],["1479","75","לשון הזהר – ח\"ב סג, ב."],["1480","76","זח\"ג רנח, א."],["1481","77","ביאורי הזהר שם ע' שטו."],["1482","78","זח\"א ב, א."],["1483","79","ראה שער היחוד לאדמו\"ר האמצעי פמ\"א ואילך (קלז, סע\"א ואילך)."],["1484","80","ישעי' ט, ה-ו."],["1485","81","ראה רד\"ק עה\"פ. ועוד."],["1486","82","ד\"ה כי מראש צורים די\"ב תמוז ספ\"ב ואילך (לעיל ע' 175 ואילך)."],["1487","83","בלק כג, ט."],["1488","84","סה\"ש תש\"ה ע' 112. וראה שיחת י\"ב תמוז ס\"ט (לעיל ע' 195). י\"ב תמוז תשל\"ה. וראה גם שיחת ב' ניסן תש\"ח (ספר השיחות תש\"ח ע' 195)."],["1489","85","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310018\" data-slug=\"tanya\" data-id=\"3401310018\">תניא ספי\"ג</a>."],["1490","86","אבות פ\"א מי\"ז."],["1491","87","ישעי' נב, יג."],["1492","88","ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600265\" data-slug=\"or-hatorah-hb\" data-id=\"8316600265\">אוה\"ת נ\"ך</a> עה\"פ (ח\"א ע' רסה ואילך). סה\"מ תרל\"ה ח\"א ע' רסה-רסו. סה\"מ תרח\"ץ ע' ר."],["1493","89","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380144\" data-slug=\"likkutei-torah\" data-id=\"4001380144\">לקו\"ת צו יז, א</a>. ובכ\"מ."],["1494","90","ראה רמ\"ז לזהר ח\"ב מ, ב. ח\"ג רס, ב. מקומות שצויינו בהערה 89. וש\"נ."],["1495","91","להעיר מביאוה\"ז פ' וישב לאדמו\"ר האמצעי (כב, סע\"ב ואילך), ולאדמו\"ר הצ\"צ (ח\"א ע' קיח ואילך)."],["1496","92","ישעי' מד, ב. ירמי' מו, כז-כח. וראה המשך תרס\"ו ע' רכה. ובכ\"מ."],["1497","93","בלק כד, יז."],["1498","94","וראה גם רמב\"ם הל' מלכים פי\"א ה\"א. רמב\"ן בלק עה\"פ. ועוד."],["1499","95","<a class=\"ft-cite\" href=\"#/read/tanya/3401310052\" data-slug=\"tanya\" data-id=\"3401310052\">תניא רפמ\"ז</a>."],["1500","96","מיכה ז, טו."],["1501","97","שעהיוה\"א פ\"ה."],["1502","98","הובא בפרש\"י בראשית א, א."],["1503","99","שיחת י\"ב תמוז תש\"ד (סה\"ש תש\"ד ע' 153 ואילך). וראה שיחת י\"ב תמוז ס\"ד (לעיל ע' 189)."]]],[1400350025,"– במחנה-קיץ \"גן ישראל\", סוואַן-לייק, ניו-יארק<sup data-n=\"1504\">*</sup> –\nבלתי מוגה\n[כ\"ק אדמו\"ר שליט\"א נטל ידיו הק' לסעודה. אח\"כ אמר \"לחיים\", וצוה לחלק לילדים \"סודה\" עבור אמירת \"לחיים\"].\n<b>א</b>. הדברים שאדבר עתה – מיועדים עבור הילדים שנמצאים במחזור זה, וגם עבור הילדים שיהיו בשני המחזורים הבאים, בתוככי כל בנ\"י, כל ילדי ישראל,\n– ואהי' חייב הכרת תודה לאלו שימסרו את הדברים לילדי ישראל בכל מקום שהם –\nכיון שדברים אלו הם דברי רבותינו, המיודעים לכל ילד יהודי באשר הוא שם, הן ילד והן ילדה, הן צעירים והן מבוגרים.\nאלו שאינם מבינים אידיש – מסתמא ימסרו להם תוכן הדברים בשפה שהם מבינים.\n*\n<b>ב</b>. נמצאים אנו עתה במחנה-קיץ (\"קעמפּ\") הנקרא \"גן ישראל\", שפירושו, גן של יהודים, אשר, כל אחד מהם נקרא בשם ישראל.\nבחירת השם \"(גן) <b>ישראל</b>\"<sup data-n=\"1505\">1</sup> – אף שיהודים נקראים בשמות נוספים, כמו יעקב וכיו\"ב – היא גם בגלל ש\"ישראל\" הוא שמו של <b>הבעל-שם-טוב</b>, שגילה את תורת החסידות ואת ההנהגה החסידית כיצד להתנהג בעולם, ומסר זאת לכל בנ\"י, באופן שקימעא קימעא יגיעו הדברים לכל אחד מישראל, שיתנהג באופן כזה.\nוכיון שצדיקים הם תמיד חיים<sup data-n=\"1506\">2</sup>, עי\"ז שלומדים תורתם ומתנהגים ע\"פ הוראותיהם<sup data-n=\"1507\">3</sup> – הרי השם \"גן ישראל\" הוא שם חי (\"אַ לעבעדיקער נאָמען\"), ע\"ש \"ישראל\" חי (\"אַ לעבעדיקער ישראל\"), שהוא הבעש\"ט.ובפרט שהזמן מתאים לכך – שהרי בשנה זו מלאו מאתיים שנה מאז שנשמתו של הבעש\"ט נפרדה מגופו, אבל – כמו כל נשמה של מנהיג בישראל – באופן שנשארה בין תלמידיו<sup data-n=\"1508\">4</sup>.\nולכן, כאשר מזכירים \"תורה\" שלימד הבעש\"ט, והולכים בדרכים שהורה הבעש\"ט – אזי נמצא הבעש\"ט עם כל אחד מאתנו, ועוזר לנו ללכת בדרכים שגילה, ונתן כח ובירך שילכו בהם, עד שיבוא משיח צדקנו ויוציא אותנו מהגלות, שאז הנה גם גופו של הבעש\"ט יקום לתחי', ונשמתו תתלבש בגופו, וכולנו יחד נלך אל הגאולה האמיתית לקראת משיח צדקנו.\nאלא, שכדי לזכות ולהגיע לזה – צריכים להתנהג ע\"פ הוראותיו של הבעש\"ט.\n<b>ג</b>. בודאי הנכם יודעים המסופר אודות הבעש\"ט<sup data-n=\"1509\">5</sup> ע\"י כ\"ק מו\"ח אדמו\"ר נשיא דורנו,\n– ולהעיר שעומדים אנו עתה בתוך שלשה ימים להגאולה שלו, לאחרי שאסרוהו בגלל שהתעסק בהפצת התורה בין בנ\"י וילדי ישראל במיוחד, אך ע\"י תוקף אמונתו בהקב\"ה, הצילו הקב\"ה ויצא מן המאסר, ומאז הנה בימים אלו, י\"ב-י\"ג תמוז, והימים הסמוכים אליהם (כולל יום זה שהוא יום השלישי מי\"ג תמוז שחל ביום ששי), חוגגים את גאולתו של הרבי, שמשמעות הדברים היא שנלך בדרכים שהורנו הרבי, שהם הדרכים של הבעש\"ט –\nשעוד לפני שלמד תורה עם הגדולים, התחיל ללמוד תורה עם ילדי ישראל – הוליכם לחדר, ולימדם לומר \"מודה אני\" ו\"שמע ישראל\", ולענות \"ברוך הוא וברוך שמו\", \"אמן\" ו\"אמן יהא שמי' רבא\",\nואמר אח\"כ, שהשנים הטובות ביותר של נחת-רוח ותענוג היו אותם השנים שבהם הי' לומד עם הילדים הקטנים, מוליך ומלווה אותם אל החדר, ומחזירם מהחדר לבתיהם.\nוכל זה מספרים <b>לנו</b> – כדי שכל הילדים ידעו ויזכרו, שבעניית \"אמן יהא שמי' רבא\", מלווה אותם כח של קדושה מהקב\"ה, ומסייע להם לילך לחדר ולחזור מהחדר מתוך בריאות, וללמוד ולהצליח בלימודים בהיותם בחדר.<b>ד</b>. אחת ההוראות של הבעש\"ט<sup data-n=\"1510\">6</sup>, אשר, באופן כזה נהגו גם תלמידיו, ורבותינו נשיאינו עד לנשיא דורנו, כ\"ק מו\"ח אדמו\"ר, היא:\nאמרו רז\"ל<sup data-n=\"1511\">7</sup> \"איזהו חכם הלומד מכל אדם\". וקשה, האם כל אדם מלמד הוא, וכי כל אדם יש לו את הסגולות ללמד? אך הענין הוא, שמהצדיק לומדים \"ועשה טוב\", ומהרשע לומדים \"סור מרע\". וזהו \"הלומד מכל אדם\", שמכל אדם, בין צדיק ובין רשע ח\"ו, אפשר וצריכים ללמוד.\nכלומר: בכל פעם שפוגשים יהודי – הנה כאשר פוגשים יהודי צדיק, שמתנהג כדבעי, אזי ילד חכם לומד ממנו שגם הוא צריך להתנהג בדרכים הטובות שבהם נוהג הצדיק שפגש בו; וכמו\"כ כאשר פוגשים מי שאינו צדיק, אלא הפכו, רשע – הרי זה לימוד שלעולם לא יעשה את הדברים הבלתי-טובים וההנהגות הבלתי-רצויות שבהם מתנהג הרשע, כך, שיש אפשרות ללמוד מכל יהודי שפוגשים בו, הן יהודי צדיק שמתנהג כרצונו של הקב\"ה, והן יהודי שלעת-עתה אינו יודע עדיין אודות הדרכים הטובות ולכן אינו עושה דברים טובים.\nוזהו גם לימוד עבורכם – שגם אתם תנהגו בדרך זו, להתבונן מסביבכם ולהשתדל לעשות את כל הדברים הטובים שנעשים ע\"י האנשים שבסביבתכם, ולהזהר ולהשמר שלא לעשות את הדברים הלא-טובים שנעשים ע\"י אנשים לא-טובים.\nואז תגדלו להיות \"חכמים\" – כפי רצונו של הבעש\"ט, כך, שההורים שלכם ואלו שמתעסקים עמכם ירוו מכם נחת אמיתי.\n*\n<b>ה</b>. והנה, לאחרי הבעש\"ט (לאחרי שנשמתו נפרדה מגופו, כנ\"ל ס\"ב), מילא את מקומו תלמידו, שנקרא הרב המגיד ממעזריטש, שהוסיף לבאר בעומק יותר הוראה הנ\"ל שצריכים ללמוד מכל אדם – שקאי לא רק על יהודי, אלא גם על כל אדם:\nוז\"ל תורת הרב המגיד<sup data-n=\"1512\">8</sup>:\n\"והי' בית עשו לקש<sup data-n=\"1513\">9</sup>, הנה אמרו רז\"ל<sup data-n=\"1514\">10</sup> כל מקום שנאמר והי' הוא לשון שמחה, ולכאורה, זו שיהי' בית עשו לקש, והלוא אין בה ניצוצותכלל כמו בדבר מאכל, אך לזה הקש ראוי, כשתשרפנו ונעשה אפר ותשפוך האפר בשדה, אזי יגדיל צמחים, שיהיו ניצוצות קדושה בודאי מהם כו'\".\nוהענין בזה:\n\"בית עשו\" – יודעים אתם שקאי על כל אלו שלוחמים נגד יהודים ויהדות, תורה ומצוות, כמו אביהם, עשו הראשון, שנלחם נגד יעקב.\nועל זה אומר הנביא דבר המשמח – \"והי' (לשון שמחה) בית עשו לקש\".\nולכאורה:\n\"קש\" הוא אמנם דבר חלש, אבל אעפ\"כ, הרי זה דבר שישנו במציאות, יש לו תפיסת מקום, ואפשר להפיק ממנו תועלת, שהרי יכולים לייצר מקש כמה דברים שהאדם יוכל להשתמש בהם, וכפי שמביא המגיד שכאשר שורפים קש ועושים ממנו אפר ושופכים בשדה, אזי תהי' תועלת בצמיחת וגידול פירות טובים.\nואינו מובן: מהי הבשורה המשמחת בכך שאלו שלוחמים נגד בנ\"י יהי' מהם דבר טוב, כמו \"קש\" – הרי היתה יכולה להיות שמחה גדולה יותר אילו לא היתה מציאותם כלל?!\nאך הענין הוא – שאפילו אינו-יהודי, ואפילו מי שלוחם נגד יהודים ויהדות, הנה לפעמים אפשר ללמוד ממנו דבר טוב (בדוגמת ה\"קש\" שכאשר שורפים אותו ושופכים בשדה אזי צומחים פירות טובים), וזוהי השמחה שבדבר – שאפילו דבר שלוחם נגד יהדות, מביא תועלת, שלמדים ממנו הוראה קדושה בנוגע להליכה בדרכי השם.\n<b>ו</b>. וזהו גם תוכן הסיפור<sup data-n=\"1515\">11</sup>, שהבעש\"ט בעצמו, לאחרי התגלותו כאדם היותר גדול וקדוש בדורו, למד מגוי, להבדיל, הוראה בעבודת השם:\nפעם אחת ישב הבעש\"ט עם תלמידיו בבית-הכנסת ובבית-המדרש ועסקו בתורה או בתפלה, וברחוב הסמוך עבר גוי עם עגלה, וכיון שברחוב הי' בוץ רב, לא היתה העגלה יכולה להמשיך לנסוע, ושקעה בבוץ. נגש הגוי לחלון בית-הכנסת שבו ישבו הבעש\"ט ותלמידיו, הכניס את ראשו מבעד לחלון, וביקש שיעזרו לו להוציא את העגלה מן הבוץ. כיון שהעגלה היתה כבדה, והבוץ הי' גדול – השיבו התלמידים שאיןבכחם להוציא את העגלה מהבוץ העמוק. וענה להם הגוי – בשפה האוקריינית – \"מאָזשעש דאַ ניע חאָטשעש\", שפירושו: הנך <b>יכול</b>, אך <b>אינך רוצה</b>, וכיון שאינך רוצה, אזי נדמה לך שאינך יכול.\nואח\"כ הסביר הבעש\"ט לתלמידיו, שהדברים ששמעו מהגוי אינם במקרה, אלא יש ללמוד מזה הוראה בעבודת השם:\nכאשר מצווים ילד יהודי ללמוד יותר חומש, משניות, דינים או קריאה (\"עברי\"), ועד\"ז אצל מבוגרים, בנוגע ללימוד גמרא עם תוספות, רמב\"ם, שו\"ע, חסידות וענינים עמוקים בחסידות (\"גאָר טיפע חסידות\") – הנה לפעמים נדמה לו <b>שאין לו כח</b>, כיון שהוא עייף.\nהנה על זה אומר הבעש\"ט, שצריכים ללמוד מדבריו של הגוי, להבדיל, \"מאָזשעש דאַ ניע חאָטשעש\", היינו, שהקב\"ה נותן <b>כחות</b> לעשות את כל הדברים הטובים, אלא, כיון שלא רוצים לעשות, בגלל שמקשיבים ליצה\"ר, אזי נדמה שאין יכולים לעשות.\nזוהי איפוא דוגמא להאמור לעיל, שאפילו מ\"בית עשו\", מגוי להבדיל, יכול לצמוח פרי טוב – לימוד והוראה להטיב את ההנהגה בדרכי השם.\n<b>ז</b>. והנה, לאחרי שנשמתו של המגיד נפרדה מגופו, אזי נעשה המנהיג והנשיא דבנ\"י אחד מתלמידיו, ראש התלמידים – רבינו הזקן, שהמשיך להפיץ יותר את תורותיו והוראותיו של הבעש\"ט, והוסיף לבאר אותם בהרחבת הביאור, כולל גם כיצד לתרגם וליישם את הדברים באופן ההנהגה בחיי היום-יום.\nומהענינים העיקריים בזה – שעבודת השם צריכה להיות מתוך אהבה ויראה, כי, \"בלא דחילו ורחימו לא פרחא לעילא\"<sup data-n=\"1516\">12</sup>.\nובהמשך להאמור לעיל:\nכל מה שרואים ולמדים הוראה ומחליטים להתנהג באופן מסויים – הרי זה צריך להעשות מתוך רגש של <b>חום ואהבה</b> כלפי ההנהגה הטובה בדרכי התומ\"צ; ועד\"ז בנוגע להלימוד ד\"סור מרע\" שלמדים מהרשע (כנ\"ל ס\"ד) – שצריך להיות מתוך רגש של <b>יראה</b> מפני הדברים הבלתי-רצויים.\nאבל כאשר עושים זאת ללא רגש של אהבה ויראה, אין זה פועלומשפיע כפי שהי' יכול לפעול ולהשפיע, ו\"לא פרחא לעילא\", אלא נשאר למטה, ללא זיכוך וטהרה.\nולעומת זאת, כאשר עושים דבר מסויים מתוך רגש של <b>אהבה ויראה</b> להקב\"ה, אזי גם דבר קטן שנעשה במעט הבנה, הרי הוא טהור וקדוש ויש לו תוקף יותר מהדבר הכי גדול שנעשה ללא אהבה ויראה (\"בלא דחילו ורחימו\").\n<b>ח</b>. עפ\"ז מבארים רבותינו נשיאינו את הסיפור שאירע אצל הבעש\"ט<sup data-n=\"1517\">13</sup>:\nפעם אחת ביוהכ\"פ – שאז נערך למעלה המשפט והפס\"ד על בנ\"י וכל העולם בנוגע לכל השנה כולה, אם תהי' שנה מבורכת או ח\"ו להיפך – ראה הבעש\"ט שהמשפט והדין קשה ביותר, ולא רוצים ליתן לבנ\"י את כל הברכות וכל הדברים הטובים שצריכים במשך השנה, ולכן התאמץ הבעש\"ט בתפלתו במרירות ובכיות בדביקות יתירה, וכן התלמידים, בראותם את גודל המרירות והבכיות של הבעש\"ט בתפלתו, הגבירו גם הם את דביקותם בתפלה, אך כל זה לא הועיל.\nוכך התקרב הזמן לסיום היום, תפלת נעילה, כאשר בעוד זמן מה (\"אָט-אָט\") יגמר ויקבע פסק-הדין על כל השנה כולה.\nבבית-הכנסת שבו התפלל הבעש\"ט, הי' נוכח באותה שעה ילד יהודי, שהוריו לא שלחו אותו לחדר או ישיבה, ולכן גדל מבלי לידע מאומה מעניני יהדות, תורה ומצוות, אבל אעפ\"כ, להיותו ילד יהודי, והי' לו לב יהודי חם, הנה בראותו שמסביבו עומדים יהודים ובוכים בתפלתם, ובכייתם הולכת ומתגברת, רצה גם הוא להתפלל ולבקש מהקב\"ה, אבל, להיותו \"עם הארץ\", מבלי לזכות באושר ללמוד בתלמוד-תורה וישיבה – לא ידע להתפלל, כיון שלא ידע אפילו לקרוא את האותיות, כך, שלא היתה לו ברירה אלא להביע זאת בדרכו הוא, לפי הרגש שלו.\nובכן: בהיותו בן-כפר, מצא חן בעיניו ביותר קריאתו של התרנגול בכל בוקר: \"קוקוריקו\". ולכן, בראותו שכולם מתפללים מתוך הסידור והמחזור מתוך רגש רב ובכי – נדלק גם לבו היהודי ברשפי אש של אהבה להקב\"ה, וזעק בכל הכחות: \"קוקוריקו\"...\nואח\"כ סיפר הבעש\"ט, שמה שלא יכלו לפעול כל התפלות, כיוןשלא היו מעומק הלב כ\"כ, ולכן לא הגיעו כ\"כ למעלה – הנה הצעקה הפשוטה \"קוקוריקו\" של הילד שלא ידע מאומה, אפילו לא קריאת האותיות (\"עברי\"), אבל צעק \"בדחילו ורחימו\", ברשפי אש של אהבה להקב\"ה, ומתוך יראה מפני הדין והמשפט – הרי זה קרע את רוע גזר הדין, ופעל שפסקו למעלה שתהי' שנה מבורכת לכל בנ\"י.\n<b>ט</b>. וזהו הלימוד לכל אחד מאתנו ולכל בנ\"י:\nצריך לעשות כל דבר \"בדחילו ורחימו\", מתוך רגש של אהבה לכל הדברים הטובים, ורגש של יראה מכל הדברים הבלתי-רצויים,\nואז מקבל הקב\"ה מתוך תענוג גדול ביותר אפילו פעולה קטנה,\nוגם ממלא את כל הבקשות של המתפלל אליו וההולך בדרכיו, בכל המצטרך לו, להתברך בכל עניניו.\n***\n<b>י</b>. לאחרי אדמו\"ר הזקן – הי' בנו שנקרא אדמו\"ר האמצעי, שגם הוא הפיץ ולימד כל הנ\"ל בתוספת ביאור והסברה, והעיקר – כיצד יכול כל אחד להתנהג ע\"פ תורה זו בענינים שלו.\nובנוגע לעניננו:\nלכאורה יש מקום לשאלה: כיצד יכולים לעמוד תמיד בתנועה של אהבה לדברים טובים ויראה מפני דברים בלתי-רצויים, אפילו ביום חול רגיל, ובמשך כל היום, כך, שיוכלו ללמוד מכל אדם ומכל מאורע?\nוהמענה על זה בתורתו של אדמו\"ר האמצעי<sup data-n=\"1518\">14</sup> – שהענין העיקרי שיש להזהר ממנו הוא: <b>פריקת עול</b>, היינו, שהאדם שוכח שעליו לשאת את העול של הקב\"ה, וכפי שהסביר בביאורים ארוכים ועמוקים, שהענין העיקרי אצל יהודי הוא – לזכור שהוא בן וגם <b>עבד</b> להקב\"ה, ולכן צריך לשאת על עצמו את העול של הקב\"ה ולעבוד אותו.\nוכאשר ענין זה הוא בדעתו תמיד, הנה בזכרו שנמצא תמיד עם הקב\"ה ונושא את עולו – אזי ביכלתו לזכור תמיד את אהבתו להקב\"ה, והיראה מפני הדברים הבלתי-רצויים.\nובאופן כזה יכול לקיים את ההוראה להיות \"חכם\" – \"הלומד מכל אדם\", שמכל אדם ומכל מאורע הרי הוא לומד דבר מה.<b>יא</b>. עפ\"ז יובן גם מה שסיפר הבעש\"ט אודות ימי חייו<sup data-n=\"1519\">15</sup>:\nעוד בהיותו ילד קטן, הי' רגיל לחזור ולשנן מה שלמד ב\"חדר\", וכדי שלא יפריעוהו, הי' נוהג לילך לשדה וליער, ושם הי' חוזר עניני התורה שלמד בחדר. וכאשר שאלוהו: היתכן שילד קטן לא מפחד להיות לבדו ביער ובשדה? – השיב, שזוכר תמיד מה שצוה עליו אביו, שאין לו לפחד משום דבר, אלא רק מהקב\"ה לבדו.\nכאשר זוכרים שנמצאים תמיד עם הקב\"ה – אין מתייראים משום דבר, גם כאשר נמצאים לבד בשדה וביער.\nוענין זה מאפשר גם לזכור תמיד את האהבה להקב\"ה, ואת היראה והפחד מכל הדברים שאינם מוצאים-חן בעיני הקב\"ה.\n<b>יב</b>. ובזה ניתוסף עוד פרט וענין:\nיש כאלה שמסתפקים במה שלומדים, כך, שאלו שהקב\"ה חנן אותם במוח ולב טובים יותר, אינם צריכים להתייגע כל כך, כי גם ללא יגיעה יכולים לידע כל מה שיודעים חבריהם בכיתה.\nועל זה באה ההוראה מהסיפור אודות הנשיא שהי' לאחרי אדמו\"ר האמצעי – הצמח צדק – שעוד בהיותו ילד, שאל אותו זקנו, אדמו\"ר הזקן, אם רצונו שיעניק לו במתנה הבנה בתורה, כך, שלא יצטרך להתייגע, והשיב הצ\"צ, שרצונו ללמוד תורה מתוך יגיעה בכל כשרונותיו וחריצותו<sup data-n=\"1520\">16</sup>.\nומזה למדים, שמי שיש לו הבנה וכשרונות יותר טובים, אינו יוצא ידי חובתו ואינו ממלא את הציפיות שתולים בו – כל זמן שאינו מתייגע בכל כשרונותיו, כפי שראוי להתייגע עבור אדם שאוהבים אותו, ועאכו\"כ – להבדיל כביכול – עבור הקב\"ה, אבינו שבשמים, אביו של כל אחד מישראל.\nכאשר כל אחד מתייגע לפי כחותיו במלוא המדה – אזי ממלא מה שנדרש ממנו, ואז מצליח ועולה מכתה אחת לכתה גבוהה יותר, כולל גם – במדת חשיבותו אצל הקב\"ה, כיון שמילא כל מה שנדרש ממנו.\n<b>יג</b>. עפ\"ז יובן סיפור נוסף אודות הבעש\"ט<sup data-n=\"1521\">17</sup>:\nכאשר המגיד בא אל הבעש\"ט – עוד לפני שנעשה מגדוליתלמידיו, שגם אז הי' כבר בעל מוחין ובעל מדות גדול ביותר, אלא שעדיין לא ידע אודות דרכי העבודה וההנהגה שלימד הבעש\"ט – שאל אותו הבעש\"ט קושיא בענין מוקשה ב\"עץ חיים\" (אחד הספרים העמוקים שבתורה), ובהיותו כבר למדן וגאון גדול, אמר את פירוש הדברים. ואמר הבעש\"ט, שעדיין אין זה פירוש הדברים לאשורו. חזר התלמיד ועיין עוד הפעם, ואמר, שכך הוא בכל זאת פירוש הדברים, ואם לאו – יואיל נא הבעש\"ט לומר את פירוש הדברים.\nואז התחיל הבעש\"ט ללמוד עם המגיד את דברי ה\"עץ חיים\", אלא, שלמד ברוב יגיעה, חיות והתלהבות, כפי שהי' דרך הלימוד אצל הבעש\"ט, ועד כדי כך, שכאשר נזכר אודות \"מלאכים\", ראו הבעש\"ט והמגיד את המלאכים שנתהוו ע\"י הלימוד, וכל החדר והבית נתמלא אורה.\nואח\"כ הסביר הבעש\"ט לתלמידו, שהוא אמנם ידע את פירוש הדברים, אבל כיון שלימודו לא הי' במלוא המאמץ של כל כחות נשמתו, ולא הי' במלוא ההתלהבות הדרושה, לכן לא הי' זה הלימוד המתאים. ורק כאשר לומדים במלוא ההתלהבות ותוך כדי ניצול כל הכשרונות, עם כל המוח וכל הלב, אזי לימוד התורה הוא כדבעי למהוי.\n<b>יד</b>. אך כיצד יכולים לבוא ללימוד התורה באופן כזה, שגם לאחרי שמבינים מה שלומדים בחומש, במשנה, בגמרא ובשאר ספרים, ישתדלו להתאמץ ולהבין יותר, וביתר חיות וחום?\nהנה על זה ישנו הביאור של אדמו\"ר מהר\"ש<sup data-n=\"1522\">18</sup> – בנו של הצ\"צ שהי' הנשיא לאחריו – שעבודת השם צריכה להיות מתוך ידיעה שהעיקר הוא עשיית המצוה ולימוד התורה, ולא השכר שיקבלו לאח\"ז בגן-עדן ובעולם-הבא, בהסבירו את החילוק שביניהם – שהתענוג שבג\"ע ובעוה\"ב הוא התענוג של <b>האדם</b>, ואילו עצם הפעולה דלימוד התורה וקיום המצוה (ע\"י ילד או מבוגר) הוא התענוג של <b>הקב\"ה</b>, והרי מובן שהתענוג של הקב\"ה הוא <b>נעלה הרבה יותר</b> מאשר התענוג שיכול להיות אצל האדם (ילד או מבוגר).\nובזה יובן גם הסיפור שאירע עם הבעש\"ט<sup data-n=\"1523\">19</sup>, שפעם התפלל להקב\"ה ודרש ממנו לברך יהודי, ואף שהלה לא הי' ראוי לברכה זו, הריכיון שהבעש\"ט דרש זאת בתוקף, ומעומק נשמתו, נעתרו לבקשתו, אבל אח\"כ אמרו לו, שכיון שידע שהלה אינו ראוי לכך, ואעפ\"כ דרש זאת, מבלי הבט על כך שזהו נגד סדר העולם, לכן מענישים אותו שלא יהי' לו עולם-הבא. והשיב הבעש\"ט, שהוא <b>שמח</b> על כך, כי, בידעו שלא יהי' לו עולם-הבא, יוכל מעתה לעבוד את הקב\"ה <b>לשמו</b> בלבד, כדי לגרום תענוג להקב\"ה, שזהו\"ע נעלה הרבה יותר מאשר התענוג של האדם (כנ\"ל).\n<b>טו</b>. וכאשר הולכים בדרך זו, שכללות ההנהגה היא כדי לגרום תענוג להקב\"ה – הרי, כיון שהקב\"ה נמצא בכל מקום, הנה בכל מקום שנמצאים, בישיבה או ב\"קעמפּ\", או בשדה וביער, ישנה תמיד האפשרות לגרום תענוג להקב\"ה, דכיון שזהו מקום שבו נמצא הקב\"ה, הרי בודאי יכולים למצוא שם אפשרות לעשות איזה דבר שעל ידו יגרמו תענוג להקב\"ה.\nוזהו גם תוכן הסיפור אודות כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע<sup data-n=\"1524\">20</sup> – שהי' הנשיא לאחרי אדמו\"ר מהר\"ש – שבהיותו פעם בוינה, בריחוק רב ממקום מגוריו, הרי אף שסיבת נסיעתו לשם היתה לצורך רפואתו ע\"י הרופאים, הנה לאח\"ז אמר שרצונו לנסוע לעיירה רחוקה מוינה, וקודם נסיעתו הלך לחנות וקנה בגדים ומצרכים נוספים, ונסע לעיירה נדחת, ונכנס לבית שבו דרה אלמנה עם שתי בנותי', והשאיר שם את כל הבגדים שקנה, וגם סכום כסף, ואמר, שזהו עבור \"הכנסת כלה\", שע\"י הבגדים והכסף יוכלו לערוך חתונה, אשר, עד אז נמנע הדבר, כיון שלא הי' כסף לאלמנה עבור צרכי החתונה.\nכלומר: בעיירה נדחת, בריחוק אלפי קילומטרים ממקום מגוריו, מצא אדנ\"ע אפשרות כיצד לגרום תענוג להקב\"ה, ובשביל זה הלך בעצמו לערוך קניות, ונסע דרך רחוקה, כדי שנערה עני', כלה עני', תוכל לערוך חתונתה.\nוזהו גם תוכן הסיפור<sup data-n=\"1525\">21</sup> אודות השליחות שמסר הבעש\"ט לאחד מגדולי הרבנים והגאונים, ר' חיים הכהן ראַפּפּאָרט, שיסע ליער רחוק, ויגש למעיין מים, ויקח מים מן המעיין ויברך עליהם \"שהכל נהי' בדברו\", ולאחרי שתייתם יברך גם ברכה אחרונה. וכאשר חזר ואמר לבעש\"ט שמילא את השליחות, הסביר הבעש\"ט, שמעיין זה, מאז בריאת העולם,יותר מחמשת אלפים וחמש מאות שנה, לא בירך יהודי על מימיו, והי' המעיין טוען להקב\"ה ובוכה: למה לא זכה שיברכו להקב\"ה על מימיו?!... ובשביל זה שלח הבעש\"ט רב וגאון גדול, כדי לגרום תענוג להקב\"ה ע\"י אמירת ברכה במקום כזה שיותר מחמשת אלפים וחמש מאות שנה לא נאמרה שם ברכה מפיו של יהודי.\n<b>טז</b>. וזהו גם הלימוד עבור כל אחד מאתנו:\nבכל מקום שנמצאים, צריכים תמיד לחפש – ואז ימצאו – כיצד לעשות דבר טוב שעל ידו יגרמו תענוג להקב\"ה.\nוע\"י הנהגה כזו תגדלו להיות ותהיו כפי שילדי ישראל צריכים להיות – שכל אחד מהם נקרא \"חייל\" בה\"חיל\" ו\"צבא\" של הקב\"ה.\nוהרבי, בעל השמחה,\n– שנגאל ממאסרו על עבודתו בהקמת חדרים וישיבות, כדי שילדי ישראל ילמדו תורה ויקיימו מצוות, וילכו בדרכי השם, לפי הוראותיהם של רבותינו נשיאינו, כמוזכר לעיל –\nמברך את כל אחד מכם, וכל ילדי ישראל, וכל בנ\"י בכל מקום שהם, שיצליחו ללכת בדרכים אלו, ויעמידו את ה\"צבא\" של הקב\"ה, שבקרוב ילכו כולם לקראת משיח צדקנו.\n[כ\"ק אדמו\"ר שליט\"א הורה שעכשיו ינגנו הילדים ניגון, ואח\"כ יש לשחרר אותם.\nכאשר הילדים ניגנו, עודדם כ\"ק אדמו\"ר שליט\"א בשתי ידיו הק', וגם עמד מלוא קומתו ורקד על מקומו בשמחה רבה.\nאח\"כ יצאו הילדים, וכ\"ק אדמו\"ר שליט\"א המשיך את ההתוועדות בנוכחות המבוגרים בלבד].\n***\n<b>יז</b>. בהפרשה דמינה אזלינן נאמר<sup data-n=\"1526\">22</sup> \"כי מראש צורים אראנו ומגבעות אשורנו\", \"אראנו\" מרחוק, ו\"אשורנו\" מקרוב<sup data-n=\"1527\">23</sup>. וכמו\"כ נזכרו ב' לשונות אלו בהמשך הסדרה<sup data-n=\"1528\">24</sup>: \"אראנו ולא עתה אשורנו ולא קרוב דרך כוכב מיעקב וקם שבט מישראל\".\nוהענין בזה:\"כוכב\" – קאי על \"מלכא\", ו\"שבט\" – קאי על \"משיחא\" (כפירוש התרגום). כלומר: \"דרך כוכב\" הוא אמנם התחלת ענין המלוכה, אבל, זהו רק מלך סתם, ועדיין יכול להיות מצב שילחמו נגדו כו'; ולאח\"ז בא במעמד ומצב ד\"קם שבט\", דקאי על מלך המשיח, אשר, הסימן אודותיו הוא ש\"ילחם מלחמות ה' . . ונצח\", כדברי הרמב\"ם<sup data-n=\"1529\">25</sup> שאז יודעים שהוא לא רק מלך כשר, אלא \"הרי זה משיח בודאי\".\nוענין זה מובן גם מדיוק לשון הכתוב, שגבי \"כוכב\" נאמר השם \"יעקב\", וגבי \"שבט\" נאמר השם \"ישראל\" – שהרי השם \"ישראל\" מורה על דרגא נעלית יותר מאשר השם \"יעקב\";\nוהרי זהו ענינו של משיח (\"שבט\", \"משיחא\") – להעמיד את כל בנ\"י במעמד ומצב שיהיו נקראים בשם \"ישראל\", ע\"ש \"כי שרית עם אלקים ועם אנשים ותוכל\"<sup data-n=\"1530\">26</sup>, היינו, שפועלים בעולם כרצונם, אם רק הרצון שלהם הוא כפי התומ\"צ.\nועד\"ז מובן בנוגע לבעש\"ט, שמכל השמות של בנ\"י נקרא בשם \"ישראל\" דוקא – כי, ענינו של הבעש\"ט הוא התחלת גילוי אור המשיח<sup data-n=\"1531\">27</sup>, שלכן, הענין ד\"יפוצו מעינותיך (דהבעש\"ט) חוצה\" פועל את ביאת המשיח למטה מעשרה טפחים<sup data-n=\"1532\">28</sup>, ולכן נקרא בשם \"ישראל\", כיון שעל ידו נעשה הענין ד\"קם שבט מישראל\", דקאי על \"משיחא\".\n<b>יח</b>. ובהתאם לסדר הכתובים, \"אראנו\" ואח\"כ \"אשורנו\", \"כוכב\" ואח\"כ \"שבט\" – הרי כשם ש\"שבט\" הוא למעלה מ\"כוכב\", כמו\"כ \"אשורנו\" הוא למעלה מ\"אראנו\", והיינו, שמהענין ד\"אראנו\" באים ל\"דרך כוכב מיעקב\", ומהענין ד\"אשורנו\" באים ל\"קם שבט מישראל\".\nוהענין בזה:\n\"אראנו\" (מרחוק) – קאי בכללות על העבודה שמצד בחי' החכמה שנקראת בשם ראי'; ואילו \"אשורנו\" (מקרוב) – קאי על העבודה המסודרת שהיא במדידה והגבלה, להיותה מצד כחות פנימיים שבאים בלבושים כו' (כמדובר לעיל בהמאמר&lt;23&gt;), שזהו כללות הענין דלימוד התורה וקיום המצוות באופן מסודר.\nאמנם, דוקא ע\"י העבודה ד\"אשורנו\" באים להענין ד\"קם שבט מישראל\":ע\"י הקיום <b>כפשוטו</b> של התומ\"צ – \"אשורנו\" – ממלאים את הרצון העליון.\nולכן, גם אלו שהם בדרגת \"ישראל\", צריכה להיות אצלם העבודה ד\"אשורנו\", מצד בחי' \"יעקב\" שבהם,\nודוקא עי\"ז באים מהמעמד ומצב ד\"כוכב\", \"מלכא\" סתם, שלוחם מלחמות ה' – למעמד ומצב ד\"קם שבט מישראל\", שישנה ההוכחה שהוא \"(מלכא) משיחא\", כיון שניצח ופעל שיהי' מעמד ומצב ד\"שרית עם אלקים ועם אנשים\", שמנהיג את העולם כולו ומעמיד אותו באופן ד\"כמים לים מכסים\"<sup data-n=\"1533\">29</sup>.\n***\n<b>יט</b>. צוה לנגן ואמר מאמר ד\"ה ברוך שעשה נסים.\n***\n[כ\"ק אדמו\"ר שליט\"א צוה לנגן ניגון ג' התנועות (דהבעש\"ט, הרב המגיד ואדמו\"ר הזקן). ואח\"כ התחיל לנגן הניגון \"לכתחילה אריבער\".\nלאחרי שהילדים חזרו, שאל כ\"ק אדמו\"ר שליט\"א אם הילדים יודעים לנגן \"אני מאמין\" – וניגנו \"אני מאמין\".\nכ\"ק אדמו\"ר שליט\"א ביקש לוודא אם ישנם עשרה שנטלו ידיהם לסעודה, וברך ברכת המזון על הכוס.\nאח\"כ נתן בידו הק' לכל אחד מהמסובים מ\"כוס של ברכה\", וביקש שתחילה יעברו הילדים.\nלאחרי חלוקת \"כוס של ברכה\", נתן כ\"ק אדמו\"ר שליט\"א לכל אחד מהילדים והמדריכים שיחיו – קונטרס \"תפלת מנחה ותפלת ערבית\".\nלאחרי תפלת מנחה, נתן כ\"ק אדמו\"ר שליט\"א למארגנים שטרות של כסף, על מנת לחלקם בין הצוות].\n**********",[["1504","*","בנוגע לכללות הביקור – ראה בארוכה \"בנאות דשא\" (קה\"ת, תשנ\"ג) פ\"ג (ע' 82 ואילך)."],["1505","1","ראה גם שיחת ט\"ו תמוז תשי\"ז (במחנה-קיץ \"גן ישראל\") ס\"ג (תו\"מ ח\"כ ע' 173). וש\"נ. לעיל ע' 162."],["1506","2","ראה ברכות יח, סע\"א."],["1507","3","ראה תענית ה, ב."],["1508","4","ראה תניא אגה\"ק סז\"ך-וביאורו."],["1509","5","ראה כתר שם טוב (הוצאת תשנ\"ט) בהוספות סרפ\"ח ואילך. וש\"נ."],["1510","6","ראה שם סקי\"ד. וש\"נ."],["1511","7","אבות רפ\"ד."],["1512","8","או\"ת צא, ב."],["1513","9","עובדי' א, יח."],["1514","10","פתיחתא דאסת\"ר יא."],["1515","11","ראה גם תו\"מ חכ\"א ס\"ע 133 ואילך. וש\"נ."],["1516","12","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא פל\"ט</a> ואילך."],["1517","13","קונטרס תורת החסידות פ\"ב ואילך. אג\"ק אדמו\"ר מוהריי\"צ ח\"ד ס\"ע שיג ואילך. וראה סה\"ש תש\"א ע' 158. וראה גם ר\"ד ש\"פ מטו\"מ, מבה\"ח מנ\"א תש\"א ס\"ד."],["1518","14","בספרו דרך חיים."],["1519","15","ראה סה\"ש תש\"ג ס\"ע 165 ואילך. וראה גם שיחת ט\"ו תמוז שבהערה 1. וש\"נ."],["1520","16","ראה גם אג\"ק חי\"א ע' רסט. תו\"מ חט\"ו ע' 15. וש\"נ."],["1521","17","כש\"ט סתכ\"ד. וראה שבחי הבעש\"ט (הוצאת מונדשיין, ירושלים תשמ\"ב) ע' 264 ואילך. וש\"נ."],["1522","18","המשך וככה תרל\"ז פי\"ב."],["1523","19","ראה \"סיפורי חסידים\" (לרש\"י זעווין), מועדים ע' 262. וראה גם תו\"מ חכ\"ז ע' 334. וש\"נ."],["1524","20","ראה \"רשימות\" חוברת צד ע' 5 ואילך. וש\"נ."],["1525","21","לקו\"ד ח\"ד תקפד, א ואילך. וראה גם לעיל ס\"ע 217."],["1526","22","בלק כג, ט."],["1527","23","ראה ד\"ה כי מראש צורים אראנו די\"ב תמוז פ\"ג (לעיל ע' 175 ואילך). וש\"נ."],["1528","24","שם כד, יז."],["1529","25","הל' מלכים ספי\"א."],["1530","26","וישלח לב, כט."],["1531","27","ראה ס' בעש\"ט עה\"ת בהקדמה אות כא ואילך. וש\"נ."],["1532","28","אגה\"ק דהבעש\"ט (כש\"ט בתחלתו. ובכ\"מ)."],["1533","29","ישעי' יא, ט. וראה רמב\"ם שם ספי\"ב."]]],[1400350026,"– במחנה-קיץ \"אמונה\", גרינפילד פּאַרק, ניו-יארק –\nבלתי מוגה\nיום זה הוא \"יום ההילולא\" של ה\"אור-החיים\" הקדוש, רבי חיים בן עטר.\nושייך במיוחד לבנות ישראל – כידוע<sup data-n=\"1534\">1</sup> שהאור-החיים שהיו לו רק בנות, הי' לומד שיעורים בחומש עם בנותיו בכל ליל שבת, ואח\"כ הי' רושם את הפירושים שאמר לפניהן בשיעורים אלו, ומהם ערך את פירוש ה\"אור החיים\" על התורה.\nומכאן ההוראה לכל אחת מכן – שעליכן להשתדל לא רק בחינוך עצמכן באופן המתאים, אלא גם בחינוך והשפעה על הזולת<sup data-n=\"1535\">2</sup>.\n[כ\"ק אדמו\"ר שליט\"א נתן למנהל המחנה-קיץ חבילת שטרות של דולר, על מנת לחלק אותם לראשי הצוות].\n**********",[["1534","1","ראה \"התמים\" ח\"ב ע' עח. אג\"ק אדמו\"ר מוהריי\"צ ח\"ג ע' תסט."],["1535","2","ראה גם שיחת ט\"ו תמוז תשי\"ז (במחנה-קיץ \"אמונה\") ס\"א-ב (תו\"מ ח\"כ ע' 177)."]]],[1400350027,"(הנחה בלתי מוגה)\n<b>ומקנה</b><sup data-n=\"1536\">1</sup> רב הי' לבני ראובן ולבני גד גו' ויראו גו' והנה המקום מקום מקנה גו' ויאמרו גו' יותן את הארץ הזאת לעבדיך לאחוזה אל תעבירנו את הירדן<sup data-n=\"1537\">2</sup>, והשיב להם משה על זה דברי תוכחה בהזכירו להם את מעשה המרגלים, ולבסוף אמר להם<sup data-n=\"1538\">3</sup> אם תחלצו לפני ה' וגו' ונכבשה הארץ גו' והיתה הארץ הזאת לכם לאחוזה. ומזה משמע, שבקשת בני גד ובני ראובן מצד עצמה היא כעין טענת המרגלים שלא רצו ליכנס לארץ, ורק כאשר הסכימו להתנאי שהתנה עמהם משה ואמרו ואנחנו נחלץ חושים גו'<sup data-n=\"1539\">4</sup>, הי' זה ענין רצוי.\nב) <b>ויובן</b> בהקדם המבואר בד\"ה ומקנה רב להצ\"צ<sup data-n=\"1540\">5</sup> ולאדמו\"ר מהר\"ש (בסה\"מ תרכ\"ט<sup data-n=\"1541\">6</sup>) ע\"פ מ\"ש רבינו הזקן<sup data-n=\"1542\">7</sup> בביאור הטעם שהאבות והשבטים בחרו להיות רועי צאן, לפי שרצו להיות בהתבודדות מהעולם בכדי שיוכלו לעבוד את הוי', שהיא כללות העבודה דתומ\"צ, ולכן בחרו להיות רועי צאן, כדי שהעולם לא יבלבל וימנע אותם מעבודתם. ומטעם זה לא רצו המרגלים ליכנס לארץ<sup data-n=\"1543\">8</sup>, כי טענתם היתה שהכניסה לארץ היא ירידה גדולה, ויותר טוב שישארו במדבר, ששם לא הי' להם עסק עם עניני עוה\"ז, ובפרט שהיו דור דעה<sup data-n=\"1544\">9</sup>, ורצו לעסוק בתורה שלא ניתנה אלא לאוכלי המן<sup data-n=\"1545\">10</sup>, ועד\"ז בנוגע לשאר צרכי האדם שהיו להם מן המוכן, מים מבארה של מרים<sup data-n=\"1546\">11</sup>, ולבושים ע\"י ענני הכבוד<sup data-n=\"1547\">12</sup>, היינו, שכל הענינים דמזון ולבוש לא היו בהגשמה, ולכן לא רצו ליכנס לא\"י לעסוקבענינים גשמיים כדי לבררם, באמרם שארץ אוכלת יושבי' היא<sup data-n=\"1548\">13</sup>, היינו, שתמורת זה שהם יבררו יזככו ויעלו את הענינים הגשמיים, אפשר להיות להיפך ח\"ו, שעי\"ז תהי' להם ירידה כו'. ועל זה הי' המענה להם טובה הארץ מאד מאד<sup data-n=\"1549\">14</sup>, שבכדי להגיע לתכלית העילוי בחי' מאד מאד, הרי זה דוקא ע\"י העבודה בארץ, לגלות בחי' הטוב שבה, כי העלי' היא דוקא ע\"י הירידה, ובזה גופא לא מספיק כללות ירידת הנשמה בגוף ונה\"ב, שהרי גם המרגלים הסכימו על הירידה בעולם המחשבה<sup data-n=\"1550\">15</sup>, או בעולם הדיבור<sup data-n=\"1551\">16</sup>, אלא צריכה להיות הירידה בעולם המעשה דוקא, ודוקא ע\"י ירידה זו מגיעים לבחי' מאד מאד. ולכן, כשאמרו בני ראובן ובני גד שרוצים לישאר בעבר הירדן ולהיות רועי מקנה, הרי זה כעין טענת המרגלים. אך ע\"י התנאי דנחלץ חושים, שגם להם יהי' מס\"נ ליכנס לא\"י, הנה לאחרי הקדמה זו יכולים הם להיות בעבר הירדן.\nג) <b>ולהבין</b> זה בעומק יותר, וגם להבין ההפרש בין בני ראובן ובני גד להאבות והשבטים, שהאבות והשבטים היו רועי צאן מבלי שיצטרכו איזה תנאי על זה, משא\"כ בני ראובן ובני גד שאצלם הוצרך להיות התנאי דנחלץ חושים, ובזה גופא לא הי' מספיק שיאמרו מעצמם אנחנו נחלץ חושים, אלא הי' צורך בהקדמת דברי מוסר שאמר להם משה, רועה ישראל, ודוקא הוא פעל שתהי' עבודתם באופן הרצוי.\n<b>ויובן</b> בהקדים המבואר בהדרושים הנ\"ל ההפרש שבין יוסף והשבטים, שהשבטים היו רועי צאן כמו האבות, משא\"כ יוסף, הנה גם קודם שירד למצרים לא הי' רועה צאן כמו אחיו, אלא הי' בביתו של יעקב אביו, ובפרט בירידתו למצרים, הנה בהיותו בבית פוטיפר הפקידו על ביתו וכל יש לו נתן בידו<sup data-n=\"1552\">17</sup>, וגם בהיותו בבית האסורים כתיב<sup data-n=\"1553\">18</sup> ויתן שר בית הסהר ביד יוסף את כל האסירים גו', ומכש\"כ לאחרי שנלקח אל פרעה, שאז נאמר לו על פיך ישק כל עמי<sup data-n=\"1554\">19</sup>, ובלעדיך לא ירים איש את ידו ואת רגלו בכל ארץ מצרים<sup data-n=\"1555\">20</sup>, והיינו, שהי' עסוק בעניני העולם כו', ואעפ\"כ, הי' בשעת מעשה בתכלית הדביקות באלקות. וזהו גם הביאור במ\"ש<sup data-n=\"1556\">21</sup> ויכר יוסף את אחיו והם לא הכירוהו, כי, השבטים שעבודתם היתה בהתבודדותמהעולם, לא יכלו להבין אשר איש שעוסק בעניני עולם יוכל להיות בשעת מעשה בדביקות באלקות. ובאמת הנה בשעה שיוסף הי' עוסק בעניני העולם הי' בתכלית הדביקות באלקות עוד יותר מאשר דביקותם של השבטים כשהיו בהתבודדות, וזהו מ\"ש והם לא הכירוהו, שלא הכירו דרגא נעלית כזו בדביקות באלקות. ונקודת הענין הוא, שהשבטים וגם האבות היו בחי' מרכבתא תתאה, סדר השתלשלות, שבבחי' זו יש תפיסת מקום להעולם, ולכן העולם מבלבל, והיינו שבבחי' זו ישנם ב' קוין, זה לעומת זה, שזהו שגם ביעקב, בחיר האבות<sup data-n=\"1557\">22</sup>, כתיב<sup data-n=\"1558\">23</sup> ויאבק איש עמו, כשני אנשים הנאבקים זה עם זה כו' לפי שיש תפיסת מקום זה לגבי זה, וזהו ג\"כ מ\"ש<sup data-n=\"1559\">24</sup> הלא אח עשו ליעקב, שיש לעשו תפיסת מקום כו'. משא\"כ יוסף הי' מבחי' עליונה ביותר שלמעלה משרש תהו ותיקון, שרש עשו ויעקב<sup data-n=\"1560\">25</sup>, שבה אין תפיסת מקום למציאות של מנגד כלל, ולכן הנה בשעה זו עצמה שעסק עצמו בעניני העולם הי' יכול להיות בתכלית הדביקות באלקות, לפי שעניני העולם לא היו מנגדים אליו כלל.\n<b>ובזה</b> יובן גם מה שמצינו חילוק בין יעקב ליוסף<sup data-n=\"1561\">26</sup>, שיעקב עשה כמה סיבות גשמיים כדי לינצל מעשו, ולא נחשב לו לחטא [ואף שאמרו רז\"ל<sup data-n=\"1562\">27</sup> שבאותה שעה שקרא יעקב לעשו אדוני, אמר לו הקב\"ה, אתה השפלת עצמך כו', חייך אני מעמיד מבניו שמונה מלכים קודם לבניך, מ\"מ, לא הי' זה חטא ממש ועונש ממש], משא\"כ ביוסף מצינו שכאשר אמר לשר המשקים כי אם זכרתני גו' והזכרתני אל פרעה גו'<sup data-n=\"1563\">28</sup>, נענש על זה להיות אסור שתי שנים<sup data-n=\"1564\">29</sup>, וכדאיתא במדרש<sup data-n=\"1565\">30</sup> שזהו מש\"נ<sup data-n=\"1566\">31</sup> ולא פנה אל רהבים, שיוסף פנה אל מצרים הקרויים רהב. וידועה הקושיא על זה, מה הי' חטאו של יוסף, הרי איתא בחובת הלבבות<sup data-n=\"1567\">32</sup> שחייב האדם לבקש סיבה כו', והראי' משמואל שאמר<sup data-n=\"1568\">33</sup> ואיך אלך ושמע שאול גו', ולא הי'נחשב לו לחסרון בבטחון כו', וא\"כ מה הי' חטאו של יוסף. ורבינו הזקן<sup data-n=\"1569\">34</sup> הקשה בעומק יותר, דיעקב אבי יוסף עשה כמה סיבות כו' ומ\"מ לא נחשב לו לחטא. אך הענין הוא, שבבחי' מרכבתא תתאה, שיש בה תפיסת מקום לעניני העולם, אזי צריך לעשות סיבות בגשמיות, דכיון שהעולם תופס מקום בבחינה זו, לכן יש צורך שגם מצד עניני העולם יהי' מתאים כו'. משא\"כ יוסף שהי' בבחי' מרכבתא עילאה, ששם אין העולם תופס מקום כלל, לכן לא הוצרך לעשות סיבות בגשמיות כלל, ועשיית סיבה בגשמיות במי שהוא למעלה לגמרי מהעולם הו\"ע של ירידה כו', וכיון שיוסף ידע מדריגתו שהוא למעלה לגמרי מהעולם, שהרי ראה בעצמו (עוד קודם שהי' בבית הסהר) שהגם שעוסק בעניני העולם מ\"מ אין זה מבלבל אותו, ומזה ידע שהוא בבחי' מרכבתא עילאה ששם אין העולם תופס מקום, לכן עשיית סיבה בגשמיות היתה אצלו ירידה ממדריגתו, ולכן נענש על זה במדה כנגד מדה, להיות שתי שנים בבור, שהו\"ע של ירידה כו'.\nד) <b>וביאור</b> הענין יובן ע\"פ משל מההפרש שבין שר למלך, שכאשר שר גדול נותן מקום וערך לאיש פשוט, הרי זה לפי שבאמת יש להאיש פשוט איזה ערך קצת אליו, דהגם שרחוק ערכו של האיש פשוט לערכו של השר, מ\"מ, יש לו איזה ערך אליו. אבל כאשר מלך גדול ורב נותן איזה מקום ומציאות לאיש הדיוט ושפל אנשים, אין זה מצד הערך שיש להאיש פשוט, שהרי לגבי רוממות המלך אין שום אדם תופס מקום כלל, אלא אדרבה, מצד האין ערוך והשפלות שלו דוקא, לפי שטבע המרומם להיות נמשך אל השפל. ומובן, שמציאות כזו שמצד עצמה אינה מציאות כלל, וכל מציאותה היא רק מה שהמלך נותן לה מציאות, הרי לא שייך שמציאות כזו תבלבל כו'. ועד\"ז יובן למעלה, שבבחי' האלקות שיש שם איזה תפיסת מקום למציאות העולמות, שייך שהעסק בעניני עולם יבלבל לעבודת ה', וגם צריך לעשות סיבות בגשמיות, לפי שצריך להתחשב גם עם עניני העולם, משא\"כ בבחי' אלקות שלמעלה מהעולמות לגמרי, שזו היתה מדריגתו של יוסף, הנה במדריגה זו אין מציאות העולם מבלבל כלל, וגם אין צריך לעשות סיבות בגשמיות כו'.\nה) <b>ובזה</b> יובן גם מה שמסופר על הבעש\"ט, שבליל ש\"ק לא הי' יכול להשיב כהלכה בעניני העולם מפני דביקות נפשו באלקות, והתפלל על זה ופעל שגם בליל ש\"ק יהי' ביכלתו להשיב בעניני העולם. ולכאורה אינו מובן, בשביל מה הוצרך לזה. אך הענין הוא, שאין זה ירידה,אלא אדרבה, שנתעלה במדריגה עליונה ביותר עד שאין הגשמיות סותר כלל. דהנה, בליל ש\"ק הו\"ע עליית העולמות כידוע<sup data-n=\"1570\">35</sup>, ולכן בתחילה לא הי' יכול להשיב אז בעניני העולם, כי הגשמיות הי' סותר כו'. אך אח\"כ פעל עילוי במדריגתו בתכלית העלי', שלא יהי' הגשמיות סותר כו', ולא עוד אלא שמבחי' זו גופא יוכל להשיב בעניני העולם, והיינו, שיומשך בעניני העולם מבחי' שלמעלה מהשתלשלות. וזו היתה מדריגתו של יוסף, דכתיב בי'<sup data-n=\"1571\">36</sup> וילקט יוסף את כל הכסף גו', היינו, שלא זו בלבד שעסקו בעניני העולם לא הי' בסתירה לכך שבשעת מעשה הי' בתכלית הדביקות לאלקות כנ\"ל, אלא עוד זאת, שמבחי' דביקותו באלקות המשיך בענינים הגשמיים, ועי\"ז פעל בהם הבירור כו'. וזהו גם כללות ההפרש בין עבודת האבות והשבטים לעבודתו של יוסף<sup data-n=\"1572\">37</sup>, שעבודת השבטים והאבות היא בירור ראשון, בירור דשם ב\"ן, שהוא בדרך התלבשות ותפיסא בהדבר המתברר, ומובן שבבחי' זו יש תפיסת מקום לעולם ולכן העולם מבלבל כו'. אך עבודתו של יוסף היא בירור שני, בירור דשם מ\"ה, שנעשה בדרך ממילא כו'.\nו) <b>והנה</b> כללות החילוק בין ב' דרכי העבודה הנ\"ל הי' קודם מ\"ת. אבל לאחרי מ\"ת, שניתנה התורה למטה דוקא, למצרים ירדתם כו' יצה\"ר יש ביניכם<sup data-n=\"1573\">38</sup>, הרי מובן שהעבודה צריכה להיות באופן של התעסקות בעניני העולם כדי לעשותם כלים לאלקות. ולכן כאשר המרגלים טענו שרצונם להשאר במדבר ולהיות בהתבודדות מהעולם, הי' זה היפך הכוונה, כי, לאחרי מ\"ת יש כח לכאו\"א מישראל שגם כאשר עוסק בעניני העולם לא יהי' זה מניעה מעבודת הוי'. וכן הוא גם בנוגע לבני גד ובני ראובן, שכאשר אמרו שרצונם להשאר בעבר הירדן ולהיות רועי צאן, הנה מצד עצמם לא הי' זה כפי הכוונה. אך על זה הועיל מה שאמרו ואנחנו נחלץ חושים גו', שהו\"ע המס\"נ, באופן שכל מציאותם היא רק מציאות האדון<sup data-n=\"1574\">39</sup>, שענין זה נתעורר אצלם לאחרי ההקדמה דאמירת דברי מוסר ע\"י משה, רועה ישראל, שהוא גילה בהם בחי' המס\"נ. והענין בזה, שע\"י המס\"נ ליכנס לא\"י הרי הם מראים בעצמם שגם בהיותם בעבר הירדן אין זה ענין של התבודדות, אלא גם שם עבודתם היא בעולם, לעשות לו ית' דירה בתחתונים<sup data-n=\"1575\">40</sup>, אלא שבזה גופא הנה עיקר עבודתם היא ע\"י לימוד התורהכו'<sup data-n=\"1576\">41</sup>, כידוע שיש ב' סוגים בישראל, מארי תורה ומארי עובדין טבין<sup data-n=\"1577\">42</sup>, ושניהם צריכים להיות בהתכללות זמ\"ז, שהרי כל האומר אין לי אלא תורה אפילו תורה אין לו<sup data-n=\"1578\">43</sup>, אלא צריך להיות תורה וגמ\"ח<sup data-n=\"1579\">44</sup>, שהיא כללות המצוות<sup data-n=\"1580\">45</sup>, וגם אצל מארי עובדין טבין צריך להיות לימוד התורה, ועכ\"פ פרק אחד שחרית ופרק אחד ערבית או פסוק אחד שחרית ופסוק אחד ערבית<sup data-n=\"1581\">46</sup>. ולכן, עי\"ז שאמרו ואנחנו נחלץ חושים גו', היו יכולים להשאר בעבר הירדן ולעבוד עבודתם בהקו דמארי תורה כו'. וזהו ג\"כ מה שאמרו רז\"ל<sup data-n=\"1582\">47</sup> עשר קדושות הן, ארץ ישראל מקודשת מכל הארצות כו' שמביאין ממנה העומר והבכורים ושתי הלחם, שבזה נכלל גם עבר הירדן שגם משם מביאים עומר ובכורים ושתי הלחם (כמו מארץ כנען), שענין ג' דברים אלו הוא הבירור של דברים הגשמיים, כידוע. אך אעפ\"כ הנה ארץ כנען מקודשת מעבר הירדן<sup data-n=\"1582\">47</sup>, ותכלית הכוונה היא שתהי' הכניסה לארץ ישראל דוקא, ועבר הירדן הוא רק הכנה לארץ ישראל. והענין בזה, שאף שבכללות הנה גם עבר הירדן קדוש לענין העומר כו', מ\"מ, בפרטיות יותר, ביחס לארץ ישראל נקרא עבר הירדן נחלה מבוהלת בראשונה<sup data-n=\"1583\">48</sup>, דנחלה מבוהלת הו\"ע התהו<sup data-n=\"1584\">49</sup>, היפך ההתיישבות דדירה בתחתונים, ותכלית הכוונה היא שתהי' הכניסה לארץ כנען לעסוק בל\"ט המלאכות, החורש והזורע כו', שהו\"ע בירור הדברים הגשמיים דוקא, שעי\"ז מאספים ומלקטים את כל ניצוצות הקדושה, וכנ\"ל שזהו מ\"ש וילקט יוסף את כל הכסף גו'. ועי\"ז זוכים למטמון הג' שיתגלה לעתיד לבוא<sup data-n=\"1585\">50</sup>, היינו, שיצא הסוד בגילוי ממש. והו\"ע גילוי פנימיות התורה לעתיד לבוא, כמ\"ש<sup data-n=\"1586\">51</sup> ישקני מנשיקות פיהו, ופירש\"י שהו\"ע טעמי תורה שיתגלו לעתיד, והיינו, שע\"י עבודת הבירורים בזמן הגלות יזכו לגילוי פנימיות התורה לעתיד לבוא ע\"י משיח צדקנו<sup data-n=\"1587\">52</sup>, במהרה בימינו בעגלא דידן.\n**********",[["1536","1","תוכן חלק מהמאמר – נכלל ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081200\" data-slug=\"likkutei-sichot\" data-id=\"1300081200\">לקו\"ש ח\"ח ע' 189</a> ואילך."],["1537","2","פרשתנו (מטות) לב, א-ה."],["1538","3","שם, כ-כב."],["1539","4","שם, יז."],["1540","5","אוה\"ת פרשתנו (מטות) ע' א'שלט."],["1541","6","ע' רפא ואילך."],["1542","7","מאמרי אדה\"ז תקס\"ה ח\"א ע' קצב ואילך. וראה גם ד\"ה בן פורת יוסף בתורת חיים ויחי קב, ב ואילך. אוה\"ת מקץ ח\"ו תתשב, א ואילך. ד\"ה ולא זכר שר המשקים תרל\"ג (סה\"מ תרל\"ג ח\"א ע' סג ואילך), ד\"ה הנ\"ל עזר\"ת (סה\"מ עזר\"ת ע' קג ואילך), תרפ\"ח (סה\"מ תרפ\"ח ע' כג ואילך). ד\"ה ומקנה רב תשכ\"א."],["1543","8","ראה לקו\"ת ר\"פ שלח."],["1544","9","ראה ויק\"ר פ\"ט, א. במדב\"ר פי\"ט, ג."],["1545","10","מכילתא ר\"פ בשלח. שם טז, ד."],["1546","11","תענית ט, א. פרש\"י חוקת כ, ב. ועוד."],["1547","12","ראה פרש\"י עקב ח, ד."],["1548","13","שלח יג, לב."],["1549","14","שם יד, ז."],["1550","15","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380461\" data-slug=\"likkutei-torah\" data-id=\"4001380461\">לקו\"ת שלח לז, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380465\" data-slug=\"likkutei-torah\" data-id=\"4001380465\">לח, ב</a>."],["1551","16","שם לז, א. וראה לקו\"ש ח\"ד ע' 1046 ואילך."],["1552","17","וישב לט, ד."],["1553","18","שם, כב."],["1554","19","מקץ מא, מ."],["1555","20","שם, מד."],["1556","21","שם מב, ח."],["1557","22","ב\"ר פע\"ו, א. ועוד."],["1558","23","וישלח לב, כה."],["1559","24","מלאכי א, ב."],["1560","25","ראה ד\"ה עם לבן גרתי לאדה\"ז – נדפס עם הגהות וכו' ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450566\" data-slug=\"or-hatorah-hb\" data-id=\"8316450566\">אוה\"ת</a> וישלח רלא, ב ואילך; תבא ע' תתרלו ואילך; קיצורים והערות לתניא ע' מט ואילך. ועוד."],["1561","26","בהבא לקמן – ראה מאמרי אדה\"ז שם (ע' ר). תו\"ח שם (קז, א ואילך). אוה\"ת וישב ח\"ו תתרחצ, סע\"א ואילך. ד\"ה ולא זכר שר המשקים תרל\"ג (סה\"מ תרל\"ג ח\"א ס\"ע סא ואילך), ד\"ה הנ\"ל עזר\"ת (סה\"מ עזר\"ת ס\"ע קב ואילך), תרפ\"ח (סה\"מ תרפ\"ח ע' כב ואילך)."],["1562","27","ב\"ר פע\"ה, יא."],["1563","28","וישב מ, יד."],["1564","29","פרש\"י ס\"פ וישב – מב\"ר פפ\"ט, ב."],["1565","30","שם, ג. הובא בפרש\"י שם."],["1566","31","תהלים מ, ה."],["1567","32","שער הבטחון פ\"ז."],["1568","33","שמואל-א טז, ב."],["1569","34","במאמרי אדה\"ז שם."],["1570","35","ראה פרי עץ חיים הקדמה לשער השבת פ\"א ואילך. ובכ\"מ."],["1571","36","ויגש מז, יד."],["1572","37","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370131\" data-slug=\"torah-or\" data-id=\"3901370131\">תו\"א וישב כח, א</a>-ב."],["1573","38","שבת פח, סע\"ב ואילך. וראה ד\"ה וכל העם ה'ש\"ת. ובכ\"מ."],["1574","39","ראה ד\"ה ומקנה רב (והמאמרים שלאחריו) בהמשך תרס\"ו."],["1575","40","ראה תנחומא בחוקותי ג. נשא טז. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. תניא רפל\"ו. ובכ\"מ."],["1576","41","ראה לקו\"ש שבהערה 1 ע' 190."],["1577","42","ראה תניא אגה\"ק ס\"ה (קט, א). ביאורי הזהר פ' וישב לאדמו\"ר האמצעי (כה, א-ב) ולאדמו\"ר הצ\"צ (ח\"א ע' קלד)."],["1578","43","יבמות קט, ב."],["1579","44","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380094\" data-slug=\"likkutei-torah\" data-id=\"4001380094\">לקו\"ת ויקרא ה, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380810\" data-slug=\"likkutei-torah\" data-id=\"4001380810\">פ' ראה כג, ג</a>."],["1580","45","לקו\"ת פ' ראה שם. ובכ\"מ."],["1581","46","הל' ת\"ת לאדה\"ז פ\"ג ס\"ד."],["1582","47","במדב\"ר פ\"ז, ח."],["1583","48","משלי כ, כא. וראה במדב\"ר סוף פרשתנו (פכ\"ב, ט)."],["1584","49","ראה ב\"ר פפ\"ג, א. וראה סה\"מ תרל\"ג ח\"א ע' לז. סה\"מ תרכ\"ז ע' תצה-ח."],["1585","50","פסחים קיט, א. וראה תו\"א ויגש מד, ב. שם, ד."],["1586","51","שה\"ש א, ב."],["1587","52","ראה ד\"ה והמשכילים יזהירו פ\"ב ואילך (לעיל ע' 29 ואילך) וש\"נ."]]],[1400350028,"בלתי מוגה\n<b>א</b>. בנוגע למ\"ש בהתחלת הפרשה \"וידבר משה גו' זה הדבר אשר צוה ה' וגו'\" – צריך להבין:\nכיון שכל ענין בתורה, ובפרט בתורה שבכתב, הוא בתכלית הדיוק – לשם מה נתפרש כאן \"זה הדבר אשר צוה ה'\", הרי כן הוא בכל הפרשיות שנאמרו ע\"י משה שהם הדברים אשר צוה ה'?\nואין לומר שהלשון \"זה הדבר\" קאי על דבר שצריך להראותו באצבע, כיון שאינו אלא לפי שעה, ואח\"כ לא יוכלו להראותו – שהרי פרשת נדרים אינה לפי שעה, אלא נוהגת בכל זמן.\nועכצ\"ל, שמ\"ש בפרשה זו \"זה הדבר אשר צוה ה'\", בא להורות על כל הציוויים שבתורה.\n<b>ב</b>. ויש להוסיף בזה:\nמבואר בדרושי חסידות<sup data-n=\"1588\">1</sup> על הפסוק \"זה הדבר\", שזהו ענין יחוד יסוד ומלכות, כי, \"דבר\" הוא בחי' מלכות, ו\"זה\" הוא בחי' יסוד, ו\"זה הדבר\" הוא יחוד יסוד ומלכות<sup data-n=\"1589\">2</sup>.\n[ומתאים גם להאמור לעיל שהלשון \"זה\" הוא על דבר שמורים עליו באצבע – כי, ע\"י יחוד יסוד ומלכות (\"זה הדבר\") נמשך גילוי אלקות בנבראים].\nוהרי ענין יחוד יסוד ומלכות הוא כללות המצוות – כדאיתא בפע\"ח<sup data-n=\"1590\">3</sup> שקודם כל מצוה צריך לומר \"לשם יחוד קוב\"ה ושכינתי'\": \"שכינתי'\" – בחי' ממלא, בחי' המלכות, ששוכנת בתחתונים, וקוב\"ה – בחי' סובב, בחי' יסוד, והיינו, שע\"י כל מצוה נעשה יחוד סובב וממלא<sup data-n=\"1591\">4</sup>, שענינו בספירות הוא יחוד יסוד ומלכות.ויחוד זה מתבטא בענין נצחיות התורה:\nאמרו חז\"ל<sup data-n=\"1592\">5</sup> \"בכל יום ויום יהיו בעיניך כחדשים\", ופעם אמרו<sup data-n=\"1593\">6</sup> \"חדשים\" (ללא כ\"ף הדמיון). והיינו, שאע\"פ שהתורה ניתנה לפני ריבוי שנים, מ\"מ, הרי זה תמיד ענין חדש, כי, \"כל הקורא ושונה הקב\"ה קורא ושונה כנגדו\"<sup data-n=\"1594\">7</sup>, ואין זה באופן שהקב\"ה רק חוזר את הדברים עוה\"פ, אלא באופן שנותנם עתה מחדש. וזהו גם מה שמדייק רבינו הזקן<sup data-n=\"1595\">8</sup> בנוסח ברכת התורה: \"נותן התורה\", לשון הוה, כיון שתמיד (בכל יום) ישנו הענין דנתינת התורה מחדש.\nוזהו שאמרו רז\"ל<sup data-n=\"1596\">9</sup> \"מה להלן באימה וביראה וברתת ובזיע אף כאן כו'\", וכמודגש בדרישת הבעש\"ט שכל עניני התומ\"צ יהיו מתוך חיות והתלהבות – דלכאורה כיצד אפשר שתהי' חיות והתלהבות בדבר שישנו כבר מלפני זמן רב – כיון שתמיד ישנה נתינת התורה מחדש<sup data-n=\"1597\">10</sup>.\n[ועד\"ז מצינו בנוגע לתפלה, כדאיתא בצוואת הריב\"ש<sup data-n=\"1598\">11</sup> שקודם כל תפלה צריך להיות מוכן שתכלה נפשו בתפלה, אף שכבר התפלל אתמול ושלשום כו' – כי בכל פעם הרי זו תפלה חדשה].\nוענין נצחיות התורה הוא מצד הענין דיחוד קוב\"ה ושכינתי' (\"זה הדבר\"):\nהחידוש שבנצחיות התורה הוא – שגם כפי שהתורה נמשכת למטה בגדרי הזמן הרי היא נצחית, שכן, למעלה הרי כל הענינים הם נצחיים, והחידוש בנוגע לתורה הוא שגם בהיותה למטה תחת הזמן, הרי היא נצחית.\nוענין זה הוא מצד יחוד קוב\"ה ושכינתי' – שגם בבחי' שכינתי', בחי' המלכות, ששם שייך גדר הזמן, ישנו גילוי בחי' קוב\"ה, שמצד זה נעשה ענין הנצחיות.\n<b>ג</b>. אך עדיין צריך להבין:\nמהו הטעם שההוראה הכללית בנוגע לכללות המצוות, \"זה הדבר אשר צוה ה'\", נאמרה בפרשת נדרים דוקא – בה בשעה שמצות נדריםאינה מצוה חיובית, שהרי יכול אדם לחיות ק\"כ שנה ולא לידור נדר, ויתירה מזה, כמ\"ש<sup data-n=\"1599\">12</sup> \"טוב אשר לא תדור גו'\", וא\"כ, הרי זה פחות אפילו ממצות שהם כמו רשות?\nוכיון שההוראה הכללית בנוגע לכל המצוות, \"זה הדבר אשר צוה ה'\", נאמרה במצות נדרים דוקא, הרי מובן, שמצות נדרים היא מצוה כללית.\n<b>ד</b>. ויובן ע\"פ הידוע (כפי שנתבאר כבר כמ\"פ<sup data-n=\"1600\">13</sup>), שכללות העולם כפי שהוא מצד הבריאה<sup data-n=\"1601\">14</sup>, נחלק לג' סוגים: (א) עניני קדושה, שבזה נכללת גם הנפש האלקית, שאינה צריכה תיקון כלל<sup data-n=\"1602\">15</sup>, (ב) מציאות הרע והקליפות כו', (ג) דברי הרשות, שזהו כללות ענין הבריאה, שבה היא עבודת הבירורים לעשות מזה קדושה.\n[ואין זה בסתירה להמבואר במ\"א<sup data-n=\"1603\">16</sup> שלפעמים יכולים לפעול בירור גם בג' קליפות הטמאות – כיון שלא זה הוא עיקר ענין העבודה.\nוכמו בנוגע לענין הקדושה ונה\"א<sup data-n=\"1604\">17</sup> – שאף שהנשמה עצמה אינה צריכה תיקון כלל, וירידתה לעוה\"ז היא רק בשביל תיקון הגוף ונפש הבהמית, הרי ע\"י הירידה למטה מתעלה גם הנשמה עצמה בעילוי שבאין ערוך, עד כדי כך, שבשביל זה היתה כדאי כל הירידה, אבל אעפ\"כ, כוונת הירידה אינה בשביל עליית הנשמה, כי אם, כדי לעשות לו ית' דירה בתחתונים ע\"י בירור הגוף ונה\"ב, אלא <b>שבדרך אגב</b> נעשית גם עליית הנשמה, וכמבואר בלקו\"ת<sup data-n=\"1605\">18</sup> ש\"תכלית המכוון בבריאת האדם אינו בשביל האדם עצמו לבד, אף שבאמת עלייתו נפלאה מאד\", שהרי \"להאדם מגיע שכר טוב לאין קץ\", אלא ש\"זהו <b>דרך טפל</b>, כדי שלא לקפח שכר כל ברי'\".\nועד\"ז בנוגע לענין הרע והקליפות – שאף שלפעמים יכול להיות בירור ג' קליפות הטמאות ע\"י העבודה דנסיונות (כמבואר בדרך מצוותיך בסופו<sup data-n=\"1606\">19</sup>), מ\"מ, אין זה עיקר העבודה, כי אם ענין שבדרך אגב כו'].\nועפ\"ז מובן הטעם שמצות נדרים היא מצוה כללית:\nכללות ענין הנדרים הוא בדברי הרשות דוקא, היינו, לא בעניניקדושה, כמו קרבן, שהוא קדוש גם ללא האדם (וצריך רק להתפיס בדבר הנדור, כמו קרבן<sup data-n=\"1607\">20</sup>, כמבואר הטעם ברמב\"ם<sup data-n=\"1608\">21</sup> ובדרך מצוותיך<sup data-n=\"1609\">22</sup>), ולא בדבר האסור, שאיסורו הוא גם ללא האדם, כי אם, בדברי הרשות דוקא.\nוכיון שכללות ענין הנדרים הוא בדברי הרשות דוקא – הרי זה קשור עם כללות העבודה שענינה הוא בירור דברי הרשות לעשותם כלים לאלקות, ועז\"נ \"זה הדבר אשר צוה ה'\", שהו\"ע יחוד קוב\"ה ושכינתי', שזוהי הנתינת כח על כללות העבודה בעניני הרשות לפעול בהם היחוד עם אלקות.\n<b>ה</b>. ובפרטיות יותר<sup data-n=\"1610\">23</sup> – יש ג' אופנים בסדר ההנהגה בעניני הרשות: (א) \"דייך מה שאסרה תורה\"<sup data-n=\"1611\">24</sup>, (ב) ענין הנדרים, שפורש גם מדבר המותר<sup data-n=\"1612\">25</sup>, (ג) התרת נדרים ע\"י חכם, כי, ענין הנדר הוא בבינה, ולכן, מצד בחי' החכמה שלמעלה מבינה, נעשה התרת הנדר. וג' אופנים אלו קשורים עם ג' המדריגות צדיקים בינונים ורשעים.\nובזה יובן גם הטעם שדין התרת נדרים ע\"י יחיד מומחה למדים ממ\"ש \"ראשי המטות\", ואילו ממ\"ש \"זה הדבר\" (שבזה מתחיל עיקר ענין פרשת נדרים) למדים \"להכשיר שלשה הדיוטות\"<sup data-n=\"1613\">26</sup> – כי, החכם הוא למעלה מעניני הרשות, שלכן בכחו להתיר את הנדר, ושייכותו לנדר היא ע\"ד נדרי מצוה (וע\"ד משנת\"ל בענין עליית הנשמה שע\"י העבודה דבירור הגוף ונה\"ב, שזהו רק ענין שבדרך טפל); ואילו עיקר ענין הנדר שהוא בדברי הרשות, מילי דהדיוטא – שייך להדיוטות (אלא שמצד ענין ההתכללות שבשלשה הדיוטות ישנו הכח להתיר את הנדר).\n***\n<b>ו</b>. על<sup data-n=\"1614\">27</sup> הכתוב \"ושפטו העדה גו' והצילו העדה\" שבסיום פרשתנו<sup data-n=\"1615\">28</sup>,אמרו רז\"ל<sup data-n=\"1616\">29</sup>: \"ומנין ל(סנהדרין) קטנה שהיא של עשרים ושלשה, שנאמר ושפטו העדה והצילו העדה, עדה שופטת ועדה מצלת, הרי כאן עשרים כו', ומנין להביא עוד שלשה כו'\". וצריך להבין מה שמסיים בכתוב \"והשיבו אותו <b>העדה</b> אל עיר מקלטו\", למה קורא הכתוב גם כאן את הב\"ד בשם עדה, ולא דיינים, שופטים וכיו\"ב?\nויובן זה עפ\"י משנ\"ת בהתוועדות י\"ב תמוז<sup data-n=\"1617\">30</sup> הטעם שלא מצינו חילוק לענין פרהסיא בין עשרה ליותר מעשרה – כי דבר שנעשה בפני עשרה מישראל הוא פרהסיא הכי גדולה, כיון שעשרה מישראל כוללים כל העולם. ולכן דבר מפורסם בפני עשרה הוא כמו שנתפרסם בכל העולם.\n\"המאבד נפש אחת מישראל כאילו איבד עולם מלא, וכל המקיים נפש אחת מישראל כאילו קיים עולם מלא\"<sup data-n=\"1618\">31</sup>. ולכן דינו של הורג נפש<sup data-n=\"1619\">32</sup> מישראל – חטא הנוגע ב\"עולם מלא\" – הוא בפני עדה דוקא, עשרה מישראל, הכוללים את כל עניני העולם, שלכן מרגישים הם את הפגם במילואו.\nכמו שבריאת העולם היתה ע\"י כל שלושת הקוים, כמארז\"ל<sup data-n=\"1620\">33</sup>: אמר הקב\"ה אם בורא אני את העולם במדת הרחמים (קו הימין) הוי חטיי' סגיאין, במדת הדין (קו השמאל) היאך העולם יכול לעמוד, אלא הרי אני בורא אותו במדת הדין ובמדת הרחמים (התכללות, קו האמצעי) – כן גם תיקון ובנין העולם שנאבד ע\"י ההורג נפש, הוא ע\"י שלושת הקוין: בתחילה<sup data-n=\"1621\">34</sup> – \"<b>ושפטו</b> העדה\" (מדת הדין), אח\"כ – \"<b>והצילו</b> העדה\" (חסד)<sup data-n=\"1622\">35</sup>, תיקונו בפועל – \"והשיבו אותו העדה אל עיר מקלטו\" – כפרת ותיקון החטא ע\"י גלות דערי מקלט – מצד קו האמצעי המכריע בין חסד וגבורה<sup data-n=\"1623\">36</sup>.<b>ז</b>. וההוראה מזה – עד כמה נוגע כל פרט ופרט בעבודת האדם.\nוכדאיתא בגמרא<sup data-n=\"1624\">37</sup> \"לעולם יראה אדם עצמו כאילו חציו חייב וחציו זכאי, עשה מצוה אחת, אשריו שהכריע עצמו לכף זכות\", ועד\"ז להיפך כו'. והביאור הפנימי בזה – שכשם שבמצוות אמרו רז\"ל<sup data-n=\"1625\">38</sup> \"העוסק במצוה פטור מן המצוה\", לפי שכל המצוות כלולות זו מזו<sup data-n=\"1626\">39</sup>, כן הוא גם בעבירות, שכל עבירה כלולה כו', ולכן, כל ענין פרטי בתומ\"צ נוגע לכללות נפשו.\nויתירה מזה – כיון שגם \"העולם נידון אחר רובו\", הרי \"עשה מצוה אחת, אשריו שהכריע את עצמו <b>ואת כל העולם</b> לכף זכות\" (כיון שעל ידו כל העולם הוכרע להיות רובן צדיקים)<sup data-n=\"1627\">40</sup>. והביאור הפנימי בזה – כיון שכל נפש אחת מישראל היא \"עולם מלא\", ולכן מצבו הפרטי של כל אחד מישראל נוגע לכל העולם.\nולאחרי כל זה, הנה גם כאשר חטא ופגם כו', אין לו להתייאש ח\"ו, ועד כדי כך, שמצינו שהבעש\"ט בכה אפילו על מסית ומדיח, באמרו, שגם אבר המדולדל יש לו תקוה כו'<sup data-n=\"1628\">41</sup>, כיון שביכלתו לתקן כל הענינים ע\"י התשובה, שזהו\"ע ערי מקלט כו'.\n***\n<b>ח</b>. צוה לנגן ואמר מאמר ד\"ה ומקנה רב גו'.\n***\n<b>ט</b>. אודות חודש מנחם-אב שמתברך ביום הש\"ק זה, אמרו חז\"ל<sup data-n=\"1629\">42</sup> \"משנכנס אב ממעטין בשמחה\".וכיון שענין זה הוא ציווי בתורה, שכללותה הו\"ע השמחה, הרי מובן, שהענין ד\"ממעטין בשמחה\" גופא צריך להיות מתוך שמחה.\nונקודת הענין – שזהו ענין של מרירות, ולא עצבות<sup data-n=\"1630\">43</sup>, והרי ענין המרירות יכול להיות באופן של בכי' מסטרא דא וחדוה מסטרא דא<sup data-n=\"1631\">44</sup>.\nובטעם השמחה – כמה פרטים:\nא) כיון שזהו ציווי הקב\"ה, יש לקיים זאת בשמחה.\nב) ובפרט בידעו שסיבת הגלות היא מצד החטא, ואעפ\"כ, גם במצב כזה נותנים לו הוראות וציוויים כו' – הרי בודאי שצריך לקיימם בשמחה. וע\"ד השמחה שמצד קירוב המלך לאיש הדיוט ושפל אנשים כו', כמבואר בתניא<sup data-n=\"1632\">45</sup>.\nג) ומה גם שהציוויים וההוראות הם בנוגע לתיקון החטא, וכמ\"ש<sup data-n=\"1633\">46</sup> \"רחץ ה' את צואת בנות ציון\".\nד) ע\"פ המבואר במארז\"ל<sup data-n=\"1634\">47</sup> \"יפה שעה אחת בתשובה ומעשים טובים בעולם הזה מכל חיי העולם הבא\", לפי שחיי העוה\"ב הו\"ע נח\"ר נברא, ואילו התשובה ומעשים טובים בעוה\"ז הו\"ע נח\"ר בורא<sup data-n=\"1635\">48</sup>. ועד\"ז בנדו\"ד, שכל ענין הגלות כו' הוא רק בנוגע לסדר ההשתלשלות, ואילו קיום ציווי הקב\"ה הו\"ע נח\"ר בורא.\nוזהו גם ענין השמחה שבחמשה עשר באב, ששייך ליום הכיפורים, כמארז\"ל<sup data-n=\"1636\">49</sup> \"לא היו ימים טובים לישראל כחמשה עשר באב וכיום הכיפורים\" – לפי שבשניהם מודגשת מעלת עבודת התשובה לגבי עבודת הצדיקים.\n*\n<b>י</b>. ידוע שבעבודת הבירורים ישנם ב' אופנים<sup data-n=\"1637\">50</sup> – שזהו החילוק שבין זמן הבית לזמן הגלות:\nבזמן הבית הי' נעשה בירור הניצוצות בדרך ממילא, והיינו, שגם ניצוצות הקדושה שנמצאו בארץ העמים, שגזרו עלי' טומאה כו'<sup data-n=\"1638\">51</sup>, היומתקבצים מאליהם מצד ריבוי אור הקדושה שבארץ ישראל, כמשל האבוקה שנמצאת במקומה וכל הניצוצות נמשכים אלי' להכלל בה.\nמשא\"כ בזמן הגלות – הרי זה בדוגמת אור הנר בלבד, שאין בכחו לקבץ אליו את הניצוצות כו', ולכן יש צורך לבוא להמקום שבו נמצא הניצוץ כדי לבררו כו', כמארז\"ל<sup data-n=\"1639\">52</sup> \"אחד מכם גולה לברבריא וכו'\", וכמאמר הבעש\"ט (שנדפס בהוספות ללקו\"ת<sup data-n=\"1640\">53</sup>) ש\"נתפזרו ישראל בכל מקומות הארץ באיים רחוקים . . כדי לטהר ארץ העמים שאוירה טמא . . באמונתם הפשוטה כו'\".\nומטעם זה הנהיג כ\"ק מו\"ח אדמו\"ר<sup data-n=\"1641\">54</sup>, שבמשך כמה שבועות יסעו למקומות שונים כדי לפעול בירור הניצוצות כו', שזהו גם ענין של פדיון שבויים, שבזה היתה תחילת עבודתו של הבעש\"ט (כמשנ\"ת בהתוועדויות שלפנ\"ז<sup data-n=\"1642\">55</sup>), והרי הדברים קל וחומר: אם ע\"י אמונה פשוטה פועלים הבירור בארץ העמים – עאכו\"כ כאשר ממלאים את רצון המשלח בהפצת היהדות ובפרט בהפצת המעיינות, הרי בודאי שפועלים הבירור כו'.\nוגם שליחות זו היא ענין כללי (ע\"ד משנת\"ל בענין הנדרים ובענין ערי מקלט), ולכן צריך כל אחד להשתדל ליטול חלק בשליחות זו, ומה גם שעי\"ז הרי הוא מוציא י\"ח את אלו שנשארים בבתיהם.\n***\n<b>יא</b>. בתפלת מנחה מתחילים לקרוא פרשת דברים – \"אלה הדברים אשר דבר משה גו'\", ש\"משה מפי עצמו אמרן\"<sup data-n=\"1643\">56</sup>, \"וברוח הקודש\" (כמ\"ש התוס'<sup data-n=\"1644\">57</sup>), אבל אעפ\"כ, הרי זה ירידה לגבי ד' הספרים שלפנ\"ז, שלא ניכר האלקות בגילוי.\nומצד ירידה זו יש נתינת מקום לענין הגלות כו', וזהו הטעם שקורין פרשה זו בהתחלת חודש מנ\"א, קודם התיקון כו'.\nולאידך גיסא, הנה בסיום ספר דברים נאמר<sup data-n=\"1645\">58</sup> \"עד הים האחרון\", ואיתא בספרי<sup data-n=\"1646\">59</sup> \"עד היום האחרון\", דקאי על הזמן דביאת המשיח – כי, דוקא ע\"י ירידת הגלות באים לתכלית העילוי דביאת המשיח, והיינו,שכללות ענין הגלות אינו עונש בלבד, כי אם, ענין של בירור ותיקון, שעי\"ז נעשית עלי' גדולה ביותר.\nוע\"ד שנתבאר לעיל (בהמאמר<sup data-n=\"1647\">60</sup>), שע\"י הירידה שבהכניסה לארץ לעסוק בענינים גשמיים (היפך חטא המרגלים), מגיעים להבחי' ד\"טובה הארץ מאד מאד\"<sup data-n=\"1648\">61</sup>.\nוזהו גם ענין הנסיעות בכדי לברר הניצוצות כו', שעי\"ז באים לעילוי גדול יותר.\nואף שישנו סדר העבודה של בני גד ובני ראובן שלא נכנסו לארץ – הרי זה שייך רק לחלק קטן מבנ\"י, ולא לרוב בנ\"י, ובפרט בזמן הזה, שכל בנ\"י הם (לא מעשרת השבטים, אלא) משבט יהודה ובנימין.\nוכאמור, שדוקא ע\"י הירידה נעשית תכלית העלי' דאתי מר דא מלכא משיחא.\n**********",[["1588","1","ראה אוה\"ת פרשתנו (מטות) ע' א'רפד ואילך."],["1589","2","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380908\" data-slug=\"likkutei-torah\" data-id=\"4001380908\">נתבאר גם הענין ד</a>\"כה לחי\" (ראה לקו\"ת נצבים מז, ב), ש\"כה\" (\"כדמותנו\") הוא בחי' מלכות, וזהו ענין בכ\"ה באלול נברא העולם, להיות נראה העולם ליש ודבר, ואח\"כ צ\"ל ביטול היש, ע\"י המשכת בחי' זה, שזהו ענינו של ר\"ה, \"זה היום תחלת מעשיך\"."],["1590","3","שער ו (שער הזמירות) ספ\"ה. וראה הנסמן בתו\"מ סה\"מ אלול ע' רמה הערה 60."],["1591","4","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370320\" data-slug=\"torah-or\" data-id=\"3901370320\">תו\"א יתרו עב, סע\"א</a>. לקו\"ת ואתחנן ט, סע\"א ואילך. ובכ\"מ."],["1592","5","ספרי ופס\"ז ואתחנן ו, ו. שו\"ע אדה\"ז או\"ח סס\"א ס\"ב."],["1593","6","פרש\"י יתרו יט, א. עקב יא, יג. תבוא כו, טז."],["1594","7","תדבא\"ר רפי\"ח. יל\"ש איכה רמז תתרלד."],["1595","8","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380172\" data-slug=\"likkutei-torah\" data-id=\"4001380172\">לקו\"ת תזריע כג, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380904\" data-slug=\"likkutei-torah\" data-id=\"4001380904\">נצבים מו, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381050\" data-slug=\"likkutei-torah\" data-id=\"4001381050\">דרושי סוכות פא, ג</a>."],["1596","9","ברכות כב, א. וש\"נ."],["1597","10","ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370301\" data-slug=\"torah-or\" data-id=\"3901370301\">תו\"א יתרו סז, ב</a>."],["1598","11","סל\"ה-מב."],["1599","12","קהלת ה, ד. וראה נדרים ט, סע\"א."],["1600","13","ראה תו\"מ חכ\"ז ע' 211. וש\"נ."],["1601","14","בכל פרטי הענינים דעולם שנה ונפש."],["1602","15","ע\"ח שער כ\"ו פ\"א. הובא ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, ב</a>)."],["1603","16","ראה גם ב\"לקוטי פירושים\" שב\"מ\"מ, הגהות והערות קצרות\" לתניא פ\"ז (ע' סה). וש\"נ."],["1604","17","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151260\" data-slug=\"likkutei-sichot\" data-id=\"1300151260\">לקו\"ש חט\"ו ע' 247</a> ואילך."],["1605","18","פ' ראה כח, ד ואילך."],["1606","19","קצא, ב."],["1607","20","נדרים יד, א."],["1608","21","בפיהמ\"ש שלו נדרים רפ\"ב."],["1609","22","סהמ\"צ להצ\"צ מצות נדרים (מב, סע\"ב ואילך)."],["1610","23","ראה גם ד\"ה לה\"ע הנדרים דש\"פ מטות, מבה\"ח מנ\"א תשי\"ד פ\"ה ואילך (תו\"מ חי\"ב ע' 131 ואילך). וש\"נ. לקו\"ש חל\"ג ע' 191 ואילך. וש\"נ."],["1611","24","ירושלמי נדרים פ\"ט ה\"א. רמב\"ם הל' דעות פ\"ג ה\"א."],["1612","25","ומש\"נ \"טוב אשר לא תדור גו'\" – יש לבאר ע\"ד המבואר ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380832\" data-slug=\"likkutei-torah\" data-id=\"4001380832\">לקו\"ת (פ' ראה כט, א</a>) בפירוש מארז\"ל (עירובין יג, ב) \"נוח לו לאדם שלא נברא\", \"ולא אמרו ח\"ו טוב לו שלא נברא, דזה אי אפשר לומר, שהרי הירידה והבריאה . . היא בשביל עלי' גדולה ונפלאה כו'\", ובודאי שזוהי טובתו כו', אלא \"ש<b>נוח וקל</b> הי' לו שלא נברא כו'\"."],["1613","26","נדרים עח, א. וש\"נ."],["1614","27","סעיף זה הוגה ע\"י כ\"ק אדמו\"ר שליט\"א, ונדפס בהוספות ללקו\"ש ח\"ד ע' 1332. במהדורא זו ניתוספו עוד איזה ציוני מ\"מ, וכמה פרטים מהנחה בלתי מוגה."],["1615","28","מסעי לה, כד-כה."],["1616","29","סנהדרין ב, סע\"א."],["1617","30","ס\"ה ואילך (לעיל ס\"ע 189 ואילך)."],["1618","31","סנהדרין פ\"ד מ\"ה."],["1619","32","ולהעיר, שע\"פ הידוע שע\"י כל חטא נעשה \"מכה נפש\" בדקות (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380362\" data-slug=\"likkutei-torah\" data-id=\"4001380362\">לקו\"ת במדבר יג, ג</a>), הרי זה ענין ששייך לכל אחד מישראל, כי \"אין צדיק בארץ אשר יעשה טוב ולא יחטא\" (קהלת ז, כ), ועד שאפילו אלו שמתו בעטיו של נחש (שבת נה, ב. וש\"נ), הנה גם אצלם ישנו ענין זה, אלא שהוא בדקות כו' (מהנחה בלתי מוגה)."],["1620","33","ב\"ר פי\"ב, טו."],["1621","34","ע\"ד מארז\"ל (רש\"י בראשית בתחלתו. ס' הלקוטים להאריז\"ל בתחלתו. ובכ\"מ. – וראה מדרש ילמדנו הובא בתלמוד תורה (נדפס בבתי מדרשות (ורטהימר) כרך א)) <b>בתחילה</b> עלה במחשבה לברוא את העולם במדת הדין כו' שיתף עמו מדת הרחמים."],["1622","35","ובשביל זה יש צורך בעדה בפני עצמה (ולא אלו שעליהם נאמר \"ושפטו העדה\") – ע\"ד שמצינו בגמרא (ר\"ה כו, רע\"א) בביאור הטעם ש\"אין עד נעשה דיין\", \"דרחמנא אמר ושפטו העדה והצילו העדה, וכיון דחזיוהו דקטל נפשא לא מצו חזו לי' זכותא\" (מהנחה בלתי מוגה)."],["1623","36","ובזה י\"ל בדא\"פ מה שהורה רבינוהזקן בסידורו (בסדר התרת נדרים) \"וטוב שיהא עדה שלימה\" – כי הטעם להתרת נדרים בערב ר\"ה הוא לפי שבר\"ה הוא בנין העולם מחדש, וההכנה לזה, הוא תיקון כללות העולם (כידוע שכל עניני העולם נחלקים לג' סוגים: מצוה, רשות ועבירה, ועיקר הבריאה, ועבודת הבירורים שבה, הוא בדברי הרשות, ונדרים ענינם – המשכת קדושה בעניני הרשות, ועד\"ז התרת נדרים*), ותיקון כללות העולם אפשרי ע\"י עשרה מישראל, עדה <b>שלימה</b>, שלימות כל העולם."],["1624","37","קידושין מ, סע\"א ואילך."],["1625","38","סוכה כה, סע\"א. וש\"נ."],["1626","39","ראה סה\"מ תרנ\"ה ע' לז. המשך תרס\"ו ס\"ע סח. ע' תקכב. סה\"מ קונטרסים ח\"ב תלה, ב."],["1627","40","קידושין שם, ריש ע\"ב (ובפרש\"י)."],["1628","41","ראה שבחי הבעש\"ט (הוצאת מונדשיין, ירושלים תשמ\"ב) ע' 157. וראה גם תו\"מ ח\"כ ע' 114."],["1629","42","תענית כו, ב (במשנה). כט, סע\"א.\n*) <b>כמבואר בלקו\"ש ח\"ד ע' 1076 ואילך</b>."],["1630","43","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310036\" data-slug=\"tanya\" data-id=\"3401310036\">תניא פל\"א</a>."],["1631","44","ראה זח\"ג עה, א. הובא ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310039\" data-slug=\"tanya\" data-id=\"3401310039\">תניא ספל\"ד</a>. אגה\"ת רפי\"א."],["1632","45","פמ\"ו."],["1633","46","ישעי' ד, ד. וראה תניא אגה\"ק סכ\"ב."],["1634","47","אבות פ\"ד מי\"ז."],["1635","48","ראה המשך וככה תרל\"ז פי\"ב."],["1636","49","תענית כו, ב (במשנה). ל, ב."],["1637","50","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370021\" data-slug=\"torah-or\" data-id=\"3901370021\">תו\"א בראשית ה, סע\"ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380324\" data-slug=\"likkutei-torah\" data-id=\"4001380324\">לקו\"ת במדבר ד, א</a>. ובכ\"מ."],["1638","51","גיטין ח, ב. וש\"נ."],["1639","52","שהש\"ר פ\"ב, ח."],["1640","53","יח, רע\"ד. וראה כתר שם טוב (הוצאת תשנ\"ט) בהוספות סקס\"ד. וש\"נ."],["1641","54","ראה גם לעיל ע' 217. וש\"נ."],["1642","55","שיחת יום ב' דחג השבועות ס\"ב וסי\"ד (לעיל ע' 111, וע' 121)."],["1643","56","מגילה לא, ב. וראה זח\"ג רסא, א."],["1644","57","ד\"ה משה – מגילה שם."],["1645","58","ברכה לד, ב."],["1646","59","הובא בפרש\"י עה\"פ."],["1647","60","פ\"ב (לעיל ע' 251)."],["1648","61","שלח יד, ז."]]],[1400350029,"<h3>בס\"ד. ש\"פ עקב, כ\"ף מנחם-אב, ה'תש\"כ<sup data-n=\"1649\">*</sup></h3>\n(הנחה בלתי מוגה)\n<b>לא</b> היו ימים טובים לישראל כחמשה עשר באב וכיום הכיפורים כו'<sup data-n=\"1650\">1</sup>, ואיתא בפע\"ח<sup data-n=\"1651\">2</sup> (הובא בחסידות<sup data-n=\"1652\">3</sup>), שמעלת היום דט\"ו באב היא משום שבו הוא מילוי הלבנה, קיימא סיהרא בשלמותא<sup data-n=\"1653\">4</sup>. וצריך להבין<sup data-n=\"1652\">3</sup>, דהרי ענין זה דקיימא סיהרא באשלמותא הוא ביום ט\"ו שבכל חודש, ובמה היא מעלת יום הט\"ו בחודש אב. ועוד זאת, דגם הימים טובים דפסח וסוכות גם הם בט\"ו לחודש, וא\"כ במה גדלה מעלת ט\"ו לחודש אב על פסח וסוכות, עד שאמרו רז\"ל לא היו ימים טובים לישראל כט\"ו באב. ונקודת הביאור בזה<sup data-n=\"1654\">5</sup>, דמעלת היום דט\"ו באב הוא משום שהעלי' דקיימא סיהרא באשלמותא באה לאחרי הירידה דט' באב, ולפי הכלל דירידה צורך עלי' מובן אשר ככל שהירידה גדולה יותר כך העלי' הבאה אחרי' ועל ידה היא גדולה יותר<sup data-n=\"1655\">6</sup>, ובזה היא מעלת יום ט\"ו לחודש אב, שבו העלי' דקיימא סיהרא באשלמותא היא עלי' גדולה ביותר, משום שבאה לאחרי (וע\"י) הירידה שלפני זה, שהיא ירידה גדולה ביותר.\nב) <b>וביאור</b> הענין הוא<sup data-n=\"1656\">7</sup>, דהנה סיהרא קאי על ספירת המלכות, דכשם שסיהרא (הלבנה) לית לה מגרמה כלום<sup data-n=\"1657\">8</sup> (שאין האור הבא ממנה אלא אור השמש המאיר על ידה), כך גם ספירת המלכות לית לה מגרמה כלום. ופירוש הדברים הוא<sup data-n=\"1658\">9</sup>, לא שסיהרא (מלכות) אין לה אור כלל, אלא הכוונה היא שיש לה אור שהוא אור עצמי (שאינו מאיר). וזהו מה שהמלכות נאצלה בסוד נקודה, שיש בזה ב' שיטות מהי הנקודה, אםכתר שבמלכות או מלכות שבמלכות. אבל אור המאיר והמתגלה (אל הזולת) אין לה מעצמה כלום. ובשביל שיהי' בה אור המאיר, ה\"ז ע\"י ההמשכה במלכות מהספירות שלמעלה הימנה, ושלימות המשכה זו היא בט\"ו לחודש דאז קיימא סיהרא באשלמותא, שאז האור המאיר דמלכות הוא בתכלית שלימותו.\n<b>וזהו</b><sup data-n=\"1659\">10</sup> מ\"ש<sup data-n=\"1660\">11</sup> ויתרון ארץ בכל היא מלך לשדה נעבד<sup data-n=\"1661\">12</sup>. ארץ קאי על ספירת המלכות כנודע. ויתרון ארץ, היינו היתרון שנעשה בספירת המלכות, הוא ע\"י בכל, ספירת היסוד<sup data-n=\"1662\">13</sup>, שע\"י היסוד נמשכים בספירת המלכות נ' שערי בינה, דזהו בכל, כל בגימטריא נ'<sup data-n=\"1663\">14</sup>. אמנם זהו סדר הענינים מצד עצמו, אך למעלה מזה הוא מה שכתוב לאחרי זה מלך לשדה נעבד, שזה מורה על עלי' מיוחדת בספירת המלכות. ובזה איתא ב' פירושים. פירוש א' כדאיתא בזוהר<sup data-n=\"1664\">15</sup> דמלך קאי על מלך עילאה, דהיינו ספירת הכתר שלמעלה מהשתלשלות, ופירוש מלך לשדה נעבד הוא המשכת הכתר למלכות, שהמלכות נקראת בשם שדה. ופירוש ב' בזוהר שם, דמלך קאי על ספירת המלכות, ומלך לשדה נעבד קאי על ירידת המלכות לעולמות בי\"ע הנק' בשם שדה, דאית שדה ואית שדה, אית שדה דקדושה שהיא ספירת המלכות, ואית שדה דלעו\"ז, ולפי פירוש זה שדה כאן קאי על שדה דלעו\"ז, שהמלכות יורדת לברר בירורים בשדה דלעו\"ז, וכמאמר<sup data-n=\"1665\">16</sup> רגלי' יורדות מות, שהמלכות יורדת לבי\"ע לברר את הניצוצות. אך דוקא ע\"י ירידה זו דמלכות לברר בירורים בבי\"ע הרי ירידה צורך עלי', ועי\"ז היא עולה למעלה מעלה, גם למעלה מבחינת המשכת הכתר במלכות<sup data-n=\"1666\">17</sup>.\nג) <b>ובזה</b> יובן ענין ט\"ו לחודש בכלל, דאז קיימא סיהרא באשלמותא, שמעלה זו בלבנה (ובמלכות) באה תמיד לאחר הירידה שבזמןהמולד, שאז הלבנה היא בהעלם והסתר, ואחרי הירידה דהעלם והסתר הלבנה בזמן המולד, באה העלי' דקיימא באשלמותא. אמנם עלי' זו עצמה אפשר שיהיו בה שינויים, שאין היא עלי' נצחית, ואפשר שתהי' אחרי' ירידה, ויש עלי' נעלית מזו, שהיא עלי' נצחית שאי אפשר שתהי' ירידה אחרי'.\n<b>ובזה</b> יובן<sup data-n=\"1667\">18</sup> החידוש דט\"ו באב לגבי ענין קיימא סיהרא באשלמותא בכלל. דבכל חודש הרי ענין העלי' שבסיהרא הוא באופן שאפשר שתהי' אחריו ירידה. ואפילו ט\"ו לחודש ניסן שהוא חג הפסח, הרי יציאת מצרים היתה גאולה שיש אחרי' גלות<sup data-n=\"1668\">19</sup>. ועד\"ז הוא לגבי בנין בית ראשון, כדאיתא במדרש<sup data-n=\"1669\">20</sup> ששלמה הי' בדור הט\"ו לאברהם דאז קיימא סיהרא באשלמותא, ולכן על ידו נבנה הבית. הרי גם עלי' זו אינה עלי' נצחית, שהרי אחר כך נחרב הבית. אמנם העלי' דט\"ו לחודש אב, להיות שהיא באה לאחרי הירידה דתשעה באב, שהיא ירידה גדולה ביותר, הרי העלי' היא לפי ערך הירידה, ועלי' זו בספירת המלכות היא בבחי' עלי' שאין אחרי' ירידה, שהיא העלי' דלעתיד לבוא.\nד) <b>ועפ\"ז</b> יובן<sup data-n=\"1670\">21</sup> גם מה שאמרו במדרש<sup data-n=\"1671\">22</sup> על הפסוק<sup data-n=\"1672\">23</sup> נחמו נחמו עמי, שהנחמה היא בכפליים כנגד חורבן בית ראשון וחורבן בית שני, ולכאורה אינו מובן, דהרי בכלל מאתיים מנה<sup data-n=\"1673\">24</sup>, דבית ראשון הוא נעלה יותר מבית שני, שהרי בבית שני חסרו ה' דברים<sup data-n=\"1674\">25</sup>, ואם כן כיון שכבר ישנה הנחמה על חורבן בית ראשון, מהו הצורך בנחמה נוספת על חורבן בית שני. אך הענין יובן ע\"פ הנ\"ל שירידה היא לצורך עלי', ולאחרי הירידה העלי' היא גדולה יותר מלפני הירידה. ולפי זה עכצ\"ל שיש מעלה בבית שני על בית ראשון, משום שבנין בית שני הי' לאחר חורבן בית ראשון, היינו עלי' שאחרי הירידה. וכמעלת בעלי תשובה על הצדיקים<sup data-n=\"1675\">26</sup>. ולכן צ\"ל נחמה מיוחדת גם על חורבן בית שני, היינו גם על מעלה זו שהיתה בבית שני.<b>וזהו</b> נחמו נחמו עמי גו', דלאחר הירידה דתשעה באב בחורבן בית ראשון ובית שני תהי' לעתיד לבוא העלי' שלפי ערך הירידה, היינו עלי' נצחית שאין אחרי' גלות&lt;19&gt;, ויהיו בעלי' זו ב' המעלות, הן מעלת בית ראשון שהיו בו אותם ה' דברים שחסרו בבית שני, והן מעלת בית שני שהיא מעלת התשובה.\n**********",[["1649","*","ראשי-פרקים (<b>המו\"ל</b>)."],["1650","1","תענית כו, ב במשנה."],["1651","2","סוף שער חג השבועות – דרוש \"על סוד ט\"ו באב\"."],["1652","3","ד\"ה נחמו עת\"ר (סה\"מ עת\"ר ע' ריח. ע' רכא). וראה גם אוה\"ת ואתחנן ח\"ו ע' ב'קצז ואילך."],["1653","4","זח\"א קנ, רע\"א. ח\"ב פה, א."],["1654","5","ראה סה\"מ עת\"ר שם ע' ריט ואילך. ע' רכט ואילך. וראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450626\" data-slug=\"or-hatorah-hb\" data-id=\"8316450626\">אוה\"ת שם ע' ב'קצח</a>. נ\"ך ח\"ב ע' א'צו."],["1655","6","אוה\"ת נ\"ך שם וסה\"מ עת\"ר שם ע' ריט. ע' רכו – עפ\"י ד\"ה לסוסתי תקס\"ד (מאמרי אדה\"ז תקס\"ד ע' כה ואילך)."],["1656","7","סה\"מ עת\"ר שם ע' ריח. ע' רכא ואילך."],["1657","8","ראה זהר ח\"א רמט, ב. ח\"ב רטו, א. ועוד."],["1658","9","ראה גם סידור (עם דא\"ח) קפב, ד. פירוש המלות לאדמו\"ר האמצעי פרק מח (כט, ב ואילך). המשך תרס\"ו ע' תד."],["1659","10","סה\"מ עת\"ר שם ע' ריח ואילך. ע' רכב ואילך. וראה גם ד\"ה לא היו יו\"ט לישראל כט\"ו באב תשל\"ה פרק ג ואילך (תו\"מ סה\"מ אב ע' קסח ואילך. שם ע' שיב ואילך). תשמ\"ו."],["1660","11","קהלת ה, ח."],["1661","12","בסה\"מ עת\"ר שם מציין למאמר דש\"פ חיי שרה תר\"ל (סה\"מ תר\"ל ע' יט ואילך). וראה גם ביאורי הזהר לאדמו\"ר האמצעי (בהוספות) חיי שרה קכט, ג ואילך."],["1662","13","ראה זח\"ג רנז, סע\"א (ברע\"מ). פרדס שער יג (שער השערים) ספ\"ו. שער כג (שער ערכי הכינויים) מערכת כל כלה. ל\"ת להאריז\"ל וישב מ, א. ועוד."],["1663","14","ראה פרדס שם. ועוד."],["1664","15","ח\"א קכב, א."],["1665","16","משלי ה, ה. וראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600564\" data-slug=\"or-hatorah-hb\" data-id=\"8316600564\">אוה\"ת נ\"ך</a> עה\"פ (ח\"א ע' תקסד ואילך)."],["1666","17","ראה ד\"ה לא היו יו\"ט לישראל כו' תשל\"ה שבהערה 10 (תו\"מ סה\"מ שם)."],["1667","18","ראה סה\"מ עת\"ר שם ע' רכ. ע' רכח ואילך."],["1668","19","ראה מכילתא בשלח טו, א. תוד\"ה ה\"ג ונאמר – פסחים קטז, ב."],["1669","20","שמו\"ר פט\"ו, כו."],["1670","21","ראה סה\"מ עת\"ר שם ע' רכ. ע' רלא."],["1671","22","איכ\"ר ספ\"א. יל\"ש ישעי' רמז רמה."],["1672","23","ישעי' מ, א."],["1673","24","לשון חז\"ל – ב\"ק עד, א. ב\"ב מא, ב."],["1674","25","יומא כא, ב."],["1675","26","ראה ברכות לד, ב. רמב\"ם הל' תשובה פ\"ז ה\"ד."]]],[1400350030,"<h3>בס\"ד. משיחות<sup data-n=\"1676\">*</sup><b> ש\"פ עקב, כ\"ף מנחם-אב, ה'תש\"כ.</b></h3>\nבלתי מוגה\n<b>א</b>. א' הענינים העיקריים דפרשת השבוע הוא – \"ואכלת ושבעת וברכת את ה' אלקיך וגו'\"<sup data-n=\"1677\">1</sup>, שזהו ענין עיקרי וכללי בחיי האדם, שהרי ע\"י האכילה נעשה חיות וקיום האדם, ומה גם שאכילה כוללת כל צרכי האדם<sup data-n=\"1678\">2</sup>, וכשהאדם מקבל צרכיו, ה\"ז בדוגמת ענין השביעה, ואז צריך לברך להקב\"ה כו'.\nויש לבאר גם הקשר והשייכות דברכת המזון (\"ואכלת ושבעת וברכת גו'\") עם התחלת הפרשה – \"והי' עקב תשמעון וגו' ושמר ה' אלקיך לך את הברית גו' אשר נשבע גו'\":\nמבואר בדרושי חסידות<sup data-n=\"1679\">3</sup> שכללות הענין ד\"ברית\" ו\"שבועה\" (\"הברית גו' אשר נשבע\") הוא המשכה <b>שלמעלה מהשתלשלות</b> – \"כמו למשל שני אוהבים שכורתים ברית ביניהם . . שיתייחדו ויתקשרו באהבתם בקשר נפלא ולמעלה מן הטעם ודעת, אף שע\"פ הטעם והדעת הי' צריך לפסוק האהבה וכו'\"<sup data-n=\"1680\">4</sup>.\nוענין זה נעשה ע\"י העבודה באופן ד\"והי' עקב תשמעון\", כפירוש רש\"י \"אם המצוות הקלות שאדם דש בעקביו תשמעון\" – שזוהי עבודה <b>שלמעלה מטעם ודעת</b>, כי, מצד טעם ודעת, יש מקום לחלק בין מצוות חמורות למצוות קלות, מצוות שבין אדם למקום ומצוות שבין אדם לחבירו, וכיו\"ב, וכדי שיהי' \"עקב תשמעון\", גם ב\"מצוות קלות שאדם דש בעקביו\", ה\"ז דוקא ע\"י עבודה מצד קבלת עול שלמעלה מטעם ודעת.\nוזהו \"והי' עקב תשמעון וגו' ושמר ה' אלקיך לך את הברית גו' אשר נשבע גו'\" – שכאשר העבודה היא למעלה מטעם ודעת (\"עקב תשמעון\"), נעשית גם ההמשכה למעלה באופן כזה (\"מדה כנגד מדה\"<sup data-n=\"1681\">5</sup>)– המשכה שלמעלה מהשתלשלות (\"ושמר גו' את הברית גו' אשר נשבע גו'\").\nוענין זה מודגש גם בברכת המזון:\nאיתא בגמרא<sup data-n=\"1682\">6</sup> \"אמרו מלאכי השרת לפני הקב\"ה, רבש\"ע, כתוב בתורתך (בפרשת השבוע<sup data-n=\"1683\">7</sup>) אשר לא ישא פנים . . והלא אתה נושא פנים לישראל דכתיב<sup data-n=\"1684\">8</sup> ישא ה' פניו אליך, אמר להם, וכי לא אשא פנים לישראל שכתבתי להם בתורה ואכלת ושבעת וברכת את ה' אלקיך, והם מדקדקים על עצמם עד כזית ועד כביצה\".\nוהענין בזה – כמבואר בדרושי חסידות<sup data-n=\"1685\">9</sup> שנשיאת פנים ענינה המשכה מבחי' <b>שלמעלה מסדר השתלשלות</b>. והמשכה זו נעשית ע\"י עבודתם של ישראל באופן ש\"מדקדקים על עצמם כו'\", שזהו\"ע <b>שלמעלה מטעם ודעת</b>, שהרי ע\"פ טעם ודעת צריך לברך רק על אכילה שיש בה כדי שביעה (\"ואכלת <b>ושבעת</b> וברכת\"), אלא שאעפ\"כ \"מדקדקים על עצמם עד כזית ועד כביצה\" – מצד קבלת עול שלמעלה מטעם ודעת.\nונמצא, שתוכן הענין דברכת המזון מתאים לתוכן הענין ד\"והי' עקב תשמעון גו'\" שבתחלת הפרשה – שבשניהם מדובר אודות המשכה מבחי' שלמעלה מסדר השתלשלות שנעשית ע\"י עבודה שלמעלה מטעם ודעת.\n<b>ב</b>. ויש להוסיף בביאור הענין ד\"מדקדקים על עצמם עד כזית ועד כביצה\" – בעומק יותר:\nההוספה שבנ\"י \"מדקדקים על עצמם כו'\" – אינה יכולה להיות שלא כפי התורה ח\"ו. וכיון שהתורה אמרה \"ואכלת <b>ושבעת</b> וברכת\", שהחיוב דברכת המזון הוא באכילה שיש בה כדי שביעה דוקא, עכצ\"ל, שהפירוש ד\"מדקדקים על עצמם עד כזית ועד כביצה\", הוא, שע\"י העבודה ד\"מדקדקים על עצמם\" נעשה אצלם ענין <b>השביעה</b> גם מאכילה בשיעור של \"כזית\" ו\"כביצה\", אף שטבע הגוף אינו כן.\nונמצא, שתוכן העבודה ד\"מדקדקים על עצמם\" הוא – שליטת הנשמה על הגוף, שהנשמה שהיא למעלה מן הגוף, פועלת גם על הגוף להיות שבע גם משיעור כזה שמצד טבע הגוף אין בו כדי שביעה.\nוזהו שע\"י העבודה ד\"מדקדקים על עצמם כו'\" פועלים העניןד\"ישא ה' פניו אליך\", המשכה שלמעלה מסדר השתלשלות – כי, זה שהנשמה שלמעלה מהגוף פועלת בהגוף (שנעשה שבע מכזית וכביצה), הוא ע\"ד ובדוגמת המשכת הבחי' שלמעלה מהשתלשלות בסדר השתלשלות.\nומזה באים לנקודה נוספת בענין זה – שהגילוי שלמעלה מהשתלשלות (נשיאת פנים) הוא באופן שנמשך ופועל <b>למטה בגשמיות</b> דוקא, כשם שהעבודה \"מדקדקים על עצמם עד כזית ועד כביצה\" היא באופן שנעשה שביעה <b>בהגוף הגשמי ממש</b>.\n<b>ג</b>. ועוד ענין בהדגשת ההמשכה שלמעלה מסדר השתלשלות <b>למטה</b> דוקא שבברכת המזון – בקשר ובשייכות לירידה למטה <b>דזמן הגלות</b>:\nאיתא בגמרא<sup data-n=\"1686\">10</sup> \"הטוב והמטיב (ברכה רביעית דברכת המזון) ביבנה תקנוה כנגד הרוגי ביתר . . אותו היום שניתנו הרוגי ביתר לקבורה תקנו ביבנה הטוב והמטיב כו'\", והיינו, שמצד ענין הגלות נעשית הוספה בברכת המזון.\nוהענין בזה:\nכללות ענין הגלות הוא בסיבת החטא – \"מפני חטאינו גלינו מארצנו\"<sup data-n=\"1687\">11</sup>. ובמצב כזה יש צורך בענין של סליחה ומחילה וכפרה – ע\"י המשכת בחי' שלמעלה מהשתלשלות, כידוע<sup data-n=\"1688\">12</sup> שהפגם שע\"י החטא אינו אלא בסדר השתלשלות, והסליחה היא מצד המשכה שלמעלה מהשתלשלות שעל ידה נעשה מילוי כל הפגמים. ונמצא, שלולי ענין החטא – אין הכרח וצורך כ\"כ בהמשכה שלמעלה מסדר השתלשלות.\nומזה מובן גם בנוגע להמשכה שלמעלה מסדר השתלשלות שבנשיאת פנים (\"ישא ה' פניו אליך\") – שעיקר הצורך וההכרח בזה הוא במצב ירוד דוקא, כבזמן הגלות, מצד ענין החטא כו', שאז אומרים \"לך ה' הצדקה ולנו בושת הפנים\"<sup data-n=\"1689\">13</sup>, היינו, שאין יכולים לתבוע \"בזרוע\" (בזכות שבידם)<sup data-n=\"1690\">14</sup>, ולכן מבקשים מהקב\"ה בתורת צדקה, שזהו\"ע דנשיאת פנים, שבכללות ה\"ז המשכה שלמעלה מהשתלשלות, שנעשית ע\"י העבודה ד\"מדקדקים על עצמם כו'\"; משא\"כ צדיקים שאין להם שייכות לענין של גלות וחטא כו', ועד לאלו שאין להם שייכות אפילו לחטא עץהדעת, כמארז\"ל<sup data-n=\"1691\">15</sup> \"ארבעה מתו בעטיו של נחש\", ועד לתכלית העילוי דנכנס חי לגן עדן<sup data-n=\"1692\">16</sup> – במצב כזה אין צורך בנשיאת פנים, ובמילא אין גם צורך בעבודה ד\"מדקדקים על עצמם כו'\".\nונמצא, שמצד ירידת הגלות ניתוסף בענין ההמשכה שלמעלה מסדר השתלשלות – שזהו\"ע הוספת ברכה רביעית בברכת המזון בזמן הגלות דוקא.\n<b>ד</b>. ומזה מובן גם בנוגע לענין ההמשכה למטה בגשמיות דוקא:\nכשם שנתבאר לעיל שההמשכה שלמעלה מהשתלשלות שבברכת המזון היא באופן שנמשכת למטה בגשמיות דוקא – כן הוא גם בנוגע להוספה בהמשכה שלמעלה מהשתלשלות שמצד ירידת הגלות, שגם ענין זה הוא באופן שנמשך למטה בגשמיות דוקא.\nוזהו גם הטעם לכך שהגאולה שבאה אחר הגלות תהי' למטה בגשמיות דוקא – כידוע הפלוגתא בין הרמב\"ם להרמב\"ן בנוגע לשכר דעולם הבא, שלדעת הרמב\"ם<sup data-n=\"1693\">17</sup> הוא השכר לנשמות בלא גופים, ולדעת הרמב\"ן<sup data-n=\"1694\">18</sup> הוא השכר לנשמות בגופים, והכרעת תורת החסידות<sup data-n=\"1695\">19</sup> היא כדעת הרמב\"ן ששלימות השכר דעולם הבא הוא לנשמות בגופים דוקא –כיון שההמשכה שלמעלה מסדר השתלשלות שמוכרחת מצד ירידת הגלות, צריכה להיות נמשכת למטה בגשמיות דוקא.\n***\n<b>ה</b>. האמור לעיל שברכת המזון ענינה המשכה מבחי' שלמעלה מסדר השתלשלות שנמשכת למטה דוקא – מובן גם ממ\"ש בזהר דפרשת עקב<sup data-n=\"1696\">20</sup> בפירוש נוסח הברכות, וכפי שנתבאר בביאורי הזהר לאדמו\"ר האמצעי<sup data-n=\"1697\">21</sup>, ותוכן הענין, שבנוסח הברכה מודגשת ההמשכה מלמעלה ביותר הקשורה עם המטה ביותר.\nביאור הדברים:\nלאחרי שמבאר בזהר כללות הענין דברכת המזון – מוסיף לבאר הפירוש דנוסח הברכה: \"ברוך דא רזא דמקורא עלאה מכלא לארקאולאמשכא ולאנהרא כל בוצינין וכו'\", \"אתה . . לאתגלייא לבר . . דא רזא דימינא וכו'\", \"הוי' דא רזא דאמצעיתא וכו'\", \"אלקינו דא סטרא דשמאלא דכליל בימינא וכו'\".\nומבאר אדמו\"ר האמצעי בביאורי הזהר בפירוש \"ברוך דא רזא דמקורא עלאה\", ש\"מקורא עילאה הוא בחי' יסוד אבא להיותו בחי' ראשית הגילוי מבחי' ההעלם דכתר\", והרי ענין הברכה הוא המשכת הכתר, ועד לפנימיות הכתר, כמבואר שם<sup data-n=\"1698\">22</sup> ש\"ענין הברכה במצות ברכת המזון להיותו בחי' אור חדש דוקא, צריך לעורר ולבוא אור המשכה חדשה ע\"י בחי' הכתר דוקא כדי שיבוא אור חדש מעצמות המאציל\", שזהו מבחי' פנימיות הכתר, דלא כיחוד או\"א ש\"לא נמשך רק מחיצוניות הכתר\".\nונמצא, ש\"ברוך\" מורה על המשכה שלמעלה מהשתלשלות, שזוהי בחי' פנימיות הכתר, כי, סדר השתלשלות מתחיל מחיצוניות הכתר, כמו באדם התחתון שכל פרטי הכחות מתחילים מענין הרצון, ולולי הרצון לא יכולה להיות המשכת הכחות, ודוגמתו למעלה, שהתחלת כל ההמשכות היא מחיצוניות הכתר, ואילו פנימיות הכתר הוא בחינה שלמעלה מהשתלשלות.\nוענינו בעבודת האדם – ש\"ברוך\" מורה על ענין ההודאה שלמעלה מטעם ודעת, שעי\"ז נמשך מבחי' שלמעלה מהשתלשלות (כנ\"ל ס\"א). ולאח\"ז באים כל שאר פרטי הענינים שבעבודה: \"אתה\", \"רזא דימינא\", בחי' החסד – ענין האהבה, ו\"אלקינו\", \"סטרא דשמאלא דכליל בימינא\" – תגבורת החיות שע\"י הגבורה (שלכן<sup data-n=\"1699\">23</sup> מצינו במתן תורה ענין הגבורה דוקא, כמארז\"ל<sup data-n=\"1700\">24</sup> \"אנכי ולא יהי' לך מפי <b>הגבורה</b> שמענום\", ועד\"ז בברכת יצחק נאמר<sup data-n=\"1701\">25</sup> \"ויתן לך <b>האלקים</b> גו'\", שהוא שם מדת הגבורה דוקא, שענינה תגבורת החיות<sup data-n=\"1702\">26</sup>).\n<b>ו</b>. וגודל העילוי שבענין הברכה – \"ברוך דא רזא דמקורא עלאה\", \"בחי' יסוד אבא להיותו בחי' ראשית הגילוי מבחי' ההעלם דכתר\", עד לפנימיות הכתר – קשור עם הירידה למטה דוקא:\nבביאורי הזהר<sup data-n=\"1703\">27</sup> ממשיך לבאר הטעם ש\"ברכת המזון שהוא בחי'המשכה חדשה מאור הכתר . . היא דוקא באכילה ושביעה . . להיות ידוע בשרש המאכלים שנפלו בשבירה מבחי' התהו שקדם לתיקון<sup data-n=\"1704\">28</sup> . . שרש בחי' התהו הן מבחי' העגולים שקדמו לבחי' היושר . . כשאוכל אדם . . את המאכל ששרשו מבחי' התהו, הרי מעלהו לשרשו הקדום בבחי' הכתרים די\"ס דנק' עגולים . . יעלה ויגיע לבחי' אור הכתר הכללי כו'\".\nובהקדם תורת הבעש\"ט<sup data-n=\"1705\">29</sup> על מ\"ש בפרשת השבוע<sup data-n=\"1706\">30</sup> \"ויענך וירעיבך ויאכילך את המן גו' למען הודיעך כי לא על הלחם לבדו יחי' האדם כי על כל מוצא פי ה' יחי' האדם\", וז\"ל:\n\"קשה דההי\"ן של ב' פעמים <b>ה</b>אדם מיותרים, דהל\"ל כי לא על הלחם לבדו יחי' אדם כי על כל מוצא פי ה' יחי' אדם. י\"ל דבס' לקוטי תורה מהאריז\"ל<sup data-n=\"1707\">31</sup> דהחוקרים הקשו מאין הוא חיות הנשמה, דאין הדעת נותן שיהי' חיות הנשמה מלחם ומאכל גשמי . . ונבוכו הרבה בזאת החקירה. ותירץ האריז\"ל שלא ידעו והיו סכלים בשרש הבריאה, דארז\"ל<sup data-n=\"1708\">32</sup> בעשרה מאמרות נברא העולם . . כשאמר תוצא הארץ נפש חי' או תוצא הארץ דשא ועץ פרי, אותו המאמר הי' מהוה הכל, והמאמר הזה הוא חיות פנימי להם. וכשנוטל אדם פרי או דבר מאכל ומברך עליו בכונה ואומר ברוך אתה ה', כשמזכיר את השם מתעורר אותו חיות שעל ידו נברא הפרי ההוא, כי נברא הכל ע\"י השם, ומוצא מין את מינו וניעור, וזה החיות הוא מזון הנשמה . . וז\"ש . . כי לא על הלחם לבדו, פי' בזמן שהוא לבדו בלא התעוררות הרוחניות בו, יחי' האדם, פי' הנשמה שנקרא אדם בה\"א הידיעה, כי הגוף נקרא בשר אדם והנשמה נקרא האדם, כי על כל מוצא פי ה', פי' כשאתה מוציא השם בכוונה ע\"י הברכה שברכת עליו שעי\"ז מתעורר הרוחניות, מזה יחי' האדם שהיא הנשמה ניזונות מרוחניות המאכלים, כי הקב\"ה עשה כן בכוונה מכוונת ע\"י שהי' בונה עולמות ומחריבן<sup data-n=\"1709\">33</sup> נפלו ניצוצין קדישין לד' חלקים שהם דומם צומח חי מדבר, שראוי לאדם להעלותם כו'\".\nוממשיך לבאר ש\"ז\"ש ריב\"ש ע\"פ<sup data-n=\"1710\">34</sup> רעבים גם צמאים נפשם בהם תתעטף . . כל אכילה שאדם אוכל ושותה הם ממש חלק ניצוצות שלו שהוא צריך לתקן, וז\"ש רעבים גם צמאים שאדם רעב וצמא להם . . נפשם בהם תתעטף בסוד גלות בלבוש כו'\".[וכפי שכותב כ\"ק מו\"ח אדמו\"ר בא' ממכתביו<sup data-n=\"1711\">35</sup> בפירוש הכתוב \"כי לא על הלחם לבדו וגו'\", שהסיבה לכך שהגוף רעב ללחם הגשמי, היא מפני שהנשמה רעבה לניצוץ האלקי שבמאכל, ורעבון הנשמה פועל על הגוף שיהי' רעב ללחם הגשמי, כך, שהעיקר הוא הענין האלקי שבדבר ולא הגשמי].\nוזוהי כללות עבודת האדם בענין האכילה [כולל גם התעסקותו בעניני העולם למלאות צרכיו, שהרי אכילה כוללת כל צרכי האדם (כנ\"ל ס\"א)] – להעלות את עניני העולם מגשמיות לרוחניות, עי\"ז שמגלה את ה\"מוצא פי ה'\" שבהם, וענין זה הוא בב' אופנים: כאשר אוכל \"לשם שמים\", או כאשר האכילה עצמה היא מצוה, כמו אכילת שבת, שעל ידה מקיים מצות עונג שבת.\nועוד ענין בזה –כאמור – שה\"מוצא פי ה'\" שבמאכל שרשו למעלה ביותר (\"בחי' הכתרים די\"ס שנק' עגולים\"), ולכן, עי\"ז שהאדם מגלה את ה\"מוצא פי ה'\" ומעלהו לשרשו, מתעלה גם הוא לדרגא נעלית ביותר (\"בחי' אור הכתר הכללי\").\nונמצא, שמעלת הברכה בבחי' שלמעלה מהשתלשלות, קשורה עם הירידה וההמשכה למטה דוקא. והיינו, שהכוונה היא שתהי' ההמשכה למטה בגשמיות דוקא, וההמשכה למטה באה מבחי' היותר עליונה דוקא, כידוע<sup data-n=\"1712\">36</sup> הכלל שכל הגבוה יותר יורד למטה יותר.\nוזה גופא הוא הטעם לכך שהכוונה היא שתהי' ההמשכה למטה בגשמיות דוקא – דלכאורה לשם מה צריכים לעשות \"קונצן\" כדי לפעול ההמשכה למטה דוקא – משום שדוקא למטה נמשך האור היותר עליון<sup data-n=\"1713\">37</sup>.\n***\n<b>ז</b>. מאמר (כעין שיחה) ד\"ה לא היו ימים טובים לישראל כחמשה עשר באב כו'.\n***\n<b>ח</b>. בהמשך להמדובר לעיל (ס\"ה) בביאור מאמר הזהר בפירוש נוסח הברכה – יש להוסיף ולבאר דיוקי הלשונות בזהר הנ\"ל.ובהקדם מ\"ש אדמו\"ר האמצעי בהקדמתו לביאורי הזהר<sup data-n=\"1714\">38</sup>, שרבינו הזקן הי' לומד ספר הזהר \"בעיון והעמקה גדולה וביגיעה רבה בדקדוק הלשון בכל מלה שיהי' מכוון ע\"פ אמיתי' חכמת הקבלה\".\nוזהו גם דרך הלימוד של אאמו\"ר ז\"ל בעל ההילולא בהערותיו על הזהר, כדלקמן.\n<b>ט</b>. במ\"ש בזהר \"ברוך דא רזא דמקורא עלאה מכלא לארקא ולאמשכא ולאנהרא כל בוצינין\" – מדייק אאמו\"ר ז\"ל<sup data-n=\"1715\">39</sup>:\n\"הג' לשונות, לארקא לאמשכא לאנהרא, י\"ל, כי ברוך שהוא רזא דמקורא עלאה, דהיינו יסוד אבא, הנה חכ' הוא יו\"ד שבשם, שיש בזה ג' בחי', והוא הג' אותיות יו\"ד. י' נקודה, ו' קו, ד' שטח. ורומזים ג\"כ על חב\"ד, כי חכ' כוללת בינה ודעת ג\"כ, י' חכ', ו' דעת, ד' בינה. זהו לארקא מי'. ולאמשכא מו', כי ו' הוא המשכה. ולאנהרא מד', כי הארת אור הוא בהתפשטות, והיינו שטח\".\nויש לקשר זה עם המבואר לעיל שההמשכה דענין הברכה צריכה לבוא למטה דוקא, שלכן, גם כמו שההמשכה היא עדיין בחכמה, מודגש בה לא רק הנקודה (י'), אלא גם הקו (ו') והשטח (ד'), שעי\"ז דוקא תהי' ההמשכה למטה.\n<b>י</b>. וממשיך אאמו\"ר ז\"ל<sup data-n=\"1715\">39</sup> לדייק גם בהמשך דברי הזהר בפירוש התיבות \"אתה הוי' אלקינו\" – \"אתה . . דא רזא דימינא . . הוי' דא רזא דאמצעיתא רזא דמהימנותא . . אלקינו דא סטרא דשמאלא כו'\":\n\"באתה ובהוי' נקט תיבת רזא, בכל א', רזא דימינא ורזא דאמצעיתא. וכאן באלקינו לא נקט רזא, רק סטרא. ובהוי' נקט רזא ב\"פ, רזא דאמצעיתא רזא דמהימנותא\".\nומבאר, \"י\"ל ע\"ד כמו שביום ראשון שנברא בו האור, חסד, כתיב כי טוב<sup data-n=\"1716\">40</sup>. וביום שלישי שלנגד ת\"ת, כתיב ב\"פ כי טוב<sup data-n=\"1717\">41</sup>. וביום שני שלנגד גבורה, לא כתיב כי טוב\".\nומוסיף לבאר, ש\"רזא שהוא סוד והעלם, הוא כמו בחי' טוב, כי טוב הו\"ע גניזה והעלם, כמא'<sup data-n=\"1718\">42</sup> ע\"פ<sup data-n=\"1716\">40</sup> וירא אלקים את האור כי טוב, כי טוב לגנוז . . א\"כ טוב הוא כמו רזא. לכן, באתה שהוא חסד, כהן, ימינא,כמו יום ראשון שנברא בו האור, נקטו רזא דימינא כמו שנאמר ביום ראשון טוב. ובהוי' ת\"ת, כמו יום שלישי שלנגד ספירת הת\"ת, נקטו ב\"פ רזא, כמו שנאמר ביום השלישי ב\"פ כי טוב. ובאלקינו שהוא לנגד מדת הגבורה . . כמו יום שני שלנגד גבורה, לא נקט בי' רזא, כמו שביום שני לא נאמר טוב\". עכ\"ל.\nוצריך להבין מ\"ש אאמו\"ר ש\"רזא\" \"הוא כמו בחי' טוב\", \"האור כי טוב\" – דלכאורה הם ענינים הפכיים זמ\"ז, שהרי \"אור\" ענינו <b>גילוי</b>, שזהו היפך ה\"רז\" שענינו <b>סוד והעלם</b>?!\n<b>יא</b>. ויש לומר הביאור בזה:\nב\"אור\" – ישנם כמה סוגים: יש אור רוחני, כמו אור השכל, ויש אור גשמי. וכשמשווים אותם זל\"ז, הרי, אור רוחני הוא אור אמיתי, ואילו אור גשמי אינו אלא אור מדומה.\nוהנה, אור רוחני, כמו אור השכל – נראה רק בעיני השכל שתופס בדבר רוחני דוקא. והפכו באור גשמי – שנראה רק בעיני בשר שתופס בדבר גשמי דוקא.\nונמצא, שענין שהוא \"אור\" (גילוי) לגבי עיני השכל – הוא \"רז\" (העלם) לגבי עיני בשר. וענין שהוא \"רז\" (העלם) לגבי עיני השכל – הוא \"אור\" (גילוי) לגבי עיני בשר.\nאמנם, הכוונה היא לחבר ולאחד ב' בחינות אור הנ\"ל – שגם אור רוחני יומשך למטה להיות בגילוי לעיני בשר.\n<b>יב</b>. וזהו גם תוכן ביאור דברי אאמו\"ר ש\"רזא דימינא\" הוא כמו טוב שנאמר ביום הראשון, \"רזא דאמצעיתא ורזא דמהימנותא\" הם כמו ב\"פ כי טוב שנאמר ביום השלישי, ו\"סטרא דשמאלא\" (שבזה לא נקט רזא) הוא כמו שלא נאמר טוב ביום שני – בעבודת האדם:\nיום ראשון שהוא בחי' חסד, ענינו תכלית הגילוי דאור רוחני, ולכן נאמר בו כי טוב, שזהו הטוב דבחי' החסדים, אלא שלמטה אינו מאיר בגילוי, כי אם באופן של רז והעלם (\"רזא דימינא\").\nיום שני שהוא בחי' גבורה וצמצום, ענינו שהאור הרוחני אינו מאיר, ולכן לא נאמר בו טוב דבחי' החסדים, אלא, שמצד הגבורה והצמצום באור הרוחני, מאיר למטה אור גשמי (ולכן לא נקט רזא דשמאלא).\nוהחידוש דיום שלישי שהוא בחי' תפארת, קו האמצעי, שמחברוכולל את קו השמאל (גבורה וצמצום) בקו הימין (חסד) – שהאור הרוחני (חסד) יומשך ויאיר בגילוי גם באור הגשמי (שבא בסיבת הגבורה והצמצום דהאור הרוחני).\nוזהו מה שיום השלישי הוכפל בו כי טוב (וכנגדם נקט ב\"פ רזא), אחת למלאכת היום ואחת לגמר מלאכת השני&lt;41&gt; – שמלבד הטוב שמצד בחי' החסד שכלול בתפארת (אור רוחני שאינו נמשך ומתגלה למטה, \"רזא\" הא'), מתגלה בו גם הטוב שבבחי' הגבורה, <b>הכוונה הפנימית</b> שבענין הגבורה והצמצום (שלא נתגלה ביום שני, וישנו רק בהעלם, \"רזא\" הב') – שכוונת הצמצום והעלם האור הרוחני היא כדי שהאור הרוחני יומשך ויאיר בגילוי באור הגשמי (ע\"ד ההמשכה היותר נעלית למטה דוקא ויחוד הרוחניות עם הגשמיות שבברכת המזון, כנ\"ל בארוכה).\n<b>יג</b>. ויש לקשר ענין זה עם הגאולה – התיקון על הענין ד\"חטאו בכפלים\" עי\"ז ש\"מתנחמים בכפלים\"<sup data-n=\"1719\">43</sup>:\n\"חטאו בכפלים\" – יש לפרש שזהו מה שעושים שתי רשויות כו', גשמיות לחוד ורוחניות לחוד.\nוהתיקון לזה הוא ע\"י החיבור דרוחניות וגשמיות – שזהו תוכן הענין ד\"נחמה בכפלים\", על בית ראשון ועל בית שני<sup data-n=\"1720\">44</sup> – בביהמ\"ק השלישי, כאמור לעיל (בהמאמר<sup data-n=\"1721\">45</sup>) שתהי' בו הן המעלה דבית ראשון, גילוי אור נעלה, והן המעלה דבית שני, מעלת התשובה (לאחרי הגבורה והצמצום), שחיבורם יחד הוא ע\"ד החיבור דרוחניות וגשמיות.\n***\n<b>יד</b>. בתפלת מנחה דיום הש\"ק זה מתחילים לקרוא פרשת ראה – \"ראה אנכי נותן לפניכם היום ברכה\".\nולכאורה אינו מובן מ\"ש \"ראה\" – דכיון שמדובר כאן אודות ענין של <b>הבנה והשגה</b> בהשייכות דענין הברכות לקיום התומ\"צ כו', הרי מתאים יותר לשון של <b>שמיעה</b> שפירושה הבנה והשגה, שמע והבן, ולמה נאמר לשון של ראי', \"ראה\"?\nויש לומר הביאור בזה<sup data-n=\"1722\">46</sup>:מהחילוקים שבין שמיעה לראי'<sup data-n=\"1723\">47</sup> – ששמיעה תופסת ענין רוחני, משא\"כ ראי' תופסת ענין גשמי בלבד, ובזה גדלה מעלת השמיעה על הראי'.\nולאידך, יש מעלה בראי' על השמיעה – שענין ההתאמתות הוא ע\"י ראי' דוקא, וכמו שרואים במוחש שכאשר אדם שומע איזה דבר ומבינו בשכלו, הרי, אף שבשעה זו נתאמת בשכלו הענין ששמע, מ\"מ, כאשר יעוררו על זה קושיות וסתירות כו', ויוכיחו לו שאין האמת כפי ששמע, אזי יתעורר אצלו ספק בדבר. משא\"כ בראי' – גם אם יקשו כו\"כ קושיות כו', לא יהי' אצלו שום ספק באמיתת הדבר, כיון שהוא בעצמו ראה את הדבר.\nאמנם, מעלת ההתאמתות שבענין הראי' – בזמן הזה אינה אלא בענינים גשמיים הנראים לעיני בשר.\nוזהו החידוש דלעתיד לבוא – שאז תהי' הראי', ובמילא, גם מעלת ההתאמתות שבה, גם בענינים רוחניים, כמ\"ש<sup data-n=\"1724\">48</sup> \"ונגלה כבוד ה' וראו כל בשר יחדיו כי פי ה' דיבר\", שהענינים הרוחניים (\"פי ה' דיבר\") יהיו נראים בעיני בשר (\"וראו כל בשר\").\nוזהו גם הענין ד\"ראה גו'\" – שגם בענינים הרוחניים שתופסים בהבנה והשגה תהי' ההתאמתות דראי', שזהו גם תוכן החיבור דרוחניות וגשמיות, כנ\"ל בארוכה.\n**********",[["1676","*","ראשי-פרקים (<b>המו\"ל</b>)."],["1677","1","ח, יו\"ד."],["1678","2","ראה רמב\"ן פרשתנו יו\"ד, יח."],["1679","3","ראה אוה\"ת פרשתנו ע' תצט. ד\"ה והי' עקב תרע\"ג (המשך תער\"ב ח\"א ע' שנה ואילך). תשי\"א (תו\"מ ח\"ג ע' 276 ואילך)."],["1680","4","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380896\" data-slug=\"likkutei-torah\" data-id=\"4001380896\">לקו\"ת נצבים מד, ב</a> – הובא בלקו\"ת פרשתנו טו, ג."],["1681","5","נדרים לב, א. סנהדרין צ, סע\"א. וראה סוטה ח, ב ואילך."],["1682","6","ברכות כ, ב."],["1683","7","יו\"ד, יז."],["1684","8","נשא ו, כו."],["1685","9","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380415\" data-slug=\"likkutei-torah\" data-id=\"4001380415\">לקו\"ת נשא כו, ד</a> ואילך. ובכ\"מ."],["1686","10","ברכות מח, ב."],["1687","11","נוסח תפלת מוסף דיו\"ט."],["1688","12","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380190\" data-slug=\"likkutei-torah\" data-id=\"4001380190\">לקו\"ת אחרי כו, ג</a> ואילך. ובכ\"מ."],["1689","13","דניאל ט, ז."],["1690","14","ראה ברכות יז, ב."],["1691","15","שבת נה, ב. וש\"נ."],["1692","16","ראה כתובות עז, ב."],["1693","17","הל' תשובה פ\"ח ה\"א-ב. פיה\"מ סנהדרין פ' חלק ד\"ה ועתה אחל."],["1694","18","בשער הגמול בסופו (בהוצאת שאוועל – ע' שט)."],["1695","19","ראה תו\"מ סה\"מ שבט ע' שסה הערה 126. וש\"נ."],["1696","20","ח\"ג (ברע\"מ) רעא, א ואילך."],["1697","21","פרשתנו קכ, ב ואילך."],["1698","22","קיח, א ואילך."],["1699","23","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830174\" data-slug=\"or-hatorah-hb\" data-id=\"8158830174\">אוה\"ת במדבר</a> (דרושי שבועות) ס\"ע קעד ואילך."],["1700","24","מכות כד, רע\"א. וש\"נ. הובא בפרש\"י עה\"ת שלח טו, כב."],["1701","25","תולדות כז, כח."],["1702","26","ראה תו\"מ סה\"מ חשון ע' שלט. וש\"נ."],["1703","27","קיט, סע\"ד ואילך."],["1704","28","ראה גם לקו\"ת פרשתנו יד, ב."],["1705","29","כש\"ט סי' קצד (כה, א ואילך)."],["1706","30","ח, ג."],["1707","31","עה\"פ."],["1708","32","אבות רפ\"ה. – פרק דשבת זה."],["1709","33","ב\"ר פ\"ג, ז."],["1710","34","תהלים קז, ה."],["1711","35","ראה גם תו\"מ חי\"ט ע' 99. וש\"נ."],["1712","36","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380794\" data-slug=\"likkutei-torah\" data-id=\"4001380794\">לקו\"ת פ' ראה יט, ג</a>. ובכ\"מ."],["1713","37","חסר קצת (<b>המו\"ל</b>)."],["1714","38","בתחלתה."],["1715","39","נדפס (לאח\"ז) בלקוטי לוי\"צ הערות לזהר פרשתנו ע' תנח."],["1716","40","בראשית א, ד."],["1717","41","ב\"ר פ\"ד, ו. פרש\"י בראשית א, ז."],["1718","42","ראה חגיגה יב, א."],["1719","43","איכ\"ר ספ\"א. יל\"ש ישעי' רמז תמה."],["1720","44","יל\"ש שם."],["1721","45","בסופו (לעיל ע' 266)."],["1722","46","ראה גם תו\"מ ח\"כ ע' 227. וש\"נ."],["1723","47","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061132\" data-slug=\"likkutei-sichot\" data-id=\"1300061132\">לקו\"ש ח\"ו ע' 121</a>. וש\"נ."],["1724","48","ישעי' מ, ה."]]],[1400350031,"(הנחה בלתי מוגה)\n<b>אחרי</b> הוי' אלקיכם תלכו ואותו תיראו ואת מצותיו תשמרו ובקולו תשמעו ואותו תעבודו ובו תדבקון<sup data-n=\"1725\">1</sup>. ומבואר בלקו\"ת<sup data-n=\"1726\">2</sup> ובסידור<sup data-n=\"1727\">3</sup> שבפסוק זה נימנו כל פרטי אופני העבודה, שהתחלתה היא בבחי' אחרי הוי' אלקיכם תלכו, ושלימותה היא בבחי' ובו תדבקון. ועפ\"ז יש לבאר גם הטעם שפסוק זה קורין תמיד בר\"ח אלול או בשבת מברכים חודש אלול. דהנה, חודש אלול הוא חודש החשבון על כל השנה<sup data-n=\"1728\">4</sup>, וזהו ג\"כ ענין התקיעות שבחודש אלול, שענינם הוא כמ\"ש<sup data-n=\"1729\">5</sup> אם יתקע שופר בעיר ועם לא יחרדו, והיינו, לפי שבחודש אלול מאירים י\"ג מדות הרחמים<sup data-n=\"1730\">6</sup> (כדאיתא במשנת חסידים<sup data-n=\"1731\">7</sup> ובפרי עץ חיים<sup data-n=\"1732\">8</sup>), ועל ימים אלו נאמר<sup data-n=\"1733\">9</sup> ואנכי עמדתי בהר כימים הראשונים, מה הראשונים ברצון אף האחרונים ברצון, שהו\"ע גילוי בחינת הרצון שלמעלה, שעי\"ז מתעורר ג\"כ הרצון הפנימי שבנפש האדם, ולכן אפשר אז לתקן את כל הענינים כו'. וזהו שבחודש אלול קורין הפסוק אחרי הוי' אלקיכם תלכו וגו', שבו נימנו כל עבודות הכלליות שצריכים לעשותם בכל יום ויום מימי השנה, כיון שאז צריך לעשות חשבון על כל השנה אם עשה עבודתו בכל ענינים אלה.\nב) <b>והנה</b> נוסף על הפסוק אחרי הוי' אלקיכם תלכו גו' שבתורה, שמבאר סדר המדריגות בעבודה עצמה, מהתחלת העבודה בבחי' אחרי הוי' גו' עד לבחי' ובו תדבקון, ישנו גם הפסוק בנביא שבו מבאר את ההכנה להתחלת העבודה בבחי' אחרי הוי' אלקיכם תלכו, שזהו מ\"ש<sup data-n=\"1734\">10</sup> אחרי הוי' ילכו (שההכנה לזה היא) כארי' ישאג כי הוא ישאג ויחרדו בנים מים יחרדו כצפור ממצרים וכיונה מארץ אשור. והענין בזה, דהנה העבודה דאחרי הוי' גו' הו\"ע היראה, שהרי ההפרש בין אהבה ליראה הוא שאהבההיא עבודה פנימית ויראה היא בחיצוניות, שזהו\"ע <b>אחרי</b> הוי'. ולכן גם ההכנה לזה היא כארי' ישאג, שארי' הו\"ע היראה, כמ\"ש<sup data-n=\"1735\">11</sup> ארי' שאג מי לא יירא. וזהו ג\"כ מ\"ש ויחרדו בנים, דחרדה הו\"ע היראה, והחרדה דאלול (שע\"י התקיעות) היא בכללות ישראל, שזהו מ\"ש ויחרדו בנים, שקאי על כל ישראל שנקראים בנים, כמ\"ש<sup data-n=\"1736\">12</sup> בנים אתם להוי' אלקיכם. ועוד זאת, שפעולת החרדה היא לא רק על אלו שהם בבחינת בנים, אלא גם על אלו שהם בחינת עם, שזהו מ\"ש&lt;5&gt; אם יתקע שופר בעיר ועם לא יחרדו, עם דייקא. וזהו ג\"כ שלאחרי ויחרדו בנים מים, מוסיף ומסיים יחרדו כצפור ממצרים וכיונה מארץ אשור, שגם אלו שהם בבחינת גלות בב' האופנים דמצרים ואשור<sup data-n=\"1737\">13</sup>, הנה גם בהם נעשה ענין החרדה בחודש אלול. וחרדה זו היא הכנה להתחלת העבודה דאחרי הוי' ילכו גו'.\nג) <b>ולהבין</b> זה בפרטיות יותר, וגם להבין מ\"ש כארי' ישאג כי הוא ישאג (ב\"פ שאגה), וגם להבין מה שמייחס ענין השאגה לארי' דוקא. והענין בזה<sup data-n=\"1738\">14</sup>, דמ\"ש כארי' ישאג קאי על עבודת המלאכים, ובפרט עבודת השרפים, שנקראים שרפים לפי שהם נשרפים בהשגתם<sup data-n=\"1739\">15</sup>, והיינו, שהשרפים הם בעלי השגה גדולה, שהרי השרפים הם בעולם הבריאה, ואימא עילאה מקננא בכורסיא<sup data-n=\"1740\">16</sup>, ולכן מאיר שם השגה באלקות. וזהו גם מ\"ש<sup data-n=\"1741\">17</sup> שרפים עומדים ממעל לו, דלכאורה אינו מובן, כפי שהקשה הבעש\"ט<sup data-n=\"1742\">18</sup>, איך אפשר להיות שיעמדו ממעל לו, והרי מ\"ש ממעל לו קאי על מ\"ש לעיל מיני'<sup data-n=\"1743\">19</sup> ואראה את אד' יושב על כסא רם ונשא, ואיך אפשר שהשרפים יעמדו ממעל לבחי' זו, ובפרט שבחי' זו היא מקור חיותם, ואיך אפשר שיעמדו ממעל לו, למעלה ממקור חיותם. אך הענין הוא, ע\"ד מ\"ש בתניא<sup data-n=\"1744\">20</sup> בענין מקיף ומוקף, שכאשר לומד ומשיג דבר הוי' זו הלכה<sup data-n=\"1745\">21</sup>, הנה אף שההלכה היא למעלה משכל האדם, מ\"מ, עי\"ז שמשיג אותה הריהוא מקיפה בשכלו, וכיון שהוא מקיף אותה הרי הוא למעלה ממנה. ובזה יובן מ\"ש שרפים עומדים ממעל לו, דכיון שהם משיגים את מקור חיותם הרי הם מקיפים את החיות והם למעלה ממנו. ומצד השגה זו הרי הם בהתפעלות והתלהבות, וזהו ענין כארי' ישאג.\n<b>אמנם</b> עיקר ענין השאגה הוא מצד ענין שהוא בריחוק הערך ממנו, וע\"ד מ\"ש<sup data-n=\"1746\">22</sup> שאגתי מנהמת לבי, שקאי על ענין התשובה, שזהו ענין שבאין ערוך, וואָס ער שטעלט זיך איבער מן הקצה אל הקצה, שבתחילה הי' בארץ צי' ועיף בלי מים<sup data-n=\"1747\">23</sup>, וע\"י התשובה נעשה במעמד ומצב שזדונות נעשים לו כזכיות<sup data-n=\"1748\">24</sup>, והיינו, שמצד דבר שבאין ערוך נעשה ענין של שאגה, אבל כאשר משיג דבר שבערכו, הנה ההשגה מעוררת רק התלהבות והתפעלות, ולא שאגה. ומזה מובן, שמ\"ש כארי' ישאג הוא מצד התבוננות והשגת השרפים בענין שבאין ערוך, והיינו, שלא זו בלבד שמשיגים את מקור חיותם, אלא עוד זאת, שהם משיגים גם שמקור חיותם הוא הארה בלבד שבאין ערוך כלל לבחי' העצם שממנה נמשך ההארה, וכמו שם האדם שהוא באין ערוך לעצם הנפש<sup data-n=\"1749\">25</sup>, ואפילו להכחות עצמיים ואפילו להכחות מחשבה דיבור ומעשה. והגם שידוע בענין השם שעל ידו הוא המשכת החיות<sup data-n=\"1750\">26</sup>, וכידוע בענין מארז\"ל<sup data-n=\"1751\">27</sup> בשעה שבא הקב\"ה לבראות את האדם נמלך במלאכי השרת כו' אמרו לו אדם זה מה טיבו, אמר להן חכמתו מרובה משלכם, הביא לפניהם את הבהמה ואת החי' ואת העוף, אמר להם זה מה שמו, ולא היו יודעין, העבירן לפני אדם, אמר לו זה מה שמו, אמר זה שור כו', והביאור בזה<sup data-n=\"1752\">28</sup>, לפי שאדה\"ר ידע והשיג שורש החיות של כל נברא, שזהו\"ע השמות, אך מ\"מ, המשכת החיות ע\"י השם היא רק לגבי הגוף (ודוגמתו בענין השם למעלה שהוא המשכת החיות לגבי כללות ההשתלשלות), אבל לגבי עצם הנפש, ומכ\"ש לגבי עצם הנשמה, הרי זה רק הארה שבאין ערוך כלל. וזוהי השגת השרפים,שמתבוננים ומשיגים הענין דאין קדוש כהוי'<sup data-n=\"1753\">29</sup>, שאין שייך לומר עליו שהוא קדוש ומובדל, לפי שאינו בגדר העולמות כלל, ועי\"ז נעשה אצלם ענין השאגה, שזהו מצד ההשגה בבחי' שבאין ערוך. וזהו פירוש הב' במ\"ש שרפים עומדים ממעל לו, דמאחר שהם משיגים הפלאת הסובב, ורוצים ומשתוקקים להכלל בבחי' זו, הרי הם נמצאים בבחינה זו, דבמקום שרצונו של אדם שם הוא נמצא, כפירוש הבעש\"ט בזה. ופירוש זה הוא בעומק יותר מפירוש הא', דלפי פירוש הא' הרי הם באותה המדריגה של מקור חיותם, ורק מפני שהם משיגים ומקיפים מדריגה זו, הרי זה נקרא שהם למעלה ממנה, אבל לפי פירוש הב', הרי הם נמצאים בבחי' הסובב, שבאין ערוך למקור חיותם.\nד) <b>אך</b> עדיין צריך להבין, מה שהכתוב מייחס את השאגה לבחי' ארי' דוקא, שהרי כל האמור לעיל שייך לכללות עבודת המלאכים, ולא לבחי' ארי' דוקא. אך הענין הוא, דהנה כתיב<sup data-n=\"1754\">30</sup> פני ארי' אל הימין גו' ופני שור מהשמאל, והחילוק בין ימין ושמאל הוא, שימין הו\"ע הגילוי, ושמאל הו\"ע הצמצום, ומזה נמשך גם החילוק בין ארי' ושור למטה, שזהו החילוק שבין חיות לבהמות<sup data-n=\"1755\">31</sup> (שהרי ארי' הוא מלך שבחיות ושור מלך שבבהמות<sup data-n=\"1756\">32</sup>), שהחיות הם בבחי' התפעלות וחמימות יותר מבהמות, שבהמות הם בקרירות וחיות הם בחמימות, והיינו מפני תגבורת החיות, שזהו התגלות החיות, משא\"כ השור שכחו חזק, כמ\"ש<sup data-n=\"1757\">33</sup> ורב תבואות בכח שור, כשור לעול<sup data-n=\"1758\">34</sup>, אבל זהו בהעלם. וחילוק זה הוא מצד שרשם<sup data-n=\"1759\">35</sup>, שפני שור הוא מהשמאל, שהו\"ע הצמצום וההעלם, ופני ארי' הוא מימין, שהו\"ע האור והגילוי, שמזה נמשך תגבורת החיות. וזהו ג\"כ שארי' בגימטריא גבורה<sup data-n=\"1760\">36</sup>, דלכאורה אינו מובן, הרי פני ארי' אל הימין, ואיך הוא בחי' גבורה, אלא שזהו ענין תגבורת החיות מצד הגילוי אור שמאיר בהם.\n<b>ובזה</b> יובן ג\"כ הטעם ששור הוא בהמה טהורה משא\"כ ארי', דלכאורה אינו מובן, הרי בשרשו פני ארי' אל הימין, והוא למעלה מפני שור מהשמאל, ומה השור שחיותו בצמצום והעלם טהור הוא, הרי ארי' שחיותוהוא בגילוי הי' בודאי צריך להיות טהור. אך הענין הוא, דהיא הנותנת, שמצד הגילוי אור דפני ארי' אל הימין, אינו יכול להאיר למטה בכלים, רק בדרך שבירה, ולכן הוא טמא. וע\"ד הידוע<sup data-n=\"1761\">37</sup> בענין שבירת הכלים דתהו, דכיון שהיו אורות מרובים, לא היו יכולים להתקבל בכלים, ולכן היתה שבירת הכלים. ועד\"ז מובן גם בענין ארי' ושור, דארי' שחיותו היא מבחי' ימין, שהוא ריבוי אור וחיות, הנה גוף הארי' אינו כלי לריבוי אור וחיות, ולכן הוא גוף טמא, כיון שהגוף הוא רחוק מהחיות, משא\"כ שור שחיותו בצמצום, הנה גוף השור הוא כלי לחיותו, ולכן הוא גוף טהור. ומובן גם מהמשל הידוע דנפילת החומה, שכל מה שנופל מבחינה עליונה יותר נופל למטה יותר<sup data-n=\"1762\">38</sup>, שלכן, ארי' ששרשו למעלה יותר, הוא חי' טמאה. וזהו גם הטעם שארי' הוא טורף ודורס. אמנם, ע\"פ האמור נמצא שהסיבה שארי' הוא טורף ודורס היא מצד גופו, שאינו כלי לריבוי אור. אך באמת צ\"ל שזהו ג\"כ מצד האור, כי, אופן הכלים הוא לפי אופן האורות, וכמו בתהו, שהסיבה לכך שהכלים הם מועטים היא לפי שהאורות הם מרובים, ולכן בהכרח לומר שכל הענינים שישנם בהכלים הנה מעין זה הוא גם בהאורות. ומזה מובן גם בנוגע לארי' שטורף ודורס, שאין זה רק מצד הכלי בלבד, אלא מעין זה הוא גם מצד האור והחיות.\n<b>וזהו</b> גם מ\"ש<sup data-n=\"1763\">39</sup> אם יגעה שור על בלילו (בתמי'), שכאשר יש לשור בליל תבואתו, אז אינו גועה, ודוקא כשאין לו טרף מזונו אז הוא גועה, ובארי' כתיב<sup data-n=\"1764\">40</sup> הישאג ארי' ביער וטרף אין לו (בתמי'), שדוקא כשיש לו טרף אז הוא גועה. והענין בזה, שפני שור מהשמאל הוא בבחי' שוב, שמסתפק בהגילוי אור, שמרווה צמאונו, ולכן הוא בהתיישבות (ורק כשהאור אינו מאיר והוא בבחי' העלם והסתר לגמרי, אז היא השאגה), אבל פני ארי' אל הימין הוא בבחי' רצוא, שאינו מסתפק בהגילוי אור, ואדרבה, ככל שיהי' הגילוי אור יותר הרי זה פועל הרצוא ביותר, והיינו, שמצד גודל הגילוי דאור הממכ\"ע נרגש אצלו הפלאת אור הסוכ\"ע, ומצד זה נעשה ענין השאגה כנ\"ל. וזהו גם מה שארי' טורף ודורס, שענינו בקדושה הוא הכעס וההתגברות על המנגד. וכפי שרואים בענין העבודה, שמי שעבודתו היא בהתיישבות, בבחי' שוב, מצד בחי' ממכ\"ע, לא נוגע לו כ\"כ שיש מציאות של מנגד לאלקות, דכל זמן שהמנגד אינו מנגדלעבודה שלו אין זה נוגע לו (וכללות עבודתו היא בדרך הכנעה וביטול, כשור לעול), משא\"כ מי שעבודתו היא בהתלהבות, בבחי' רצוא, מצד בחי' הסוכ\"ע, הנה כאשר ישנו מציאות של מנגד, אינו יכול לסבול זאת, ופועל לבטל את המנגד (ער זאָל ווערן אויס מנגד), דזהו\"ע טורף ודורס, וכמו הזאב שטורף מלפניו ומלאחריו<sup data-n=\"1765\">41</sup>, והיינו שבכל מקום, מלפניו ומלאחריו, שרואה איזה מציאות של מנגד, הרי הוא טורף אותו, שמבטלו ממציאות של מנגד ועד שמהפכו לקדושה.\nה) <b>וממשיך</b> בכתוב (לאחרי כארי' ישאג) כי הוא ישאג, הוא לשון נעלם, ששאגה זו היא למעלה גם משאגת הארי'. והענין בזה, ששאגת הארי' היא מצד האור שבעולמות, והיינו, שגם ע\"פ משנת\"ל ששאגת הארי' היא מצד הפלאת אור הסובב, הרי גם אור הסובב שייך לעולמות, שלכן נקרא בשם סובב כל עלמין<sup data-n=\"1766\">42</sup>, ולכן הרי זה ג\"כ בכלל אחרי הוי'. אמנם מ\"ש כי הוא ישאג הרי זה מצד אמיתית הסובב שלמעלה מגדר סובב לעלמין. ובנפש האדם הרי זה מצד בחי' המקיף דיחידה שלמעלה גם מבחי' המקיף דחי'. וממשיך בכתוב ויחרדו בנים גו', היינו, שב' הבחי' הנ\"ל בענין השאגה, חודרים (דערנעמען) את כל אחד ואחד מישראל, שנקראו בנים, ולא רק אלו שהם בבחי' בנים, אלא גם אלו שהם במצב הגלות, כפי שמשיך בכתוב כצפור ממצרים, שזהו הגלות שבבחי' מיצר, וכיונה מארץ אשור, שזהו הגלות שבבחי' וישמן ישורון ויבעט<sup data-n=\"1767\">43</sup>, הנה גם בהם נעשה החרדה הבאה בסיבת שאגת הארי'.\n<b>וכללות</b> ענין שאגת הארי' בעבודת האדם קשור עם עבודת הקרבנות, שהרי ענינו של הארי' הוא דאכיל קורבנין<sup data-n=\"1768\">44</sup>, וענין הקרבנות בעבודת האדם הוא כמ\"ש<sup data-n=\"1769\">45</sup> אדם כי יקריב מכם גו', והו\"ע הקרבת נפש הבהמית<sup data-n=\"1770\">46</sup> בכל פרטי הסוגים דשור כשב ועז<sup data-n=\"1771\">47</sup>, שכולם צריכים להיות קרבים באהבה מסותרת שבנפש האדם, שזהו הארי' דאכיל קורבנין שבאדם, שהרי אף שאש יורד מלמעלה מצוה להביא מן ההדיוט<sup data-n=\"1772\">48</sup>, והאששלמטה הו\"ע האהבה מסותרת. וכל זה הוא ההכנה לבחי' אחרי הוי' ילכו, שזוהי התחלת העבודה כנ\"ל.\nו) <b>והנה</b> עיקר ענין הארי' הוא בראש השנה, כידוע<sup data-n=\"1773\">49</sup> שר\"ה הוא בחינת ארי'. אמנם ההכנה לר\"ה מתחילה בחודש אלול, כמ\"ש כ\"ק מו\"ח אדמו\"ר בהמאמרים דאלול לפני עשרים שנה<sup data-n=\"1774\">50</sup> בבואו לארצות הברית [ע\"מ לדור]. ולכן הנה גם באלול ישנו ענין הארי', שהו\"ע התקיעות דאלול הפועלים השאגה והחרדה, ועי\"ז נעשה אחרי הוי' ילכו, שזוהי התחלת העבודה כנ\"ל, ולאח\"ז באים שאר המדריגות, ועד שמגיעים לבחי' ובו תדבקון, בתוספת נו\"ן פשוטה, שיש לה רגל ארוכה ומשוכה למטה, לרמז שתתפשט ותומשך הארת והמשכת גילוי אלקותו ית' למטה מטה כו'<sup data-n=\"1775\">51</sup>, ובאופן שגם למטה ישנו ענין הדביקות כו'. וכן הוא גם בענין חודש אלול, ר\"ת אני<sup data-n=\"1776\">52</sup> לדודי ודודי לי<sup data-n=\"1777\">53</sup>, שההתחלה היא מאני לדודי, ואח\"כ נעשה ודודי לי, שהו\"ע הדביקות, ועד שהאני לדודי ודודי לי נעשים דבר אחד. וממשיך בכתוב הרועה בשושנים, דשושנה אית בה תליסר עלין כנגד י\"ג מכילין דרחמי<sup data-n=\"1778\">54</sup>, שמאירים בחודש אלול. וגם פירוש הרועה בשושנים הוא ששונים בתורה, והו\"ע י\"ג מדות שהתורה נדרשת בהן<sup data-n=\"1779\">55</sup>, שהמשכה זו היא בשמע\"צ ושמח\"ת. והרי התורה היא הכלי להמשכת הכתיבה וחתימה טובה לשנה טובה ומתוקה, בבני חיי ומזוני רויחי.\n**********",[["1725","1","פרשתנו יג, ה."],["1726","2","פרשתנו יט, ב (וראה גם סהמ\"צ להצ\"צ קפה, ב)."],["1727","3","כג, ד ואילך."],["1728","4","סה\"מ תרצ\"ו ס\"ע 141 ואילך (וש\"נ). סה\"מ ה'ש\"ת ע' 153."],["1729","5","עמוס ג, ו. טור או\"ח רסתקפ\"א."],["1730","6","לקו\"ת פרשתנו לב, א ואילך."],["1731","7","מסכת אלול פ\"א, ג."],["1732","8","ראה פע\"ח שער ר\"ה בתחילתו."],["1733","9","עקב י, י ובפרש\"י. וראה גם פרש\"י: תשא לג, יא. עקב ט, יח."],["1734","10","הושע יא, י-יא."],["1735","11","עמוס ג, ח."],["1736","12","פרשתנו יד, א."],["1737","13","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380959\" data-slug=\"likkutei-torah\" data-id=\"4001380959\">לקו\"ת</a> דרושים לר\"ה ס, א. סה\"מ אידיש ע' 80 ואילך."],["1738","14","בהבא לקמן – ראה ד\"ה אני לדודי דש\"פ ראה עת\"ר (סה\"מ עת\"ר ס\"ע רלב ואילך). וראה גם ד\"ה כתיב אחרי ה' ילכו כארי' ישאג באוה\"ת דרושים לר\"ה ע' א'תיג ואילך. ד\"ה אתם נצבים תשכ\"ב (סה\"מ תשכ\"ב ע' שלה ואילך)."],["1739","15","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380423\" data-slug=\"likkutei-torah\" data-id=\"4001380423\">לקו\"ת נשא כח, סע\"ד</a>. פינחס עז, ד. ועוד."],["1740","16","תקו\"ז ת\"ו (כג, א)."],["1741","17","ישעי' ו, ב."],["1742","18","ראה אוה\"ת בראשית ח\"ו תתרכז, ב. סה\"מ תרל\"ה ח\"א ע' ו. ח\"ב ע' שב. וש\"נ."],["1743","19","ישעי' שם, א."],["1744","20","פרק ה. וראה גם לקו\"ת חוקת סב, ג. סה\"מ תרע\"ח ע' תיז ואילך. סה\"מ תרפ\"ו ע' קסא ואילך. ד\"ה מים רבים תשי\"ז פ\"ז (תו\"מ חי\"ח ע' 203)."],["1745","21","שבת קלח, ב."],["1746","22","תהלים לח, ט."],["1747","23","שם סג, ב."],["1748","24","יומא פו, ב. תניא פ\"ז."],["1749","25","ראה תו\"א ר\"פ תרומה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380254\" data-slug=\"likkutei-torah\" data-id=\"4001380254\">לקו\"ת בהר מא, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380588\" data-slug=\"likkutei-torah\" data-id=\"4001380588\">בלק סז, ג</a>. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רכב ואילך. אוה\"ת שמות ע' קג ואילך."],["1750","26","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310060\" data-slug=\"tanya\" data-id=\"3401310060\">תניא</a> שער היחוד והאמונה ספ\"א."],["1751","27","ב\"ר פי\"ז, ד."],["1752","28","ראה רמב\"ן ובחיי בראשית ב, יט. של\"ה בהקדמה בית המקדש (יד, א). לקוטי אמרים להרב המגיד סימן רמד. אור תורה להרב המגיד ד, סע\"ב ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380413\" data-slug=\"likkutei-torah\" data-id=\"4001380413\">לקו\"ת</a> בהר שם. נשא כו, ב. כז, א. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560151\" data-slug=\"or-hatorah-hb\" data-id=\"8316560151\">אוה\"ת בראשית ח\"ג תקמב, א</a>. סה\"מ תר\"ל ע' סז ואילך. ע' צז ואילך. המשך מים רבים תרל\"ו פרק כב. המשך תער\"ב ח\"א פרק שז ואילך. סה\"מ תרח\"ץ ע' קז. וש\"נ."],["1753","29","שמואל-א ב, ב."],["1754","30","יחזקאל א, י."],["1755","31","ראה גם אוה\"ת דרושים ליום הכפורים ח\"ה ע' ב'קלא."],["1756","32","חגיגה יג, ב."],["1757","33","משלי יד, יד."],["1758","34","ע\"ז ה, ב."],["1759","35","ראה גם ביאורי הזהר פ' ויחי לאדמו\"ר האמצעי (כז, ג ואילך) ולאדמו\"ר הצ\"צ (ח\"א ע' קנט ואילך)."],["1760","36","מאורי אור מערכת א אות קא."],["1761","37","ראה עץ חיים שער הכללים פ\"א-ב. שער התיקון פ\"ה. שער המלכים פ\"א ופ\"ה. ובכ\"מ."],["1762","38","לקו\"ת פרשתנו יט, ג."],["1763","39","איוב ו, ה."],["1764","40","עמוס ג, ד."],["1765","41","מכילתא יתרו כ, ח. וראה סה\"מ תרפ\"ט ע' 117."],["1766","42","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370439\" data-slug=\"torah-or\" data-id=\"3901370439\">תו\"א מגלת אסתר צח, ב</a>. סה\"מ עטר\"ת ע' שעא. תרפ\"ט ע' 40. תרצ\"ז ע' 192. ועוד."],["1767","43","האזינו לב, טו."],["1768","44","ראה זהר ח\"ג לב, סע\"ב. לקו\"ת\nבמדבר יא, א. סה\"מ תרצ\"ו ע' 126. תרח\"ץ ע' רכט. תש\"ט ע' 30 (השני)."],["1769","45","ויקרא א, ב."],["1770","46","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380083\" data-slug=\"likkutei-torah\" data-id=\"4001380083\">לקו\"ת ויקרא ב, ב</a> ואילך."],["1771","47","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380085\" data-slug=\"likkutei-torah\" data-id=\"4001380085\">לקו\"ת שם ב, ד</a>. קונטרס התפלה פ\"ח (ע' 20). ספר השיחות תורת שלום ע' 10."],["1772","48","יומא כא, ב."],["1773","49","ראה לקו\"ת ר\"פ עקב. ובכ\"מ."],["1774","50","ד\"ה אני לדודי וסד\"ה לך אמר לבי ה'ש\"ת (סה\"מ ה'ש\"ת ע' 151. 153. 155. 167)."],["1775","51","לקו\"ת פרשתנו כ, סע\"ב."],["1776","52","שה\"ש ו, ג."],["1777","53","אבודרהם סדר תפלת ר\"ה ופירושה פ\"א. ראשית חכמה שער התשובה פ\"ד (קטו, ב). פע\"ח שער ר\"ה פ\"א. ב\"ח לטור או\"ח סתקפ\"א (ד\"ה והעבירו). של\"ה במסכת ר\"ה שלו (ריג, א). לקו\"ת פרשתנו (לב, א). ועוד."],["1778","54","לקו\"ת פרשתנו לג, א. ועוד."],["1779","55","ראה לקו\"ת שם לג, ד. אוה\"ת שם ע' תשפה."]]],[1400350032,"בלתי מוגה\n<b>א</b>. פרשת<sup data-n=\"1780\">1</sup> ראה קורין לעולם בשייכות לחודש אלול – בשבת מברכים חודש אלול, או בראש חודש אלול.\nוע\"פ פתגם רבינו הזקן – ששמענו כמ\"פ<sup data-n=\"1781\">2</sup> שחזר עליו כ\"ק מו\"ח אדמו\"ר – שצריכים \"לחיות עם הזמן\", עם פרשת השבוע, הרי מובן במכ\"ש, שפרשה בתורה שקורין בפני כל עם ועדה תמיד באותו זמן, הרי היא קשורה עם זמן זה.\nובנדו\"ד – שפרשת ראה קשורה עם ענינו של חודש אלול.\n<b>ב</b>. חודש אלול הוא החודש שבו עורכים חשבון-נפש על השנה שעברה, ועי\"ז זוכים לכתיבה וחתימה טובה לשנה הבאה. ונמצא, שחודש אלול הוא החודש המקשר את השנה שעברה עם השנה הבאה.\nושני הענינים נלמדים זה מזה: כשם שבנוגע לשנה הבאה, הנה ע\"י העבודה דחודש אלול זוכים לקבל <b>טוב גמור</b> בגשמיות וברוחניות – הנה גם בנוגע לשנה שעברה פועלת העבודה דחודש אלול שנעשה <b>כולו טוב</b>.\nוהענין בזה:\nגם בנוגע לשנה שעברה, שזהו ענין של \"עבר\", שלכאורה הרי זה כבר דבר אבוד – הנה בכח התשובה נעשים בעה\"ב גם על העבר.\nוזוהי מעלת בעלי תשובה לגבי צדיקים גמורים<sup data-n=\"1782\">3</sup> – שצדיקים גמורים הם בעה\"ב רק על ההוה והעתיד, ואילו ע\"י עבודת התשובה נעשים בעה\"ב גם על העבר.\nוהבעלות על העבר היא באופן שנעשה <b>כולו טוב</b>, והיינו, שלא זו בלבד שמבטלים את הרע, \"וסר עונך וחטאתך תכופר\"<sup data-n=\"1783\">4</sup>, אלא יתירה מזה – שעושים ממנו טוב, כמארז\"ל<sup data-n=\"1784\">5</sup> \"זדונות נעשו לו כזכיות\".\nולא עוד אלא שה\"זכיות\" שנעשים ע\"י עבודת התשובה הם במדריגה היותר נעלית:ב\"זכיות\" יש כמה מדריגות: יש \"זכיות\" שהם באופן ד\"מצות אנשים מלומדה\"<sup data-n=\"1785\">6</sup> בלבד. ויש גם \"זכיות\" במדריגה תחתונה יותר – כפי שמביא רבינו הזקן בהלכות תלמוד תורה<sup data-n=\"1786\">7</sup> שיכול להיות קיום התומ\"צ באופן שעי\"ז \"מוסיף כח בקליפות לפי שעה\", ומ\"מ, הרי הם \"זכיות\".\nאמנם, ה\"זכיות\" שנעשים ע\"י התשובה – כיון שנעשים ע\"י תשובה מאהבה,\n– כדאיתא בגמרא&lt;5&gt; שבשביל הפיכת זדונות לזכיות לא מספיק תשובה מיראה, אלא יש צורך בתשובה מאהבה דוקא,\nוכפי שמבאר רבינו הזקן בתניא<sup data-n=\"1787\">8</sup> \"שהיא תשובה מאהבה מעומקא דלבא [שהו\"ע העבודה שמצד פנימיות הלב, ובפנימיות הלב גופא – הפנימיות של ב' המדריגות, כמבואר בלקו\"ת<sup data-n=\"1788\">9</sup>] באהבה רבה וחשיקה וכו'\", ש\"על תשובה מאהבה רבה זו אמרו שזדונות נעשו לו כזכיות הואיל ועל ידי זה בא לאהבה רבה זו\" –\nהרי מובן שהם במדריגה נעלית ביותר, למעלה גם מה\"זכיות\" של צדיקים גמורים שעבודתם היא ע\"פ טעם ודעת.\nוזוהי מעלת חודש אלול, שבכל יום שבו, בכחו של יהודי לפעול שיהי' אצלו תכלית הטוב גם בנוגע להעבר, לא רק בחודש אלול עצמו, אלא גם בכל השנה שעברה, וגם בכל השנים הקודמות מיום היותו לאיש. ומזה מובן גודל היוקר והעילוי שבכל יום מימי חודש אלול.\n<b>ג</b>. וזוהי גם השייכות דפרשת ראה לחודש אלול:\n\"ראה גו'\" – פירושו – שדורשים מכל אחד מישראל שיהי' אצלו ענין הראי' באלקות.\nולכאורה אינו מובן: כיצד יכולים לדרוש מכאו\"א מישראל דרגא נעלית כזו?\nיכולים לדרוש ענין של <b>הודאה</b>, היינו, שאע\"פ שאין לו הכרה והבנה כו', מ\"מ, הרי הוא מודה על זה, בידעו שהלה הוא למעלה ממנו; וכמו\"כ יכולים לדרוש מדריגה נעלית יותר – <b>שמיעה והשגה</b>. אבל, גם כאשר משיג את הדבר, יתכן שעדיין אין זה נרגש בלב, ומכ\"ש שאינובאופן של ראי', שהיא ההתאמתות היותר חזקה<sup data-n=\"1789\">10</sup>, שלכן אמרו רז\"ל<sup data-n=\"1790\">11</sup> \"אינה דומה שמיעה לראי'\". וא\"כ, כיצד יכולים לדרוש מכאו\"א מישראל ענין של <b>ראי'</b> ברוחניות, ובפרט באלקות?\nאך הענין הוא – שפרשה זו קורין ב(שייכות ל)חודש אלול:\nחודש אלול הוא מארבעים יום האחרונים שעליהם אמרו<sup data-n=\"1791\">12</sup> \"מה הראשונים ברצון אף אחרונים ברצון\", שאז הוא גילוי רצון העליון. ומצד גילוי רצון העליון מתעורר גם רצון הפנימי שבנפש, ובאופן שחודר גם בהגוף הגשמי.\nוזהו גם ענין תקיעת שופר שבחודש אלול (שהוא בדוגמת ענין תק\"ש דראש השנה<sup data-n=\"1792\">13</sup>) \"כדי להזהיר ישראל שיעשו תשובה שנאמר<sup data-n=\"1793\">14</sup> אם יתקע שופר בעיר ועם לא יחרדו\"<sup data-n=\"1794\">15</sup> – שאפילו אלו שהם בבחינת \"עם\" מלשון (גחלים) עוממות (כמ\"ש בשער היחוד והאמונה<sup data-n=\"1795\">16</sup>), היינו, שניצוץ היהדות (\"דער אידישער פונק\") שנמצא בתוכם אינו מאיר ומחמם, הוא בקושי (\"קאַם קאַם\") עומם, הנה גם אצלם נעשה ענין של חרדה מצד הגילוי שבחודש אלול.\nואע\"פ שהגילוי הוא למעלה ממדריגתם, הרי זה פועל חרדה גם בגופם הגשמי – ע\"ד מ\"ש<sup data-n=\"1796\">17</sup> \"והאנשים אשר היו עמי לא ראו את המראה אבל חרדה גדולה נפלה עליהם ויברחו גו'\", ופירשו חז\"ל<sup data-n=\"1797\">18</sup> \"אע\"ג דאינהו לא חזו מזלייהו חזו\", דהיינו, שאף שהגילוי הוא מבחי' המזל שלמעלה מגופם, מ\"מ, אין זה כמו ה\"בת-קול\" שנשמע אצל הנשמה, ולפעמים אינו מאיר בהגוף כלל, אלא מצד זה ש\"מזלייהו חזו\" נפלה עליהם חרדה גדולה גם בגופם הגשמי, שלכן \"ויברחו גו'\".\nונמצא, שמצד הגילויים שבחודש אלול בכחו של יהודי לפעול זיכוך גם בגופו הגשמי, כך, שאפילו לעיני בשר יוכלו לראות שגופו נזדכך.\nומצד זיכוך הגוף יכול להיות אצלו הענין ד\"ראה\" – ראיית אלקות בעין בשר הגשמי.\n<b>ד</b>. וזהו \"ראה אנכי נותן לפניכם היום ברכה וקללה\"<sup data-n=\"1798\">19</sup>:הענין ד\"ברכה וקללה\" – קאי על כללות העבודה דחודש אלול, שנחלקת לב' ענינים: (א) ברכה – העבודה ד\"ועשה טוב\" בנוגע לשנה הבאה, (ב) קללה – העבודה ד\"סור מרע\" בנוגע לתיקון שנה שעברה.\nומדייק בכתוב \"ברכה <b>ו</b>קללה\", בוא\"ו המוסיף (לא כפשוטו, וא\"ו המחלק, אלא וא\"ו המוסיף, הוספה על ענין הברכה) – שכשם שהעבודה בנוגע לשנה הבאה (\"ברכה\") פועלת שיהי' כולו טוב, כך גם העבודה בנוגע לשנה שעברה (\"קללה\") פועלת שיהי' כולו טוב, כנ\"ל ש\"זדונות נעשו לו כזכיות\", \"זכיות\" בדרגא היותר נעלית.\nועז\"נ \"ראה אנכי נותן לפניכם היום ברכה וקללה\" – שמצד הגילוי (\"ראה\") ד\"אנכי מי שאנכי\" שמתגלה בכל אחד מישראל, הרי הוא פועל הענין ד\"היום\", לשון אור וגילוי, היינו, שיאירו אצלו ב' הקוין ד\"ברכה וקללה\", שכל הענינים, גם העבר, נעשים טוב גמור,\nועי\"ז הרי הוא זוכה לכתיבה וחתימה טובה, בגשמיות וברוחניות גם יחד.\n***\n<b>ה</b>. לאחרי סיום הענין ד\"ראה אנכי נותן וגו'\" – נאמר בהמשך הפרשה<sup data-n=\"1799\">20</sup>: \"אלה החוקים והמשפטים אשר תשמרון לעשות בארץ גו'\", \"אבד תאבדון את כל המקומות אשר עבדו שם הגוים אשר אתם יורשים אותם את אלהיהם על ההרים הרמים ועל הגבעות ותחת כל עץ רענן\", שזהו הציווי הראשון מיד בהכניסה לארץ, שלכל לראש – \"אבד תאבדון וגו'\".\nוצריך להבין:\nהתורה היא נצחית<sup data-n=\"1800\">21</sup>, בכל מקום ובכל זמן, גם בזמן הגלות, וגם עתה, בסוף זמן הגלות. וכמו כן גם <b>הסדר</b> בתורה, שגם הוא תורה<sup data-n=\"1801\">22</sup> – נצחי הוא בכל זמן ובכל מקום.\nולכאורה: הציווי \"אבד תאבדון גו'\" שייך רק בארץ ישראל, ורק בזמן שיד ישראל תקיפה. ואפילו בנוגע לע\"ז של ישראל – הרי מצינו בגמרא<sup data-n=\"1802\">23</sup> שהחלישו לגמרי את היצה\"ר של ע\"ז. ואף שמצד האפשרות לגרות את היצה\"ר יכולה להיות מציאות ד\"שרש פורה ראש ולענה\"<sup data-n=\"1803\">24</sup>של ע\"ז – עדיין אינו מובן: מדוע הציווי \"אבד תאבדון\" צריך להיות ציווי <b>ראשון</b> בתורה הנצחית?!\n<b>ו</b>. ויובן בהקדם תורת הבעש\"ט<sup data-n=\"1804\">25</sup>:\n\"כי לא מחשבותי מחשבותיכם ולא דרכיכם דרכי<sup data-n=\"1805\">26</sup>, פירוש, כי כאשר האדם מפריד את עצמו מהשי\"ת, מיד הוא עובד עבודה זרה, ולא יש דבר ממוצע, וזהו וסרתם ועבדתם\" (\"וסרתם ועבדתם אלהים אחרים\"<sup data-n=\"1806\">27</sup> – \"תיכף כשסרתם מאת ה', מיד ועבדתם אלהים אחרים\"<sup data-n=\"1807\">28</sup>).\nכלומר: \"כי לא מחשבותי מחשבותיכם\" – כאשר האדם חושב מחשבה שאינה אלקות, אזי \"לא דרכיכם דרכי\" – כיון שסר מדרך ה' ועובד אלהים אחרים.\nוהביאור בזה – כמבואר בספר מאור עינים<sup data-n=\"1808\">29</sup> בפירוש תורת הבעש\"ט על הפסוק \"וסרתם ועבדתם אלהים אחרים\", \"תיכף כשסרתם מאת ה', מיד ועבדתם אלהים אחרים\" – לפי ש\"עיקר הדעת לידע שכל כחותיו וחיותו הוא הבורא ב\"ה שהוא תקיף ובעל היכולת ובכל הכחות כולם<sup data-n=\"1809\">30</sup>, והוא יתברך מנענע כל הכחות שלו, ותיכף כשסר מדעת זה נעשה עובד אלהים אחרים, כחות אחרים זולת הבורא ב\"ה, שאין לו דעת זה שכל הכחות שלו הוא הבורא ב\"ה\".\nכלומר: לא זו בלבד שהקב\"ה הוא בורא העולם ומנהיגו, היינו, שיש עוד מציאות של כחות בעולם, והוא בעה\"ב עליהם, אלא, מלבדו ית' אין מציאות של כחות כלל, כי הוא ית' בעל הכחות כולם, וכל הכחות שבעולם הם כגרזן ביד החוצב. ולכן, כאשר חושבים שיש מציאות של כחות זולתו ית', הרי זה ענין של עבודה זרה – \"ועבדתם אלהים אחרים\".\nוכמ\"ש הרמב\"ם<sup data-n=\"1810\">31</sup> ששרש הענין דע\"ז הוא – לא כפירה באלקות לגמרי, אלא – המחשבה ש\"הואיל והאלקים ברא כוכבים אלו וגלגלים להנהיג את העולם . . ראויין הם לשבחם ולפארם ולחלוק להם כבוד, וזהו רצון הא-ל ברוך הוא . . כמו שהמלך רוצה לכבד העומדים לפניו\".\nהוא אמנם מודה שהקב\"ה הוא בעה\"ב על השרים שלמעלה,כוכבים וגלגלים, וכל חוקי הטבע, אבל, הוא סבור שיש להם כח בעצמם, וכמו שר שנתמנה ע\"י המלך, שאף שכחו הוא מצד המלך, הרי הוא בעל בחירה ועושה כרצונו, ולפעמים – גם שלא כפי רצון המלך.\nוזהו שרש הענין דע\"ז, שממנו משתלשל הענין דע\"ז היותר תחתון – כפירה באלקות לגמרי.\nדלכאורה, כיצד יתכן מציאות של ע\"ז באופן של כפירה לגמרי, הרי כתיב<sup data-n=\"1811\">32</sup> \"מי לא יראך מלך הגוים\"?! – אלא ההתחלה היא מהשיטה שעזב ה' את הארץ בידי כוכבים ומזלות, כיון ש\"רם על כל גוים ה'\"<sup data-n=\"1812\">33</sup>, ומצד גדלותו ורוממותו אינו מתעסק עם כל הפרטים והענינים הקטנים; ומזה באים אח\"כ לכפירה לגמרי.\nוזהו \"וסרתם ועבדתם אלהים אחרים\" – שכיון שנמצאים בגוף ונפש הבהמית ומסובבים בעניני העולם, הנה \"תיכף כשסרתם מאת ה' מיד ועבדתם אלהים אחרים\", כי, כאשר מסיח דעת לרגע מאלקות, אזי מתחיל להיות מונח אצלו ענין הטבע ועניני העולם, שיש בהם כח כו', ועד להענין ד\"טבע\" מלשון \"טובעו בים סוף\"<sup data-n=\"1813\">34</sup>, שהניצוץ אלקי שבעניני העולם הוא באופן של טביעה (\"פאַרטרונקען\") וההעלם, שלא ניכר כלל האלקות שבעולם, ועד לכפירה לגמרי.\n<b>ז</b>. וזהו הטעם שהציווי הראשון הוא \"אבד תאבדון\" – כיון שמזה באים לכללות העבודה דתומ\"צ:\nענין המצוות הוא – שלוקחים דבר גשמי ועושים ממנו כלי לאלקות.\nוכדי שדבר גשמי יוכל להיות כלי לאלקות – הנה לכל לראש צריך להיות \"אבד תאבדון\", לאבד את כללות ענין הע\"ז, ולא רק הע\"ז עצמה, אלא גם \"את כל המקומות גו'\", היינו, שלא תהי' <b>נתינת מקום</b> כלל לענין של ע\"ז, והיינו, ע\"י ההכרה ש\"אין עוד מלבדו\"<sup data-n=\"1814\">35</sup>.\n– שאלו פעם אצל הבעש\"ט<sup data-n=\"1815\">36</sup>: מהו החידוש שלו, הרי גם לפנ\"ז היו יהודים שומרי תומ\"צ, צדיקים וכו', ומה חידש בדרכו המיוחדת? והשיב: יש שני דרכים כיצד להתמודד עם גנב. דרך אחת היא – לצעוקכנגדו, ואז הוא נבהל ובורח, אבל עדיין יכול הוא לנסות שוב, ולחשוב שבפעם השני' יצליח. אבל ישנה דרך נוספת – שזוהי דרכו של הבעש\"ט – לתפוס את הגנב ולפעול עליו להשתנות ולהיות איש ישר, ואז אין לחשוש שינסה לגנוב שוב. –\nועי\"ז – \"אתם יורשים אותם\":\nובהקדים – ש\"ירושה\" הו\"ע השייך לכל, שהרי אפילו קטן יורש, וגם גדול שמתנהג כמו קטן, הנה להיותו \"בן\", הרי הוא יורש.\nוזהו \"אשר אתם יורשים אותם\" – שע\"י העבודה דבירור הניצוצות דתהו שבדברים הגשמיים, יורשים את האורות דתהו<sup data-n=\"1816\">37</sup>, ובאופן של התיישבות – \"וירשתה וישבת בה\"<sup data-n=\"1817\">38</sup>, ונעשים בעה\"ב על כל עניני העולם, שיהי' ניכר בהם אלקות – \"אין עוד מלבדו\".\nוענין זה קורין בר\"ח אלול או בשבת מברכים חודש אלול, חודש חשבון-הנפש על כל השנה – כיון שאחת העבודות הכלליות והעיקריות היא העבודה ד\"אבד תאבדון גו'\", עי\"ז שמחדירים את ההרגש ש\"אין עוד מלבדו\", שזהו יסוד כל התורה והמצוות.\n***\n<b>ח</b>. צוה לנגן ואמר מאמר ד\"ה אחרי הוי' אלקיכם תלכו וגו'.\n***\n<b>ט</b>. דובר לעיל (ס\"ג) אודות הגילוי דחודש אלול שפועל ענין של חרדה (\"ועם לא יחרדו\"), שעם היותו למעלה מהגוף, הרי הוא פועל גם על הגוף הגשמי, וכמו הגילוי ד\"מזלייהו חזו\", שעי\"ז נעשה ענין של חרדה בהגוף הגשמי.\nובכללות – הרי זה גילוי מבחי' הסובב<sup data-n=\"1818\">39</sup>.\nומצד גילוי זה נעשה גם ענין התשובה – כי, מצד בחי' הסובב אין הגבלות, ולכן יכולים לפעול שגם הרע יתהפך לטוב<sup data-n=\"1819\">40</sup>.\n[גם ענין זה הוא חידוש של פנימיות התורה, שהרי ע\"פ נגלה דתורה, ענין התשובה הוא \"שיעזוב החוטא חטאו . . ויגמור בלבו שלא יעשהו עוד\" (כמ\"ש הרמב\"ם<sup data-n=\"1820\">41</sup>), דהיינו, הסרת הרע בלבד; אבל ע\"פפנימיות התורה ענין התשובה הוא גם הפיכת הרע לטוב. ומרומז גם בנגלה דתורה – בדברי הגמרא&lt;5&gt; ש\"זדונות נעשו לו כזכיות\"].\nועפ\"ז מובן החילוק שבין התשובה דבני ישראל להתשובה דאומות העולם<sup data-n=\"1821\">42</sup>:\nעצם ענין התשובה ישנו גם אצל אוה\"ע, כפי שמצינו באנשי נינוה<sup data-n=\"1822\">43</sup>. אבל, פעולת התשובה דאוה\"ע היא רק <b>מכאן ולהבא</b>, להסיר הגזירה כו'; ואילו אצל בנ\"י פועלת התשובה גם על <b>העבר</b>, כאמור, ש\"זדונות נעשו לו כזכיות\".\nוטעם הדבר – כיון שבנ\"י שייכים לבחי' הסובב, ואוה\"ע שייכים רק לבחי' הממלא, כמבואר בדרושי חג הפסח<sup data-n=\"1823\">44</sup> שהאמונה של בנ\"י היא בבחי' הסובב, ואילו האמונה של אוה\"ע היא בבחי' הממלא, ולכן, רק אצל בנ\"י ישנה פעולת התשובה גם בנוגע להעבר, שזהו מצד בחי' הסובב, שעי\"ז הנה גם הרע נהפך לטוב.\nוכאמור, אף שזהו גילוי נעלה ביותר, הרי זה חודר ופועל גם בגוף הגשמי.\n<b>י</b>. ענין זה (שגם ענין <b>שלמעלה</b> מהגוף חודר ופועל <b>בהגוף</b>) קשור גם עם המדובר לעיל<sup data-n=\"1824\">45</sup> בענין ברכת המזון – \"שכתבתי להם בתורה ואכלת ושבעת וברכת את ה' אלקיך<sup data-n=\"1825\">46</sup>, והם מדקדקים על עצמם עד כזית ועד כביצה\"<sup data-n=\"1826\">47</sup>:\nכיון שבתורה נאמר \"ואכלת <b>ושבעת</b> וברכת\", הרי לא יתכן שבנ\"י יעשו היפך התורה, ח\"ו, לברך גם כאשר לא שבעו עדיין.\nועכצ\"ל, שמצד העבודה ד\"מדקדקים על עצמם\", פועלת הנשמה שגם הגוף יהי' שבע מאכילת כזית וכביצה.\nמצד הנשמה – מספיק גם כזית וכביצה בשביל שביעה, וא\"כ, צועקת הנשמה שכיון שנהנתה מעולמו של הקב\"ה, רצונה לברך לא רק לפני האכילה אלא גם לאחרי'. ואע\"פ שהגוף צועק שמצד טבעו אינו שבע עדיין, מ\"מ, פועלת הנשמה שגם הגוף יהי' שבע.\n<b>יא</b>. וגם בענין זה יש חילוק בין נגלה דתורה לפנימיות התורה:ע\"פ נגלה דתורה – ברכת המזון לאחרי אכילת כזית או כביצה אינה מן התורה, אלא רק מדרבנן, כפס\"ד השו\"ע<sup data-n=\"1827\">48</sup>.\nאמנם, בזהר פ' תרומה<sup data-n=\"1828\">49</sup> איתא: \"אפילו לא ייכול בר נש אלא כזית, ורעותי' איהו עלי', וישוי לי' לההוא מיכלא עקרא דמיכלי', שבעא אקרי\", כך, שהחיוב דברכת המזון הוא מן התורה.\nוהרי \"אלו ואלו דברי אלקים חיים\"<sup data-n=\"1829\">50</sup>, אלא, שבנוגע להלכה, ידוע מ\"ש רבינו הזקן<sup data-n=\"1830\">51</sup> ש\"כל דבר שבעלי הקבלה והזוהר חולקים עם הגמרא או הפוסקים הנמשכים אחר הגמרא, הלך אחר הגמרא או הפוסקים הנמשכים אחרי', ומ\"מ, אם בעלי הקבלה מחמירים יש להחמיר ג\"כ, אבל אין אנו יכולים לכוף את הצבור להחמיר כו'\".\nוהענין בזה:\nהתורה על הרוב תדבר<sup data-n=\"1831\">52</sup>, והרי רוב בני אדם אינם אוחזים במדריגה כזו שיהי' אצלם אמיתית הענין ד\"בכל דרכיך דעהו\"<sup data-n=\"1832\">53</sup>, כך, שהנהגת הגוף באכילה ושתי' תהי' כפי שהיא מצד הנשמה. אלא, כיון שהנשמה צועקת שאצלה גם כזית וכביצה הוא שיעור שביעה, קבעו רבנן שיש לוותר (\"נאָכגעבן\") להנשמה ולברך ברכת המזון;\nאמנם, אלו שהנהגתם היא ע\"פ פנימיות התורה (בעלי הקבלה), ואוחזים בעבודה ד\"בכל דרכיך דעהו\" לאמיתתה – אצלם פועלת הנשמה שגם הגוף הגשמי יהי' שבע מאכילת כזית וכביצה, והיינו, שלא נוגע הכמות, אלא יש צורך בשיעור שהוא כלי לברכת הוי' – שזהו כזית וכביצה, שענינם הוא אות יו\"ד דשם הוי' ואות יו\"ד דשם אדנ-י<sup data-n=\"1833\">54</sup>.\nובכל אופן, הנה תוכן כללות הענין ד\"מדקדקים על עצמם עד כזית עד כביצה\" הוא ע\"ד ענין החרדה שע\"י התקיעות דחודש אלול – שעניני הנשמה חודרים ופועלים גם בהגוף.\n<b>יב</b>. כל האמור לעיל שייך לכללות העבודה דחודש אלול. וענינו של שבת מברכים חודש אלול הוא הנקודה הכוללת את כל הנ\"ל, ע\"ד האות ב' ד\"בראשית\" שכוללת את כל התורה<sup data-n=\"1834\">55</sup>.וכן הוא גם ביום א' דר\"ח אלול, שיש בו הנקודה הכוללת את כל חודש אלול.\nועפ\"ז יש לבאר דבר פלא בנוגע להנהגות דחודש אלול:\nכ\"ק מו\"ח אדמו\"ר אומר<sup data-n=\"1835\">56</sup> שביום ב' דר\"ח אלול מתחילים לתקוע בשופר, וביום א' דר\"ח אלול תוקעין להתלמד.\nולכאורה, מהו ענין התקיעה להתלמד ביום א' דר\"ח אלול – דממה-נפשך: אם ענין התקיעות שייך ליום א' דר\"ח, יש להתחיל לתקוע ביום א' דר\"ח, ואם לאו, הרי בשביל סתם להתלמד יכולים להתחיל להתלמד כמה ימים לפנ\"ז?\nאך הענין הוא – שביום א' דר\"ח אלול ישנה הנקודה הכוללת את כל חודש אלול. וענין התקיעה להתלמד הוא – שאפילו כאשר לא אוחזים עדיין בענין התקיעות כראוי, שאינו יכול אפילו לתקוע בקול פשוט, מ\"מ, תוקעין להתלמד, שענינו הוא, שגם הטעות הוא מכלל התיקון, כיון שהטעות מביא לידי תיקון, שילמד לתקוע כראוי&lt;13&gt;.\n***\n<b>יג</b>. בתפלת מנחה מתחילים לקרוא: \"שופטים ושוטרים תתן לך בכל שעריך וגו'\"<sup data-n=\"1836\">57</sup>.\nואיתא בספרי מוסר<sup data-n=\"1837\">58</sup> ובספרי חסידות<sup data-n=\"1838\">59</sup>, וכבר דובר על זה פעם במאמר<sup data-n=\"1839\">60</sup>, שהאדם צריך להעמיד \"שופטים ושוטרים\" בכל ה\"שערים\" שבגופו, בנוגע לאכילה ושתי', ראי', שמיעה, ריח ודיבור, שכל ענינים אלו יהיו באופן של \"משפט צדק\", ועי\"ז – \"צדק צדק תרדוף\"<sup data-n=\"1840\">61</sup>, צדק בנוגע לעצמו, וצדק בנוגע לעולם.\nוענין זה צריך להיות באופן ד\"תתן לך\", ש\"כל הנותן בעין יפה הוא נותן\"<sup data-n=\"1841\">62</sup>.\nועי\"ז יקויים גם הענין ד\"שופטים ושוטרים תתן לך בכל שעריך\" <b>כפשוטו</b> – בארץ ישראל, שעתידה שתתפשט בכל הארצות, וירושליםתתפשט בכל ארץ ישראל<sup data-n=\"1842\">63</sup>, בגאולה השלימה ע\"י משיח צדקנו, במהרה בימינו.\n**********",[["1780","1","בהתחלת שיחה זו תיקן כ\"ק אדמו\"ר שליט\"א כמה תיקונים (<b>המו\"ל</b>)."],["1781","2","ראה – לדוגמא – סה\"ש תש\"ב ע' 29 ואילך (נעתק ב\"היום יום\" ב חשון)."],["1782","3","ראה ברכות לד, ב. רמב\"ם הל' תשובה פ\"ז ה\"ד."],["1783","4","ישעי' ו, ז."],["1784","5","יומא פו, ב."],["1785","6","ישעי' כט, יג. וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא פל\"ט (נג, ב</a>). ובכ\"מ."],["1786","7","פ\"ד ה\"ג."],["1787","8","פ\"ז."],["1788","9","תצא לו, א."],["1789","10","ראה גם לעיל ע' 279."],["1790","11","מכילתא יתרו יט, ט."],["1791","12","פרש\"י תשא לג, יא. עקב ט, יח. ועוד."],["1792","13","ראה גם תו\"מ חי\"ב ע' 227."],["1793","14","עמוס ג, ו."],["1794","15","טואו\"ח ר\"ס תקפא."],["1795","16","רפ\"ז."],["1796","17","דניאל יו\"ד, ז."],["1797","18","מגילה ג, א. וש\"נ."],["1798","19","ראה גם שיחת ש\"פ ראה, מבה\"ח אלול דאשתקד ס\"ב ואילך (תו\"מ חכ\"ו ע' 212 ואילך). וש\"נ."],["1799","20","יב, א ואילך."],["1800","21","<a class=\"ft-cite\" href=\"#/read/tanya/3401310022\" data-slug=\"tanya\" data-id=\"3401310022\">תניא רפי\"ז</a>. ובכ\"מ."],["1801","22","ראה של\"ה חלק תושבע\"פ, כלל לשונות בתחלתו (תב, ב)."],["1802","23","ראה יומא סט, ב ובחדא\"ג מהרש\"א שם."],["1803","24","נצבים כט, יז."],["1804","25","צוואת הריב\"ש סע\"ו."],["1805","26","ישעי' נה, ח."],["1806","27","עקב יא, טז."],["1807","28","מאור עינים דלקמן."],["1808","29","ר\"פ שמות."],["1809","30","כמ\"ש בשו\"ע (או\"ח ס\"ה) בפירוש הכוונה דשם \"אלקים\"."],["1810","31","ריש הל' ע\"ז."],["1811","32","ירמי' יו\"ד, ז."],["1812","33","תהלים קיג, ד."],["1813","34","בשלח טו, ד."],["1814","35","ואתחנן ד, לה."],["1815","36","ראה כתר שם טוב (הוצאת תשנ\"ט) בהוספות סשצ\"ו. וש\"נ. וראה גם תו\"מ חט\"ז ע' 234 ואילך."],["1816","37","ראה סה\"מ תר\"ל ע' פח. תרנ\"ד ע' ל. תש\"ב ע' 40. ועוד."],["1817","38","ר\"פ תבוא."],["1818","39","חסר קצת (<b>המו\"ל</b>)."],["1819","40","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380622\" data-slug=\"likkutei-torah\" data-id=\"4001380622\">לקו\"ת פינחס עה, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380848\" data-slug=\"likkutei-torah\" data-id=\"4001380848\">ראה לג, ב</a>. ובכ\"מ."],["1820","41","הל' תשובה פ\"ב ה\"ב."],["1821","42","ראה ספר הערכים חב\"ד (כרך ב) ערך אוה\"ע סי\"ז סק\"ט (ע' שמט ואילך). וש\"נ."],["1822","43","יונה ג, ה ואילך."],["1823","44","סידור (עם דא\"ח) שער חהמ\"צ בתחלתו (רפד, ג)."],["1824","45","שיחת ש\"פ עקב, כ\"ף מנחם-אב ס\"ב (לעיל ע' 270)."],["1825","46","עקב ח, יו\"ד."],["1826","47","ברכות כ, ב."],["1827","48","ראה שו\"ע אדה\"ז או\"ח סקפ\"ד ס\"ב. וש\"נ."],["1828","49","קנג, רע\"ב. וראה בהנסמן בנצו\"ז שם."],["1829","50","עירובין יג, ב. וש\"נ."],["1830","51","שו\"ע או\"ח סכ\"ה סכ\"ח."],["1831","52","ראה מו\"נ ח\"ג פל\"ד."],["1832","53","משלי ג, ו. וראה רמב\"ם הל' דעות ספ\"ג."],["1833","54","ראה זח\"ג רמד, ב (ברע\"מ). הובא בלקו\"ת נשא כז, ריש ע\"ד."],["1834","55","ראה תקו\"ז ריש תיקון לב. וראה גם דגל מחנה אפרים פ' בשלח (לג, ב) עה\"פ (טו, כג) ויבואו מרתה."],["1835","56","\"היום יום\" ל מנ\"א, ר\"ח (אלול). הדיעות בזה – ראה נו\"כ הטושו\"ע או\"ח סתקפ\"א. וראה גם לקו\"ש חל\"ד ע' 95 ואילך."],["1836","57","ר\"פ שופטים."],["1837","58","ש\"ך עה\"ת ר\"פ שופטים. של\"ה ס\"פ שופטים."],["1838","59","אוה\"ת פ' שופטים ע' תתכב. סה\"מ תרל\"ג ח\"ב ע' תסט."],["1839","60","ד\"ה שופטים ושוטרים דש\"פ שופטים, ד' אלול תשט\"ז פ\"ג (תו\"מ חי\"ז ע' 181)."],["1840","61","שם, כ."],["1841","62","ראה ב\"ב נג, רע\"א. וש\"נ."],["1842","63","ראה ספרי דברים בתחלתו. פס\"ר פ' שבת ור\"ח. יל\"ש ישעי' רמז תקג."]]],[1400350033,"בלתי מוגה\n<b>א</b>. על הפסוק<sup data-n=\"1843\">1</sup> \"קומי אורי כי בא אורך\", ידועה תורת הבעש\"ט<sup data-n=\"1844\">2</sup> – שנמסרה ע\"י כ\"ק מו\"ח אדמו\"ר בשם אביו, כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע, ששמע מהבעש\"ט בגן-עדן<sup data-n=\"1845\">3</sup> – שאמרה לנשיאי ישראל<sup data-n=\"1846\">4</sup>:\nאתם נשיאי ישראל, שמניחים (\"איר לייגט אַוועק\") את תורתכם ועבודתכם בשביל טובת הרבים – מה יהי' עמכם? הנה על זה נאמר \"קומי אורי כי בא אורך\", שיומשך לא רק האור הכללי אלא גם האור הפרטי.\nומובן, שאע\"פ שתורה זו נאמרה לנשיאי ישראל, מ\"מ, מזה שכ\"ק מו\"ח אדמו\"ר סיפר וחזר תורה זו בהתוועדות גדולה<sup data-n=\"1847\">5</sup>, מוכח, שיש לזה שייכות לכל ישראל.\nוהענין בזה – שאצל כאו\"א מישראל ישנו הציווי \"הוכח תוכיח את עמיתך\"<sup data-n=\"1848\">6</sup>, שזהו בדוגמת העבודה דנשיאי ישראל.\n<b>ב</b>. אך לכאורה אינו מובן:\nכאשר יהודי מוכיח את חבירו, לא שייך לשאול \"מה יהי' עמו\" – כי גם כאשר מוכיח את חבירו הרי הוא בעצמו מקיים מצוה: \"הוכח תוכיח את עמיתך\".\nועד\"ז בנוגע לנשיאי ישראל – שע\"י התעסקותם בטובת הרבים הרי הם עצמם מקיימים מצוה:\nנשיאות – הו\"ע המלכות, שזוהי מצוה: \"שום תשים עליך מלך\"<sup data-n=\"1849\">7</sup>, וכיון שמצוה זו אינה יכולה להתקיים אלא כאשר ישנו מי שמקבל על עצמו להיות מלך, נמצא, שעי\"ז שהמלך מקבל על עצמו את המלוכה, הרי הוא משתתף וגורם קיום מצות מינוי מלך.וע\"ד שמצינו בענין ברכת כהנים, שיש סברא<sup data-n=\"1850\">8</sup> שמצוה זו היא לא רק על הכהנים, אלא גם על הישראלים, דכיון שברכת כהנים אינה יכולה להתקיים אלא רק כאשר ישנם המתברכים, נמצא, שהמצוה שייכת גם אליהם.\nונוסף לכך ישנם גם מצוות המלך, ומה גם שעי\"ז שהמלך מקיים מצוות אלו, הרי הוא מוציא את כל ישראל ידי חובתן<sup data-n=\"1851\">9</sup>.\nכלומר: כל מצוה שיהודי מקיים פועלת גם בנוגע לכל ישראל, אם מצד ענין הערבות<sup data-n=\"1852\">10</sup>, או מצד העובדה ש\"כל העולם שקול\"<sup data-n=\"1853\">11</sup>, ולכן הוספת \"מצוה אחת\" היא זכות לכל ישראל. אבל, ענין זה הוא באופן <b>שהמצוה עצמה</b> מתקיימת על ידו, ורק <b>הפעולה</b> שנעשית ע\"י המצוה היא עבור כל ישראל; ואילו במצוות המלך שייכת גם <b>המצוה עצמה</b> לכל ישראל, שהרי כל אחד מישראל חייב לקיים כל תרי\"ג מצוות, אלא שהמלך מוציא את כל ישראל <b>ידי חובתן</b>.\nועפ\"ז אינו מובן: מהי השאלה \"אתם נשיאי ישראל כו' מה יהי' עמכם\" – הרי בזה גופא מקיימים הם מצוה?!\n<b>ג</b>. והביאור בזה:\nבקיום המצוות יש ב' ענינים: (א) ע\"י קיום המצוה ממלאים רצון העצמות, (ב) ע\"י קיום המצוה ממשיכים המשכות והשפעות כו'.\nומובן, שאע\"פ שההמשכות וההשפעות הם רק אורות וגילויים שאינם בערך לגבי הענין העיקרי שבמצוות שעי\"ז מקיימים רצון העצמות, מ\"מ, רצון העצמות הוא שע\"י המצוות יומשכו גם אורות וגילויים. וכיון שזהו רצון העצמות, הרי כאשר חסר ענין זה, אזי חסר מעיקר ענין המצוה<sup data-n=\"1854\">12</sup>.\nוזהו הביאור בדברי הבעש\"ט \"אתם נשיאי ישראל, שמניחים את תורתכם ועבודתכם בשביל טובת הרבים, מה יהי' עמכם\" – כי, אע\"פ שבכך מקיימים מצוה וממלאים את הרצון העצמי, מ\"מ, בנוגע לענין האורות וגילויים (שגם זה רצון העצמות כנ\"ל) הרי זה ענין של <b>ירידה</b>, כי:המלך – \"משכמו ומעלה גבוה מכל העם\"<sup data-n=\"1855\">13</sup>.\nובפרט מצד הענין דהתנשאות עצמית, בחי' המלך המרומם לבדו מאז<sup data-n=\"1856\">14</sup>, ועד\"ז בנשיאי ישראל, דכיון \"שאין על גביו אלא הוי' אלקיו\"<sup data-n=\"1857\">15</sup>, הרי הוא חד (\"איין זאַך\") עם הקב\"ה, כך, שגם אצלו ישנו הענין דהתנשאות עצמית, שלכן צריכה להיות הנהגתו בהרחבה כו'.\nולכן, כאשר המלך יורד אל העם, משכמו ולמטה – הרי זו ירידה גדולה.\nועל זה בא המענה: \"קומי אורי כי בא אורך\" – שיתוסף גם בהאורות והגילויים, וכהלשון בתורת הבעש\"ט: לא רק באור הכללי, אלא גם באור הפרטי.\nועד\"ז בכל אחד מישראל בפעולתו בענין \"הוכח תוכיח את עמיתך\":\nאע\"פ שזוהי מצוה, מ\"מ, בענין הגילויים הרי זו ירידה, כי, גם אם בכללות נמצא חבירו במעמד ומצב נעלה יותר ממנו, הרי כיון שבפרט זה שצריך להוכיחו נמצא חבירו למטה ממנו, הנה בשעה שמוכיח את חבירו הרי זו ירידה עבורו.\nועז\"נ \"קומי אורי כי בא אורך\" – שע\"י ההתעסקות עם הזולת להוכיחו כו', יתוסף אצל המוכיח גם בענין האורות והגילויים.\n<b>ד</b>. וזהו גם מה שמבואר בתו\"א<sup data-n=\"1858\">16</sup> במעלת הצדקה, שעי\"ז \"נעשה מוחו ולבו זכים אלף פעמים ככה\":\nכללות ההתעסקות בענין הצדקה, הן צדקה גשמית, והן צדקה רוחנית, הו\"ע של ירידה בענין הגילויים, כאמור לעיל שגם אם בכללות נמצא המקבל במדריגה נעלית יותר מן הנותן, הנה בענין פרטי זה שמקבל בתורת צדקה הרי הוא למטה מן הנותן, ולכן, ההתעסקות ליתן לו צדקה הו\"ע של ירידה בענין הגילויים.\nועל זה אומרים, שלא זו בלבד שלא יחסר אצלו בענין הגילויים, אלא אדרבה, שיתוסף אצלו גם בענין הגילויים, ולא רק הוספה סתם, אלא הוספה גדולה ביותר – אלף פעמים ככה.ולהעיר, שהלשון \"אלף פעמים\" אינו בדרך גוזמא, אלא הכוונה היא אכן לאלף פעמים ככה – כמובן מהמבואר בלקו\"ת לג\"פ<sup data-n=\"1859\">17</sup> שמביא על זה מארז\"ל<sup data-n=\"1860\">18</sup> \"אלף בני אדם נכנסין למקרא יוצא מהן מאה למשנה, מאה למשנה יוצאין מהן עשרה לתלמוד, עשרה לתלמוד יוצא מהם אחד להוראה\" (היינו שתמיד נשאר חלק עשירי), שמזה מובן שהמספר אלף הוא בדיוק.\n<b>ה</b>. ובפרטיות יותר:\nבחינת אלף – היא בחי' החכמה (כמבואר שם), ובענין העולמות הו\"ע עולם האצילות, שלמעלה מהשתלשלות, שהרי התחלת ההשתלשלות היא מבחי' הבינה.\nוכאשר ישנה העבודה ד\"הוכח תוכיח את עמיתך\", \"אפילו מאה פעמים\"<sup data-n=\"1861\">19</sup>, שמספר מאה הוא בבינה<sup data-n=\"1862\">20</sup>, והיינו, שמצד עבודתו מגיע רק בבחי' ההשתלשלות – אזי נותנים לו מלמעלה בחי' אלף, שלמעלה מהשתלשלות.\nועד\"ז בענין הנשיאות והמלוכה – שדוקא ע\"י הירידה להיות נשיא ומלך מגיעים לבחי' החכמה, כידוע בענין אבא יסד ברתא<sup data-n=\"1863\">21</sup>, שע\"י המלכות (ברתא) נעשה גילוי החכמה (אבא), שבכללות הוא בחי' שלמעלה מהשתלשלות, ובפרט ע\"פ המבואר במק\"א<sup data-n=\"1864\">22</sup> בענין אל\"ף ד\"אחד\" שאל\"ף הוא בחי' הכתר.\nונקודת הענין – שכדי לבוא לתכלית העילוי הרי זה ע\"י הירידה דוקא. וזהו תכלית המכוון – להמשיך העליון ביותר בהתחתון ביותר.\nומרומז גם בלשון \"אלף פעמים ככה\": \"<b>ככה</b>\" – היא מדריגה תחתונה, כמבואר שם ההפרש בין \"זה\" ל\"כה\" ו\"ככה\". ודוקא ע\"י הירידה לבחי' \"ככה\", שלמטה לא רק מ\"זה\", אלא גם מ\"כה\" – באים לבחי' \"<b>אלף</b>\".\nוזהו גם הענין ד\"יוצא מהם אחד להוראה\": ענין ההוראה הוא בעולם המעשה דוקא, וכמארז\"ל<sup data-n=\"1865\">23</sup> \"אין למדין הלכה לא מפי למוד כו' עד שיאמרו לו הלכה למעשה\". ולאידך גיסא, הנה דוקא הלכה למעשהמגעת בבחי' נעלית ביותר, כמבואר בארוכה בהמשך יו\"ט של ר\"ה תרס\"ו<sup data-n=\"1866\">24</sup> במעלת ההלכה, שנמשכת (לא משם אלקים, ואפילו לא \"(אלו ואלו דברי) אלקים חיים\"<sup data-n=\"1867\">25</sup>, בחי' הבינה, אלא) משם הוי' דוקא, כמ\"ש<sup data-n=\"1868\">26</sup> \"והוי' עמו\", ודרשו חז\"ל<sup data-n=\"1869\">27</sup> ש\"הלכה כמותו\".\nוזהו גם סיום הפסוק \"וכבוד <b>הוי'</b> עליך זרח\" – שבזה מתבאר גודל העילוי ד\"קומי אורי גו'\", שבאים לבחי' הוי'.\n<b>ו</b>. וזהו גם כללות ענין התגלות הנשיאים<sup data-n=\"1870\">28</sup> וגילוי המשיח:\nבביאת המשיח נאמר<sup data-n=\"1871\">29</sup> \"היום אם בקולו תשמעו\", ולכן יצטרכו לפעול הענין ד\"בקולו תשמעו\" אצל כל אחד מישראל, אפילו אצל יהודי שנמצא <b>בשפל המצב ביותר</b>, וכידוע<sup data-n=\"1872\">30</sup> שזוהי מעלת הגאולה העתידה על הגאולות שלפנ\"ז, שבהם לא נגאלו כל בנ\"י, ואילו בגאולה העתידה יצאו כל בנ\"י מהגלות, כך, שיהי' הענין ד\"בקולו תשמעו\" אצל כל אחד מישראל. ומובן, שכדי לפעול הענין ד\"בקולו תשמעו\" אצל מי שנמצא בשפל המצב ביותר, יש צורך בירידה גדולה ביותר.\nולאידך גיסא – הרי גילוי המשיח הוא תכלית העילוי, וכידוע<sup data-n=\"1873\">31</sup> שמשיח יהי' לא רק רב, אלא גם מלך<sup data-n=\"1870\">28</sup>.\n<b>ז</b>. אך עדיין צריך להבין:\nמהו טעם הדבר שגודל העילוי בענין האורות והגילויים בא ע\"י הירידה דוקא, דלכאורה, איזה מקום יש בשכל על זה, שלא זו בלבד שע\"י גודל הירידה לא יגרע מאומה, ולא זו בלבד שעי\"ז יתוסף יותר, אלא עוד זאת, שתהי' הוספה שבאין ערוך?!\n– הקב\"ה הוא אמנם כל יכול, ולא שייך לשאול קושיות; אבל אעפ\"כ, הרי כל ענין ניתן גם בהבנה והשגה.\nובהקדמה, שמצינו ענין זה בשיעור תניא דח\"י אלול – כפי שסידר כ\"ק מו\"ח אדמו\"ר חלוקת השיעורים בדיוק – הן בהשיעור דח\"י אלול בשנה פשוטה, והן בהשיעור דח\"י אלול בשנה מעוברת.<b>ח</b>. בשיעור דח\"י אלול לשנה פשוטה<sup data-n=\"1874\">32</sup> איתא:\n\"שמעתי ממורי ע\"ה ע\"פ<sup data-n=\"1875\">33</sup> ואנכי עפר ואפר שאמר אברהם אבינו ע\"ה על הארת נשמתו המאירה בגופו מאור חסד עליון והיא מדתו מדת אהבה רבה שהי' אוהב את הקב\"ה אהבה גדולה ועליונה . . וסד\"א שבחי' חסד ואהבה שלמעלה בספירות העליונות היא מעין וסוג מהות מדת אהבה רבה של א\"א ע\"ה, רק שהיא גדולה ונפלאה ממנה . . אבל מ\"מ סד\"א שמדותי' הן מעין וסוג מדות העליונות, ולז\"א ואנכי עפר ואפר, דכמו שהאפר . . אין לו דמיון וערך אל מהות העץ הגדול . . קודם שנשרף (אף ש\"עיקרו הי' מיסוד העפר . . והכל שב אל העפר שהוא האפר הנשאר כו'\") . . כך עד\"מ אין דמיון וערך מהות אור האהבה המאיר בו אל מהות אור אהבה וחסד עליון שבאצילות אלא כערך ודמיון מהות העפר שנעשה אפר אל מהותו ואיכותו כשהי' עץ נחמד למראה וטוב למאכל עד\"מ ויותר מזה כו'\".\nוכמבואר גם בענין אברהם אברהם פסיק טעמא בגווייהו<sup data-n=\"1876\">34</sup>, שאברהם שלמטה אינו בערך כלל לאברהם שלמעלה. וכל זה אפילו בנוגע לבחינתו של אברהם למטה כפי שהוא מצד עצמו, ועאכו\"כ בשעה שהתפלל על אנשי סדום, שגם בהיותו למטה היתה זו ירידה לגביו, הרי בודאי שאינו אלא בבחי' עפר ואפר.\nואעפ\"כ, איתא בספר הבהיר<sup data-n=\"1877\">35</sup> \"אמרה מדת החסד לפני הקב\"ה רבש\"ע מימי היות אברהם בארץ לא הוצרכתי אני לעשות מלאכתי שהרי אברהם עומד ומשמש במקומי\", היינו, שבהיותו למטה החליף את מדת החסד דאצילות,\nוכידוע פתגם רבינו<sup data-n=\"1878\">36</sup> שמדת החסד דאצילות אמרה זאת מתוך <b>קנאה</b> באברהם, ומזה מוכח שאברהם הי' במדריגה נעלית יותר מחסד דאצילות, שהרי ענין הקנאה הוא במעלה שחסרה אצלו.\nוהיכן נעשית מעלה זו בעבודתו של אברהם? – לא בהיותו באצילות, אלא דוקא כשירד למטה ונעשה בבחי' עפר ואפר.\nוענין זה מודגש יותר אצל משה רבינו:משה משה לא פסיק טעמא בגווייהו&lt;34&gt;, שבהיותו למטה הי' כמו למעלה<sup data-n=\"1879\">37</sup>.\nוזוהי כללות מעלת התורה (ובפרט פנימיות התורה) שניתנה על ידו – שלא זו בלבד שע\"י הירידה למטה ניתוסף איזו מעלה (כמו באברהם), אבל בכללות נשארת הירידה למטה, אלא פעולת התורה היא – לבטל את ה\"פסיק טעמא\", כך, שלמטה הרי זה ממש כמו למעלה, ואדרבה, באופן נעלה יותר, שהרי דוקא למטה קיבל משה את התורה.\nוזה גם כללות הענין דח\"י אלול, התגלות הבעש\"ט והתגלות תורת החסידות, שענינה הוא לפעול הענין ד\"מחצתי ואני ארפא\"<sup data-n=\"1880\">38</sup>, שע\"י המחיצה עצמה באים לתוספת עילוי.\n<b>ט</b>. ובשיעור דח\"י אלול לשנה מעוברת<sup data-n=\"1881\">39</sup> (שבה צריכה להיות <b>הוספה</b> כדי להשוות שנת הלבנה עם שנת החמה<sup data-n=\"1882\">40</sup>) איתא:\n\"כ\"ז הוא בנפש השכלית התחתונה שבאדם הבאה מקליפת נוגה, אך באמת לאמיתו בנפש העליונה האלקית שהיא חלק אלקה ממעל כל המדות וכו'\", ומתחיל לבאר ענין המדות דנפש האלקית.\nולכאורה אינו מובן:\nכיון שהעיקר היא נפש האלקית – למה מקדים לבאר באריכות גדולה ענין המדות בנפש השכלית, ואח\"כ מסיים בקצרה בנוגע לנפש האלקית?\nאך הענין הוא – שצריכה להיות הירידה במדות דנפש השכלית, ודוקא עי\"ז באים לעילוי גדול יותר בהמדות דנפש האלקית (וע\"ד האמור לעיל בענין הירידה דאברהם בבחי' עפר ואפר).\n<b>י</b>. והביאור בזה:\nמצד סדר השתלשלות – כל הענינים הם בערך; ודוקא כאשר ישנה ירידה למטה באופן שבאין ערוך, אזי מתגלה האין ערוך דהעצמות, שהתגלותו היא בהאין ערוך דיש הנברא.\nולכן, כאשר ישנה הירידה בגוף הגשמי, אזי מתגלה ענין נמנע הנמנעות שמצד העצמות, שהוא נושא הפכים<sup data-n=\"1883\">41</sup>,– ע\"ד ש\"מקום ארון אינו מן המדה\"<sup data-n=\"1884\">42</sup>, דאף שהוצרך להיות \"אמתיים וחצי ארכו ואמה וחצי רחבו ואמה וחצי קומתו\"<sup data-n=\"1885\">43</sup>, מדידה ע\"פ תורה, מ\"מ, במדידה גופא הי' הענין ד\"אינו מן המדה\", שזהו מצד נמנע הנמנעות –\nומצד זה נעשה היחוד של הקצה התחתון ביותר עם הקצה העליון ביותר.\n*\n<b>יא</b>. בין שבעת התורות שאמר מורנו הבעש\"ט&lt;2&gt;, ישנה גם התורה שנאמרה בהקהל (ובה היו נוכחים גם הנשים) – על הפסוק<sup data-n=\"1886\">44</sup> \"והי' כי תבוא אל הארץ\"<sup data-n=\"1887\">45</sup>:\n\"והי' כי תבוא אל הארץ\" – ארץ לשון רצון ומרוצה<sup data-n=\"1888\">46</sup> – אזי צריכה להיות העבודה \"וישבת בה\" – להמשיך בהתיישבות, \"ושמת בטנא\" – להמשיך אורות בכלים, \"והלכת אל המקום אשר יבחר ה' אלקיך\" – שכל מקום שאליו הולך יהודי, הרי זה בבחירת העצמות.\n<b>יב</b>. והביאור בזה:\nהפסוק \"והי' כי תבוא אל הארץ וגו'\" הוא בפרשת ביכורים, שצריכים להיות מן המובחר דוקא<sup data-n=\"1889\">47</sup>, ולא רק שהפירות עצמם צריכים להיות מובחרים, אלא גם המקומות שמהם מביאים את הפירות צריכים להיות מקומות המובחרים<sup data-n=\"1889\">47</sup>.\nומה גם שהיותם מובחרים אינו מצד הטבע, אלא מפני שארץ ישראל היא \"ארץ אשר גו' תמיד עיני ה' אלקיך בה גו'\"<sup data-n=\"1890\">48</sup>.\nומזה מובן שענין הביכורים מורה על אורות בלתי מוגבלים.\nואעפ\"כ נאמר \"ושמת בטנא\":\nעל הפסוק \"ושמת בטנא\", איתא בספרי \"הביכורים טעונין <b>כלי</b>\" – ענין הכלים.\nוזהו גם מ\"ש בדגל מחנה אפרים<sup data-n=\"1891\">49</sup> בשם הבעש\"ט, ש\"טנא ר\"ת<b>ט</b>עמים <b>נ</b>קודין <b>א</b>תוון\"<sup data-n=\"1892\">50</sup> – שזהו ענין הכלים, כפי שרואים בשכל המלובש באותיות, שהאותיות הם כלים אל השכל, ועוד זאת, שלא די בהאותיות עצמם כדי לגלות את השכל, אלא יש צורך גם בנקודות, ובכדי לגלות גם את החיות של השכל, הרי זה ע\"י הטעמים. ונמצא, ש\"טנ\"א\" – טעמים נקודות ואותיות – הו\"ע הכלים.\nוזהו מ\"ש בביכורים \"ושמת בטנא\" – שגם האורות הבלתי מוגבלים (ביכורים) צריך להמשיך בכלים (טנא).\nומסיים, \"אשר <b>יבחר</b> ה' אלקיך\" – בחירת העצמות:\nאמיתית ענין הבחירה הוא רק בהעצמות. – באור, להיותו מוגדר בגדר האור, שחושך הוא מנגד אליו כו', אזי לא יכול להיות ענין הבחירה; ורק בהעצמות שבו היא שלילת כל התוארים, ישנו ענין הבחירה.\nומצד העצמות, שהוא נמנע הנמנעות, נמשך הכח להיות \"ושמת בטנא\", להמשיך את האורות הבלתי מוגבלים – בכלים.\n<b>יג</b>. והנה, בכלים גופא יש שני אופנים:\nא) כלים של <b>דיבור</b>, וכפי שמסיים בדגל מחנה אפרים (בפירוש \"ושמת בטנא\" ש\"טנא ר\"ת <b>ט</b>עמים <b>נ</b>קודין <b>א</b>תוון\") ש\"הוא ע\"ד אם<sup data-n=\"1893\">51</sup> שגורה תפלתי בפי\", והרי ענין התפלה הוא בדיבור. ועפ\"ז יובן גם מה שלא חשיב תגין, כי בתפלה לא נוגע ענין התגין, כמבואר במק\"א<sup data-n=\"1894\">52</sup>.\nב) כלים של <b>מעשה</b> – לא רק מעשה זוטא, דעקימת שפתיו (שבהם נכללים כל שאר המוצאות<sup data-n=\"1895\">53</sup>) הוי מעשה<sup data-n=\"1896\">54</sup>, אלא גם מעשה כפשוטו, מעשה רבה, שדוקא עי\"ז נעשה הבירור ד\"רב תבואות בכח שור\"<sup data-n=\"1897\">55</sup>.\nוהחילוק בין ב' אופנים אלו תלוי גם אם נמצאים במעמד ומצב ד\"עושין רצונו של מקום\" אם לאו:\nענין התפלה (כלים של דיבור) – עיקרה הוא עבודה שבלב<sup data-n=\"1898\">56</sup>, והו\"ע האהבה ד\"בכל לבבך ובכל נפשך ובכל מאדך\"<sup data-n=\"1899\">57</sup>, והרי העבודה ד\"בכל מאדך\" הו\"ע \"עושין רצונו של מקום\"<sup data-n=\"1900\">58</sup>.ובזמן שעושין רצונו של מקום – מספיקה גם הירידה בדיבור, ואין צורך בהירידה במעשה, כיון ש\"מלאכתן נעשית ע\"י אחרים, שנאמר<sup data-n=\"1901\">59</sup> ועמדו זרים ורעו צאנכם\"<sup data-n=\"1902\">60</sup>. וע\"ד שהי' בזמן שלמה, שניצוצות הקדושה נתבררו בדרך ממילא<sup data-n=\"1903\">61</sup>.\nאבל בזמן שאין עושין רצונו של מקום – אזי צריכה להיות הירידה גם בענין המעשה, שזהו ענין הגלות ש\"אחד מכם גולה לברברי' כו'\"<sup data-n=\"1904\">62</sup>, והיינו, שלא זו בלבד שמלאכתם אינה נעשית ע\"י הזרים, אלא אדרבה, שצריכים לעשות גם את מלאכתם של הזרים, שזהו\"ע הגלות, התלבשות בבחי' תחתונה ביותר.\nאמנם, אף שההתלבשות בכלים של מעשה היא ירידה גדולה יותר מאשר ההתלבשות בכלים של דיבור, מ\"מ, ע\"י הירידה במעשה דוקא מגיעים לעילוי גדול יותר מאשר ע\"י הירידה בדיבור – ע\"ד המבואר בהמשך תרס\"ו<sup data-n=\"1905\">63</sup> שדוקא ע\"י מעשה המצוות מגיעים לעילוי גדול יותר מאשר ע\"י לימוד התורה, כולל גם היגיעה בתורה, \"דדחקין<sup data-n=\"1906\">64</sup> למלה דחכמתא\"<sup data-n=\"1907\">65</sup>.\n**********",[["1843","1","ישעי' ס, א."],["1844","2","ראה כתר שם טוב (הוצאת תשנ\"ט) בהוספות ס\"ג. וש\"נ."],["1845","3","ראה גם שיחת ש\"פ תבוא, ח\"י אלול תשי\"ז בתחלתה (תו\"מ ח\"כ ע' 239). וש\"נ."],["1846","4","ראה גם שיחת ח\"י אלול תשי\"ב ס\"כ ואילך (תו\"מ ח\"ו ס\"ע 170 ואילך)."],["1847","5","בשיחת ש\"פ בראשית (בסעודה) תרצ\"ז ס\"ב (סה\"ש תרצ\"ז ריש ע' 207)."],["1848","6","קדושים יט, יז."],["1849","7","פ' שופטים יז, טו."],["1850","8","דעת החרדים (מ\"ע כו' התלויות בפה כו' לקיימם בכל יום פ\"ד אות יח). וראה הפלאה כתובות (כד, ב) ברש\"י ד\"ה דאיסור עשה (הובא בשע\"ת או\"ח סקכ\"ח סק\"ב). וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171237\" data-slug=\"likkutei-sichot\" data-id=\"1300171237\">לקו\"ש חי\"ז ע' 237</a> הערה 55."],["1851","9","ראה תניא אגה\"ק רסכ\"ט. תו\"א שמות נג, ג."],["1852","10","ראה ספר הגלגולים פ\"ד."],["1853","11","קידושין מ, רע\"ב ובפרש\"י. וראה רמב\"ם הל' תשובה פ\"ג ה\"ד."],["1854","12","ראה גם לקו\"ש ח\"ה ע' 245."],["1855","13","שמואל-א ט, ב. וראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770414\" data-slug=\"or-hatorah-hb\" data-id=\"8316770414\">אוה\"ת</a> וירא (כרך ד) תרסד, ב. שה\"ש (כרך ב) ע' תיד ואילך. ועוד."],["1856","14","נוסח ברכות ק\"ש. וראה תניא אגה\"ק ס\"ו. ובכ\"מ."],["1857","15","הוריות יו\"ד, א (במשנה). וש\"נ."],["1858","16","בראשית א, ב."],["1859","17","בראשית ג, א ואילך. ולאח\"ז באוה\"ת בראשית (כרך ו) תתרכו, ב ואילך."],["1860","18","ויק\"ר רפ\"ב. קה\"ר פ\"ז, כח."],["1861","19","ב\"מ לא, א."],["1862","20","ראה אוה\"ת תולדות קלט, א."],["1863","21","זח\"ג רמח, א. רנו, סע\"ב. רנח, א. ועוד."],["1864","22","ראה אמ\"ב פתח השער ספ\"א. וראה גם תו\"מ סה\"מ כסלו ע' יד."],["1865","23","ב\"ב קל, ב."],["1866","24","ד\"ה כל השונה הלכות (ע' תכז ואילך)."],["1867","25","עירובין יג, ב. וש\"נ."],["1868","26","שמואל-א טז, יח."],["1869","27","סנהדרין צג, ב."],["1870","28","חסר קצת (<b>המו\"ל</b>)."],["1871","29","תהלים צה, ז. וראה סנהדרין צח, א."],["1872","30","ראה לקו\"ש חי\"א בתחלתו. וש\"נ. וראה גם תו\"מ חכ\"ז ע' 492. וש\"נ."],["1873","31","ראה סהמ\"צ להצ\"צ מצות מינוי מלך פ\"ג (דרמ\"צ קי, ב ואילך). ובכ\"מ."],["1874","32","אגה\"ק סט\"ו (קכא, סע\"א ואילך)."],["1875","33","וירא יח, כז."],["1876","34","זח\"ג קלח, רע\"א (אד\"ר). וראה סה\"מ תש\"ט ע' 152 הערה 15. וש\"נ."],["1877","35","סקצ\"א (זח\"א בהשמטות רסד, רע\"ב) – הובא ונת' בפרדס שכ\"ב פ\"ד."],["1878","36","ראה סה\"ש תרח\"ץ ריש ע' 252. ע' 255. אגרות-קודש אדמו\"ר מוהריי\"צ ח\"ד ע' שכא."],["1879","37","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380916\" data-slug=\"likkutei-torah\" data-id=\"4001380916\">לקו\"ת נצבים מט, ב</a>."],["1880","38","האזינו לב, לט. וראה קה\"ר פ\"א, ד (ג). המשך חייב אדם לברך תרל\"ח פכ\"ה (סה\"מ תרל\"ח ס\"ע קנב)."],["1881","39","אגה\"ק שם (קכג, סע\"א)."],["1882","40","ראה רמב\"ם הל' קידוה\"ח פ\"א ה\"ב."],["1883","41","ראה שו\"ת הרשב\"א ח\"א סתי\"ח. הובא ונת' בס' החקירה להצ\"צ לד, ב ואילך. ובכ\"מ."],["1884","42","יומא כא, סע\"א. וש\"נ."],["1885","43","תרומה כה, יו\"ד."],["1886","44","ריש פרשתנו."],["1887","45","סה\"ש תרצ\"ז ע' 191 (נעתק ב\"היום יום\" חי אלול). וראה גם שיחת ש\"פ תבוא, ח\"י אלול תשי\"ז ס\"ב ואילך (תו\"מ ח\"כ ע' 240 ואילך)."],["1888","46","ראה ב\"ר פ\"ה, ח ובמת\"כ ומהרז\"ו שם. תו\"א בראשית א, סע\"ג."],["1889","47","ראה בכורים פ\"א מ\"ג. רמב\"ם הל' בכורים פ\"ב ה\"ג."],["1890","48","עקב יא, יב."],["1891","49","עה\"פ (פרשתנו כח, ה) ברוך טנאך (עה, ב)."],["1892","50","מגלה עמוקות אופן נג."],["1893","51","ברכות לד, ב (במשנה)."],["1894","52","ראה גם או\"ת להה\"מ ריש פרשתנו. הובא בתו\"מ סה\"מ אלול ע' רעג."],["1895","53","ראה ב\"מ\"מ, הגהות והערות קצרות\" לתניא פל\"ז (ע' רל) הערה ד\"ה וקיי\"ל. וש\"נ."],["1896","54","סנהדרין סה, א."],["1897","55","משלי יד, ד. וראה לקו\"ת האזינו עה, ב."],["1898","56","ריש מס' תענית. רמב\"ם ריש הל' תפלה."],["1899","57","ואתחנן ו, ה."],["1900","58","ראה ברכות לה, ב ובחדא\"ג מהרש\"א שם."],["1901","59","ישעי' סא, ה."],["1902","60","ברכות שם."],["1903","61","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370021\" data-slug=\"torah-or\" data-id=\"3901370021\">תו\"א בראשית ה, סע\"ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380324\" data-slug=\"likkutei-torah\" data-id=\"4001380324\">לקו\"ת במדבר ד, א</a>. ובכ\"מ."],["1904","62","שהש\"ר פ\"ב, ח (ב)."],["1905","63","ע' עח ואילך."],["1906","64","זח\"א קל, ב."],["1907","65","סיום ההתוועדות חסר (<b>המו\"ל</b>)."]]],[1400350034,"<h3>בס\"ד. ליל ג' דסליחות, ה'תש\"כ<sup data-n=\"1908\">*</sup></h3>\n<b>לך</b> אמר לבי בקשו פני גו'<sup data-n=\"1909\">1</sup>, ומביא כ\"ק מו\"ח אדמו\"ר במאמרו ד\"ה זה<sup data-n=\"1910\">2</sup> פירוש רש\"י עה\"פ, דבלך שני פירושים. בשבילך בשליחותך ובמקומך. וממשיך בהמאמר, שגם בבקשו פני שני פירושים. שבקשו הוא בקשה ותחינה, ושבקשו הוא בקשה וחיפוש. ומבאר, דשני ענינים אלה (בקשה ותחינה, בקשה וחיפוש) הם בתפלה. דתפלה היא בקשה ותחינה, והבקשה היא שיצליח בעבודתו לחפש ולמצוא דרכי התיקון בכל עניניו. וזהו מ\"ש לך אמר לבי בקשו פני (לבי דוקא), כי שני הענינים דבקשו פני הם בתפלה (כנ\"ל), ותפלה היא עבודה שבלב<sup data-n=\"1911\">3</sup>. ומוסיף בהמאמר, דבעבודה שבלב שני ענינים. בתוך הלב ועם הלב. ויש לומר, דשני ענינים אלה הם בהתאם לשני הפירושים (דלעיל) בבקשו פני. דהבקשה ותחינה שבתפלה באה ע\"י העבודה בתוך הלב, שבכדי שהבקשה והתחינה שלו תהי' באמת, הוא ע\"י שמעורר את לבו, עבודה בהלב עצמו. והחיפוש שבתפלה (איך לתקן כל עניניו) הוא עבודה עם הלב. היינו, שהעבודה היא (לא בהלב, אלא) בכל עניניו, אלא שעבודה זו היא ע\"י הלב<sup data-n=\"1912\">4</sup>.\nב) <b>ולבאר</b> זה, מקדים בהמאמר מ\"ש<sup data-n=\"1913\">5</sup> ומבשרי אחזה אלוקה, דצריך להבין הרי העיקר הוא הנפש ולמה אומר <b>ומבשרי</b> אחזה. ומבאר, דבראי' ישנם שני אופנים, ראי' שכלית וראי' מוחשית. דראי' שכלית מתייחסת יותר אל הנפש, וראי' מוחשית מתייחסת יותר אל הגוף.וחילוק זה הוא גם בנוגע להדבר הנראה. דבכל דבר יש גוף ונפש. שגם בדברים גשמיים יש הנפש שבהם<sup data-n=\"1914\">6</sup>, וגם בדברים רוחניים יש הגוף שבהם. ולכן אומר <b>ומבשרי</b> אחזה אלוקה, כי הכוונה באחזה אלוקה היא לראי' מוחשית באלקות, דישנם עניני אלקות, כמו השגחה פרטית, שאפשר לראותם במוחש. וממשיך בהמאמר<sup data-n=\"1915\">7</sup> בפירוש הכתוב ומבשרי אחזה אלוקה, דכחות נפש האדם משתלשלות מהספירות שלמעלה<sup data-n=\"1916\">8</sup> כמ\"ש<sup data-n=\"1917\">9</sup> נעשה אדם בצלמנו כדמותנו, ולכן, מכחות נפש האדם אפשר להבין הספירות שלמעלה.\n<b>וממשיך</b> בהמאמר<sup data-n=\"1918\">10</sup> (לאחרי שמבאר באריכות הענין דמבשרי אחזה אלוקה), שבכדי שתהי' התעוררות המדות שבלב, צריכה להיות הכנה לזה. דהגם שהתעוררות המדות שבלב היא ע\"י התבוננות, מ\"מ, בכדי שאור המוחין יאיר בלבו לעורר את המדות, צריך להיות הכנה לזה גם מצד הלב. וההכנה לזה היא המרירות שקודם התפלה. דע\"י שמתבונן בתכלית ירידת נשמתו למטה שהיא ירידה צורך עלי', שע\"י עבודתה בתומ\"צ תתעלה למדריגה נעלית יותר מכמו שהיתה קודם ירידתה, ואיך שהוא מתנהג בפועל, דלא זו בלבד שאינו עוסק בתומ\"צ כדבעי (שלכן העלי' דהנשמה שע\"י הירידה אינה בשלימות), הנה ע\"י מעשיו הבלתי רצויים הוא מוריד את נשמתו למטה עוד יותר, ובפרט כשמתבונן בהמשל דהאוחז ראשו של מלך כו'<sup data-n=\"1919\">11</sup>, יבוא למרירות גדולה. וע\"י מרירות זו נעשה החרישה בקרקע לבבו, שנעשה מוכן להתעוררות (ע\"י התבוננות) אמיתית במדות שבלב.\n<b>וממשיך</b> בהמאמר<sup data-n=\"1918\">10</sup>, דכ\"ז הוא גם בכל ימות השנה, ובפרט בחודש אלול שהוא זמן התגלות י\"ג מדות הרחמים<sup data-n=\"1920\">12</sup>, והגילוי די\"ג מדות הרחמים דחודש אלול הוא לכל, גם להרחוקים ביותר. וכהמשלדמלך בשדה<sup data-n=\"1921\">13</sup> שאז רשאים ויכולים<sup data-n=\"1922\">14</sup> כל מי שרוצה להקביל פניו (ולמסור לו את בקשותיהם), והוא מקבל את כולם בסבר פנים יפות ומראה פנים שוחקות לכולם. [ויש להוסיף, דהגם שהביאור (בהמאמר) בהמעלה דחודש אלול בא בהמשך לענין המרירות, דכיון שבאלול הוא הגילוי די\"ג מדות הרחמים גם להרחוקים לכן הוא זמן מסוגל ביותר לעשות חרישה בקרקע לבבו ע\"י המרירות, הגילוי די\"ג מדות הרחמים שבאלול צריך להוסיף גם בענין השמחה. דמכיון שבאלול מראה המלך פנים שוחקות לכולם, ה\"ז צריך לעורר (כמים הפנים לפנים<sup data-n=\"1923\">15</sup>) תוספות שמחה בעבודת המלך]. ומסיים בהמאמר, דהפירוש לך אמר לבי בשבילך ובשליחותך, הוא, שהלב הוא בשבילו ית' להשלים רצונו ית' לעשות את המטה דירה לו ית', והפירוש לך אמר לבי במקומך הוא ענין נקודת היהדות שישנה בכאו\"א מישראל שמקושרת בהעצמות.\nג) <b>ולהבין</b> הביאור בשני הפירושים בלך אמר לבי, והשייכות שלהם להענינים המבוארים בהמאמר [הענין דמבשרי אחזה אלוקה, ושבכדי שתהי' התעוררות מדות שבלב צריכה להיות הכנה לזה, וכו'] יש להקדים מ\"ש הרב המגיד<sup data-n=\"1924\">16</sup> בשם הבעש\"ט שבכל תיבה<sup data-n=\"1925\">17</sup> מתיבות התפלה ישנם ג' בחינות, עולמות נשמות ואלקות. ועפ\"ז יש לומר גם בנוגע לבקשו פני, שהעבודה דבקשו פני היא בתפלה, שהיא בג' בחינות אלו. דבתיבת פני (שבפסוק זה), ג' פירושים. דלפירוש רש\"י בלך אמר לבי, שהלב אומר בשליחותו או במקומו של הקב\"ה, פני קאי על פניו ית', פנימיות דאלקות. ואדמו\"ר הזקן מפרש<sup data-n=\"1926\">18</sup>, דזה שהלב אומר בקשו פני קאי על הפנימיות שלו, פנימיות הלב, הפנימיות דנשמות. ועוד פירוש בבקשו פני<sup data-n=\"1927\">19</sup>, שפני קאי על אצילות, כי ד' המדריגות פנים ואחור ימין ושמאל הםד' העולמות אבי\"ע [אחור – עשי', שמאל – יצירה, ימין – בריאה, ופנים – אצילות], פנימיות העולמות.\nד) <b>והנה</b> בהענין דפני, בכל אחת מג' בחינות אלה, יש ב' מדריגות, בכללות. פנימיות שיש לה שייכות להחיצוניות, ופנימיות ממש שמובדלת מהחיצוניות. דבענין העולמות הוא אצילות ולמעלה מאצילות. וכמ\"ש הצ\"צ<sup data-n=\"1928\">20</sup> בפירוש הכתוב בקשו פני את פניך הוי' אבקש, דבקשו פני הוא להמשיך החכמה, אצילות, ואת פניך הוי' אבקש הוא להמשיך הפנים של הוי', האורות דאריך ועתיק. דהחילוק בין אצילות ולמעלה מאצילות הוא, דאצילות הוא בכלל ד' העולמות אלא שהוא ה\"פנים\" שלהם, פנימיות ששייך לחיצוניות, ולמעלה מאצילות הוא למעלה מעולמות, פנימיות שמובדל מחיצוניות. ועד\"ז הוא בפנימיות הלב, פנים דהנשמות, שיש בו דוגמת ב' מדריגות אלה. וכמבואר בלקו\"ת ד\"ה כי תצא למלחמה על אויביך<sup data-n=\"1929\">21</sup>, דבפנימיות הלב יש שתי מדריגות, הארת נקודת הלב ועצמות נקודת הלב, דשתי המדריגות הם מאצילות [דזהו החילוק שבין חיצוניות הלב לפנימיות הלב, שחיצוניות הלב הוא מבי\"ע ופנימיות הלב הוא מאצילות. וזהו מה שחיצוניות הלב הוא ע\"פ טעם ודעת ופנימיות הלב הוא למעלה מטעם ודעת, כי בבריאה הוא ענין ההשגה, אימא מקננא בכורסיא<sup data-n=\"1930\">22</sup>, ואצילות בכלל הוא חכמה, דאמיתית ענין החכמה הוא למעלה מהשכל], אלא שהארת נקודת הלב היא מאצילות שבפנימיות בי\"ע ועצמות נקודת הלב היא מאצילות עצמו. וכמו שלמעלה, בחינת האצילות שבבי\"ע היא רק הארת האצילות, עד\"ז הוא בנשמת האדם, שבחינה זו היא רק <b>הארת</b> נקודת הלב. ונמצא, שהארת נקודת הלב הוא מה שמאיר מפנימיות הלב לחיצוניות הלב (ע\"ד הארת האצילות בבי\"ע), ועצמות נקודת הלב הוא הפנימיות כמו שהוא במקומו.\n<b>ועד\"ז</b> הוא גם בהפנימיות דאלקות, שיש בו דוגמת ב' מדריגות הנ\"ל. ויובן זה ע\"פ מ\"ש בתניא<sup data-n=\"1931\">23</sup> בענין ב' השמות הוי' ואלקים, דאלקים הוא חיצוניות והוי' הוא פנימיות. [ויש לקשר זה עם המבוארבלקו\"ת שם<sup data-n=\"1932\">24</sup>, דהאהבה שבחיצוניות הלב באה ע\"י ההתבוננות באור הממלא, והאהבה (רעו\"ד שלמעלה מטו\"ד) שבפנימיות הלב נמשכת מאור הסובב, כי הוי' ואלקים הם (בד\"כ) סובב וממלא<sup data-n=\"1933\">25</sup>. ולכן, אור הממלא (אלקים), חיצוניות<sup data-n=\"1934\">26</sup>, הוא שרש להאהבה דחיצוניות הלב, ואור הסובב (הוי'), פנימיות, הוא שרש להאהבה דפנימיות הלב]. ועפ\"ז יש לומר, דפירוש פניך הוי' הוא העצם דהוי' שלמעלה מהתלבשות באלקים. דזה שהוי' (בכלל) הוא פנימיות, הוא גם לאחרי שמתלבש באלקים. ופניך הוי' הוא העצם דהוי' שלמעלה מהתלבשות באלקים.\nה) <b>ויש</b> לומר דבחינת פניך הוי', הפנימיות דהוי', הוא למעלה גם מהוי' שלמעלה מהתלבשות באלקים. [וע\"ד המבואר במקום אחר<sup data-n=\"1935\">27</sup> בפירוש הכתוב<sup data-n=\"1936\">28</sup> ואמת הוי' לעולם, דגם שם הוי' שלמעלה מהתלבשות באלקים הוא הוי' (סתם), ואמת הוי' (האמיתית דהוי') הוא עצמות אוא\"ס שלמעלה משם הוי', למעלה גם מהוי' שלמעלה מהתלבשות באלקים]. ויובן זה ע\"פ הידוע<sup data-n=\"1937\">29</sup> דהפנימיות של כל דבר הוא הדבר עצמו, וזה שהוא מקור לאיזה ענין אחר, הוא החיצוניות שלו. ועפ\"ז יש לבאר החילוק בין שתי הדרגות בהפנימיות שלמעלה (הוי' ואוא\"ס שלמעלה מהוי'), דהוי' הוא לשון מהווה<sup data-n=\"1938\">30</sup>, אלא שההתהוות שמשם הוי' היא באופן דבדרך ממילא. וכידוע<sup data-n=\"1939\">31</sup> דההתהוות שמשם אלקים היא בדרך התלבשות (בראשית ברא אלקים<sup data-n=\"1940\">32</sup>), וההתהוות משם הוי' היא באופן דבדרך ממילא (יהללו את שם הוי' כי הוא צוה ונבראו<sup data-n=\"1941\">33</sup>). ולכן, בכללות, שם הוי' הוא פנימיות, כי זה שההתהוות ממנו היא באופן דבדרך ממילא, מורה על זה שהוא מופלא מענין ההתהוות<sup data-n=\"1942\">34</sup> (ואינו מקור ממש). אבל בפרטיות, זה שמשם הוי' נעשהההתהוות, הוא מפני שהוא מקור לההתהוות<sup data-n=\"1943\">35</sup>, ולכן, עיקר ענין הפנימיות הוא בעצמות אוא\"ס שלמעלה מהוי'.\n<b>ועפ\"ז</b> יש לומר שעד\"ז הוא בשתי המדריגות דפנימיות הלב, דזה שהארת נקודת הלב אינה בבחינת פנימיות כ\"כ כהפנימיות דעצמות נקודת הלב הוא גם כמו שהיא בעצמותה, לפני שהיא מאירה בחיצוניות הלב<sup data-n=\"1944\">36</sup>. דמזה שממנה נמשך להאיר בחיצוניות הלב, מוכח, שאינה אמיתית ענין הפנימיות. ואמיתית ענין הפנימיות הוא בעצמות נקודת הלב שהיא מובדלת מחיצוניות הלב. וע\"ד שנת\"ל (סוף סעיף ד) בענין פניך הוי', שהוא למעלה גם מהוי' שלמעלה מהתלבשות באלקים.\nו) <b>ויש</b> להוסיף ביאור בהשייכות דשתי הדרגות שבפנימיות הלב (הארת נקודת הלב ועצמות נקודת הלב) לשתי הדרגות בהפנימיות שלמעלה (הוי' ואוא\"ס שלמעלה מהוי'), ע\"פ המבואר בלקו\"ת שם בפירוש הכתוב<sup data-n=\"1945\">37</sup> כי תצא למלחמה על אויביך, דכי תצא למלחמה קאי על מלחמת נפש האלקית עם נפש הבהמית<sup data-n=\"1946\">38</sup>, דמלחמה זו היא בכחות הנשמה המלובשים בגוף (שכל ומדות), משא\"כ פנימיות הלב (הארת נקודת הלב) הוא על אויביך, למעלה מאויביך, שאין להאויב שליטה ואחיזה שם. וע\"י הגילוי דהארת נקודת הלב, על אויביך, עי\"ז ושבית שביו<sup data-n=\"1945\">37</sup>, שנהפך הרע לטוב. אלא שהפיכת הרע לטוב שע\"י גילוי הארת נקודת הלב הוא רק בהלבושים מחשבה דיבור ומעשה, ובכדי להפוך המדות מרע לטוב הואע\"י גילוי עצמות נקודת הלב<sup data-n=\"1947\">39</sup>. וזהו וראית בשבי' אשת יפת תואר<sup data-n=\"1948\">40</sup>, אשת יפת תואר היא הנשמה המלובשת בגוף, ובכדי להוציא אותה [את עצמותה ומהותה, היינו השכל והמדות שלה] מהשבי', הוא ע\"י גילוי עצמות נקודת הלב<sup data-n=\"1949\">41</sup>.\n<b>ויש</b> לומר, דזה שבנוגע להפיכת הלבושים (שע\"י גילוי הארת נקודת הלב) כתיב <b>ושבית</b> שביו, ובנוגע להפיכת המדות (שע\"י גילוי עצמות נקודת הלב) כתיב <b>וראית</b> בשבי' וגו', הוא, כי לגבי הארת נקודת הלב ישנו מנגד. וזהו שבנוגע לדרגא זו כתיב על אויביך, כי לגבי הארת נקודת הלב ישנו מציאות האויב, אלא שהוא באופן דעל אויביך, למעלה מאויביך, שאין להאויב שליטה ואחיזה. ולכן, הוצאת הענינים דקדושה (מחשבה דיבור ומעשה דהנשמה) מהשבי', שע\"י גילוי הארת נקודת הלב, היא באופן של פעולה, <b>ושבית</b> שביו [אלא שהפעולה אינה באופן דמלחמה, כי לגבי דרגא זו אין להאויב שליטה]. משא\"כ עצמות נקודת הלב הוא [ע\"ד] בחינת היחידה<sup data-n=\"1950\">42</sup> שאין כנגדה לעומת זה, בבואה דבבואה לית להו<sup data-n=\"1951\">43</sup>. ולכן הביטול דלעו\"ז שע\"י גילוי עצמות נקודת הלב הוא (לא שע\"י גילוי עצמות נקודת הלב <b>נעשה</b> ביטול הלעו\"ז, כי אם) שע\"י גילוי זה, אין מקום מלכתחילה להמציאות דלעו\"ז<sup data-n=\"1952\">44</sup>. וזהו <b>וראית</b> בשבי' אשת יפת תואר, דכאשר ישנו הגילוי דעצמות נקודת הלב, אזי הדרגא דהנשמה (אשת יפת תואר) שהיתה תחלה בשבי', מתגלית מעצמה, <b>וראית</b> (ואין צריך <b>להוציא</b> אותה מהשבי').\n<b>ועד\"ז</b> הוא למעלה, דבשם אלקים אפשר להיות (ע\"י ריבוי צמצומים) יניקה לחיצונים, ועד לאלקים אחרים<sup data-n=\"1953\">45</sup>. וע\"פ המבואר בכ\"מ<sup data-n=\"1954\">46</sup> דשם אלקים הוא לא רק המגן ונרתק שמעלים ומסתיר על האור דשם הוי', אלא שגם האור דשם הוי' כמו שנמשך ומתצמצם ע\"י שם אלקיםלהיות מקור לנבראים, שבכללות הוא אור הממלא, נקרא אלקים, יש לומר שעד\"ז הוא באור הממלא. דמכיון שההתהוות משם אלקים (אור הממלא) היא בדרך התלבשות, הנבראים שמתהווים ממנו הם תופסים מקום, והביטול שלהם הוא רק ביטול היש<sup data-n=\"1955\">47</sup>, ולכן אפשר להשתלשל מזה ישות ממש<sup data-n=\"1956\">48</sup>, ועד להישות דע\"ז (אלקים אחרים). ובכדי שלא יהי' נתינת מקום לישות ולעו\"ז, הוא דוקא ע\"י הגילוי דשם הוי' (אור הסובב), שההתהוות ממנו היא באופן דבדרך ממילא, והנבראים אינם תופסים מקום לגבי', ביטול במציאות<sup data-n=\"1955\">47</sup>. וע\"פ המבואר לעיל (סעיף ה) שגם שם הוי' הוא מקור להתהוות, בהכרח שגם לגבי שם הוי' יש איזה תפיסת מקום להנבראים<sup data-n=\"1957\">49</sup>, ואמיתית הביטול הוא דוקא לגבי עצמות אוא\"ס שלמעלה מהוי' שאינו בגדר מקור לעולמות. ועפ\"ז יש לומר שבכדי לשלול <b>בתכלית</b> שלא תהי' נתינת מקום לישות, הוא דוקא ע\"י הגילוי דעצמות אוא\"ס שלמעלה מהוי'. וזהו מ\"ש<sup data-n=\"1958\">50</sup> לא יהי' לך אלקים אחרים על פני, שבכדי שלא יהי' שום נתינת מקום לאלקים אחרים הוא ע\"י על פני, דאמיתית הענין דפני הוא עצמות אוא\"ס שלמעלה מהוי'.\nז) <b>ויש</b> לומר, דשני הפירושים בלך אמר לבי בקשו פני (שלך הוא בשבילך ובשליחותך, ושלך הוא במקומך), וגם שני הפירושים (בהמאמר) בבקשו (בקשה ותחינה, בקשה וחיפוש), הם בהתאם לשתי הדרגות בפני. דבהפנימיות דשם הוי' (שהוא בחי' פנימיות לגבי שם אלקים), שדוגמתו באדם הוא הארת נקודת הלב, פירוש לך הוא בשבילך ובשליחותך. היינו שהלב הוא שלוחו של הקב\"ה, דענינו של שליח הואששולחים אותו <b>לעשות</b> איזה דבר. והשליחות שבדרגא זו שבפנימיות הלב הוא להאיר בחיצוניות הלב כדי לנצח המלחמה עם הנפש הבהמית, דעיקר הנצחון (שע\"י גילוי דרגא זו) הוא בהלבושים מחשבה דיבור ומעשה, אלא שבכדי שהמחשבה דיבור ומעשה יהיו בשלימות הוא ע\"י המדות שבלב<sup data-n=\"1959\">51</sup>, עבודה <b>עם</b> הלב. ועפ\"ז פירוש בקשו פני הוא בקשה וחיפוש, לחפש בכל עניניו שיהיו בהתאם לבחי' פני (פני הוי'). ובהפנימיות דאוא\"ס שלמעלה מהוי', שדוגמתו באדם היא עצמות נקודת הלב, פירוש לך הוא במקומך, וכמובא לעיל (סוף סעיף ב) מהמאמר שהוא נקודת היהדות שבכל אחד מישראל שמקושרת בהעצמות (במקומך). דבדרגא זו אין שייך ענין השליחות, כי נקודת היהדות אינה אמצעי לענין אחר (מילוי השליחות), והתכלית הוא בה עצמה<sup data-n=\"1960\">52</sup>. והעבודה בנוגע לדרגא זו היא – עבודה בהלב עצמו, שיהי' בגילוי. דפנימיות הלב כמו שהוא מצד עצמו הוא בהעלם<sup data-n=\"1961\">53</sup>, והעבודה בו היא לעורר אותו שיהי' בגילוי. ועפ\"ז פירוש בקשו פני הוא בקשה ותחינה, דבקשה ותחינה היא (כהלשון בהמאמר) בהתעוררות גדולה.\nח) <b>והנה</b> מבואר במק\"א<sup data-n=\"1962\">54</sup>, שבהעלי' דהנשמה שע\"י ירידתה למטה, שני ענינים. שע\"י שגם בהיותה מלובשת בגוף ונה\"ב היא עובדת את ה', מתגלה תוקף ההתקשרות שלה עם הקב\"ה, שגם ההעלם וההסתר דהגוף ונה\"ב אינו יכול לעשות גרעון בההתקשרות שלה. ושע\"י עבודתה למטה נעשה ענין חדש, הבירור והזיכוך דהגוף ונה\"ב וחלקו בעולם. וכיון שענין זה (הבירור והזיכוך דהגוף וכו') הוא התחדשות (ולא גילוי ההעלם), הוא נעלה יותר מגילוי תוקף ההתקשרות דהנשמה. וע\"פ הידוע<sup data-n=\"1963\">55</sup> שבירור וזיכוך הגוף ונה\"ב (שבשביל זה ירדה הנשמה למטה<sup data-n=\"1964\">56</sup>) הוא דוקא ע\"י אהבה ויראה שבהתגלות הלב, חיצוניות הלב, יש לומר, שיש יתרון בהשליחות דהארת נקודת הלב לחיצוניות הלב, על העבודה דגילוי נקודת היהדות.ט) <b>ויש</b> לומר, דזהו שמבאר בהמאמר מ\"ש מבשרי אחזה אלוקה, מבשרי דוקא, שהכוונה בזה היא לראי' מוחשית (באלקות) שמתייחסת להגוף, כי תכלית הכוונה דירידת הנשמה למטה הוא (לא שעניני הנשמה יהיו בגילוי בהיותה מלובשת בגוף, כי אם) <b>שהגוף</b> יראה אלקות. [ולהעיר שיש עוד פירוש במבשרי אחזה אלוקה, שבהבשר עצמו רואים את האלקות שבו. וכתורת אדמו\"ר הזקן<sup data-n=\"1965\">57</sup> עה\"פ מבשרי אחזה אלוקה שצריך שייערין דעם בשר אַז מי זאָל דערזעהען געטליכקייט. דמזה שאומר שצריך שייערין דעם בשר (הסרת הדברים המכסים) מובן שעי\"ז רואים האלקות שבהבשר עצמו. וכמובן גם ממאמר אדמו\"ר (מהורש\"ב) נ\"ע<sup data-n=\"1966\">58</sup> עה\"פ מבשרי אחזה אלוקה, קוק ניט וואָס ער איז אַ גולם, דעם גולם האָט מהוה גיווען עצמות א\"ס ב\"ה, דהוא לבדו בכחו ויכלתו לברוא יש מאין ואפס המוחלט<sup data-n=\"1967\">59</sup>. ויש לומר, דזה שבהמאמר מבאר דפירוש מבשרי אחזה אלוקה הוא ראי' מוחשית, אף שראיית האלקות שבהבשר עצמו הוא לכאורה ענין נעלה יותר (ובפרט לפירוש אדמו\"ר נ\"ע שקאי על כח העצמות שבהגוף), הוא, כי ראיית האלקות שבהבשר (כח העצמות שבו) היא ראי' שכלית שמתייחסת להנפש, ותכלית הכוונה דירידת הנשמה למטה הוא <b>שהגוף</b> יראה אלקות].\nיו\"ד) <b>והנה</b> ידוע<sup data-n=\"1968\">60</sup>, דכמו שירידת הנשמה למטה היא לצורך עלי', כמו\"כ הוא גם בנוגע לירידת האור האלקי להוות ולהחיות את הנבראים, שהיא ירידה צורך עלי'. ועפ\"ז יש לומר, שע\"י ששם הוי' יורד ומתלבש בשם אלקים (בכדי להוות ולהחיות את הנבראים), נעשה עלי' בהאור, למעלה יותר גם מכמו שהוא בשרשו באוא\"ס שלמעלה מהוי'<sup data-n=\"1969\">61</sup>. והעלי' היא, שנעשה<sup data-n=\"1970\">62</sup> בו ענין חדש<sup data-n=\"1971\">63</sup> – גילוי אלקות בעוה\"ז הגשמי. וכמובא לעיל (סעיף ב) מהמאמר, דישנם עניני אלקות, כמו השגחה פרטית, שהם בגילוי ממש, עד שאפשר לראותם במוחש. ויש לומר, דזהו מ\"ש בהמאמר דזה שראי' מוחשית מתייחסת להגוף הוא הן בנוגע להאדם הרואה והן בנוגע להדבר הנראה, שהיתרון בהפנימיות השייכת לחיצוניותוירידתה בחיצוניות הוא הן בנוגע להאדם, <b>שהגוף</b> רואה אלקות (כנ\"ל סעיף ט), והן בנוגע להאור שלמעלה, שהגילוי שלו הוא בעוה\"ז הגשמי.\nיא) <b>והנה</b> עד\"ז הוא בעבודת האדם, שעל ידי ירידת המוחין [העליון שבאדם<sup data-n=\"1972\">64</sup>, דטבע המוחין הוא עלי' למעלה] בהמדות [התחתון שבאדם<sup data-n=\"1972\">64</sup>, דטבע המדות הוא ירידה למטה], נעשה עלי' בהמוחין. ועיקר העלי' הוא לא זה שאור השכל מאיר גם בלב, אלא שעי\"ז נעשה ענין חדש – התעוררות <b>המדות</b>. ויש לומר, שזהו הטעם על זה שבכדי שתהי' התעוררות המדות שבלב צריכה להיות הכנה גם מצד הלב, כי <b>עיקר</b> החידוש שבהתעוררות המדות הוא כשההתעוררות היא (גם) מצד ענין המדות.\n<b>ויש</b> לומר, שעד\"ז הוא בנוגע למלך בשדה (אלול), דהגם שזוהי ירידה לגבי כמו שהוא בהיכל מלכותו (ר\"ה ויוהכ\"פ), דבהיותו בהיכל מלכותו הוא בכתר מלכות ולבושי מלכות משא\"כ בהיותו בשדה, הנה עי\"ז נעשה עלי' כביכול בהמלך<sup data-n=\"1973\">65</sup>, כי ע\"י ירידתו לשדה נעשה ענין חדש, שגם הרחוקים ביותר באים להקביל את פניו. אלא שאעפ\"כ, מכיון שבענין הגילויים, זה שנמצא בשדה הוא ירידה לגבי כמו שהוא בהיכל מלכותו, צריכה להיות העבודה בשדה באופן דללכת (אח\"כ) אחרי המלך להיכל מלכותו<sup data-n=\"1974\">66</sup>, וכמ\"ש בהמאמר<sup data-n=\"1975\">67</sup> שהעבודה דאלול היא הקדמה להעבודה דר\"ה ויוהכ\"פ. וזהו גם הקשר דשני הפירושים<sup data-n=\"1976\">68</sup> בלך אמר לבי בקשו פני, שהעבודה דלך אמר לבי להפירוש שלך הוא בשבילך בשליחותך, להשלים רצונו ית' לעשות את המטה דירה לו ית', צריכה להיות באופן שעי\"ז יגיעו להפירוש שלך הוא במקומך, גילוי נקודת היהדות שמקושרת בהעצמות.\nיב) <b>וממשיך</b> בהמאמר (בסיום וחותם המאמר), שע\"י התעוררות נקודת הלב נעשה כלי טהורה לקבל השפע ברכה על כל השנה. ויש לומר, שבזה ישנם ב' המעלות, המעלה דלך בשליחותך והמעלה דלך במקומך. דכאשר המשכת השפע הוא ע\"פ סדר ההשתלשלות, מעייניםבדינו אם הוא ראוי לזה, וישנם מקטריגים שמקטרגים ואומרים שאינו ראוי לזה. ויש לומר, דענין זה הוא גם כשההמשכה היא משם הוי' (כיון שגם שם הוי' הוא מקור להתהוות, כנ\"ל סעיף ה), כמ\"ש<sup data-n=\"1977\">69</sup> ויבואו בני האלקים להתייצב על הוי'. וזה שנמשך שפע ברכה (בריבוי מופלג) הוא לפי שע\"י גילוי עצמות נקודת הלב ההמשכה היא מאוא\"ס שלמעלה מהוי', ואין שייך שם הקטרוג דבני האלקים (וכנ\"ל סוף סעיף ו בפירוש הכתוב לא יהי' לך אלקים אחרים על פני), ויתירה מזו, שאין שם גם המדידות וההגבלות דשם אלקים (דקדושה), ולכן השפע שנמשך משם הוא בריבוי מופלג. וזה שהמשכת השפע הוא בענינים גשמיים, ומכש\"כ זה שהמשכת השפע הוא לא רק מצד למעלה אלא (כנ\"ל מהמאמר) שהאדם נעשה כלי מתאימה לקבל השפע, הוא לפי שע\"י העבודה בהארת נקודת הלב וחיצוניות הלב לעשות את <b>המטה</b> דירה לו ית', נרגש מעלת הגשמיות (כנ\"ל סעיף י בענין <b>מבשרי</b> אחזה אלוקה) ומעלתן של ישראל העושים את הדירה.\n<b>ומכיון</b> שבהעבודה דאלול ישנם שני הענינים, שהעבודה (עצמה) היא בשדה ובאופן דללכת אחרי המלך להיכל מלכותו (כנ\"ל סעיף יא), לכן, גם בהמשכת השפע שני הענינים, שנמשך רב טוב (במלופם<sup data-n=\"1978\">70</sup>) שלמעלה ממדידה והגבלה, וזה בא בטוב הנראה והנגלה (גם) בענינים הגשמיים, לשנה טובה ומתוקה, בבני חיי ומזוני כפשוטם, ובכולם – רויחי.\n**********<b>בס\"ד. ערב ראש השנה, ה'תשכ\"א</b>.\nבלתי מוגה\n[לאחרי קבלת הפ\"נ כללי – אמר כ\"ק אדמו\"ר שליט\"א:]\nיתן השי\"ת התעוררות תשובה אמיתית – תשובה עילאה, שהיא עבודה בשמחה<sup data-n=\"1979\">1</sup>,\nובאופן ד\"בקשו פני\"<sup data-n=\"1980\">2</sup> – פנימיות הנפש, שמעורר וממשיך \"את פניך הוי' (אבקש)\"<sup data-n=\"1980\">2</sup>, עצמות א\"ס.\nוכאמור, שענין זה צריך להיות בשמחה וטוב לבב, שעי\"ז נעשית גם ההמשכה למטה מטה בעניני העולם, בכתיבה וחתימה טובה לשנה טובה ומתוקה באמת ובאמיתיות, ברוחניות ובגשמיות, עד לבני חיי ומזוני רויחי.\nכתיבה וחתימה טובה לשנה טובה ומתוקה.\n**********",[["1908","*","המאמר הוגה ע\"י כ\"ק אדמו\"ר שליט\"א ויצא לאור בקונטרס ג' דסליחות* – תשמ\"ט."],["1909","1","תהלים כז, ח. – והוא פסוק במזמור \"לדוד ה' אורי וישעי\" שנוהגים לומר מר\"ח אלול עד הושענא רבה – סידור אדה\"ז אחר שיר של יום. ועוד. – נסמנו בתו\"מ סה\"מ תשרי ע' רלה הערה 94. ובמאמרי אדהאמ\"צ דברים ח\"ב ע' תקו: שאו' לדוד ה' אורי . . והעיקר הוא בפסוק לך אמר לבי בקשו פני כו'."],["1910","2","דליל ג' לפני ערב ר\"ה ה'תש\"א – נדפס בסה\"מ ה'ש\"ת ע' 163 ואילך. ה'שי\"ת ע' 281 ואילך (ושם הכותרת: ג' דסליחות)."],["1911","3","תענית ב, א. רמב\"ם הל' תפלה בתחלתו. רבינו יונה לאבות פ\"א מ\"ב."],["1912","4","ראה סה\"מ תרפ\"ח ע' קד, דפירוש עבודה <b>עם</b> הלב הוא כי התפלה צריכה גם לפעול בכל היום במחשבה דיבור ומעשה, וזהו <b>ע\"י</b> הלב."],["1913","5","איוב יט, כו.\n*) <b>ראה סה\"מ ה'תש\"ה ע' 266</b>."],["1914","6","שעהיוה\"א פ\"א, מהאריז\"ל. וראה ע\"ח שער לט (שער מ\"ן ומ\"ד) פ\"ג. שער נ (שער קיצור אבי\"ע)."],["1915","7","פ\"ב."],["1916","8","ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא רפ\"ג</a>."],["1917","9","בראשית א, כו."],["1918","10","פ\"ד."],["1919","11","<a class=\"ft-cite\" href=\"#/read/tanya/3401310029\" data-slug=\"tanya\" data-id=\"3401310029\">תניא ספכ\"ד</a>."],["1920","12","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380844\" data-slug=\"likkutei-torah\" data-id=\"4001380844\">לקו\"ת</a> פ' ראה ד\"ה אני לדודי הא' ס\"א (לב, א). וראה מאמרי אדהאמ\"צ דברים ח\"ב ס\"ע תכב ואילך, ובהנסמן שם בהערה ד\"ה הנזכר בספרי הקבלה."],["1921","13","לקו\"ת שם (לב, ב)."],["1922","14","בלקו\"ת שם \"רשאין\". ובהמאמר מוסיף \"רשאים ויכולים\"."],["1923","15","משלי כז, יט."],["1924","16","או\"ת להה\"מ (הוצאת קה\"ת) ז, ב (בהוצאת קה\"ת ה'תש\"מ ואילך – סי' יח). ועיין ג\"כ שם ז, סע\"א (סי' יז). הובא ג\"כ בצוואת הריב\"ש (הוצאת קה\"ת) סי' עה (יב, א-ב). הובא ונתבאר ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560295\" data-slug=\"or-hatorah-hb\" data-id=\"8316560295\">אוה\"ת נח כרך ג תריד, א</a>. וראה ג\"כ אגה\"ק המפורסמת דהבעש\"ט שנדפסה בריש ספר כתר שם טוב. ועיין ג\"כ בהנעתק בס' בעש\"ט עה\"ת ח\"א פ' נח עמוד התפלה בהערה לאות טו."],["1925","17","כ\"ה באוה\"ת שם. ובאו\"ת וצוואת הריב\"ש שם \"בכל אות\"."],["1926","18","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380896\" data-slug=\"likkutei-torah\" data-id=\"4001380896\">לקו\"ת נצבים מד, ב</a> ואילך. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380862\" data-slug=\"likkutei-torah\" data-id=\"4001380862\">לקו\"ת תצא</a> (המובא לקמן בפנים) לו, ב. וראה מאמרי אדהאמ\"צ דברים ח\"ב ע' תפט. שם ע' תצב. תקז."],["1927","19","אוה\"ת לתהלים (יהל אור) עה\"פ (כז, ח) אות א' (ע' קד), ע\"פ רמ\"ז לזח\"ג צג, ב."],["1928","20","אוה\"ת שם."],["1929","21","תצא לו, א. וראה ג\"כ מאמרי אדהאמ\"צ שם."],["1930","22","<a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תיקו\"ז ת\"ו (כג, א</a>). עץ חיים שער מז (שער סדר אבי\"ע) פ\"ג. שער מב (שער דרושי (כללות) אבי\"ע) פי\"ג. תניא פל\"ט (נב, א)."],["1931","23","אגה\"ת פ\"ד (צד, א)."],["1932","24","לה, ד."],["1933","25","ראה לקמן הערה 46."],["1934","26","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380897\" data-slug=\"likkutei-torah\" data-id=\"4001380897\">לקו\"ת נצבים מד, ג</a>, שההתבוננות בגדולתו ית' שממנה באה האהבה דחיצוניות הלב היא בבחי' \"<b>אחרי</b> הוי'\"."],["1935","27","המשך תרס\"ו ע' רכד."],["1936","28","תהלים קיז, ב."],["1937","29","ראה סה\"מ עת\"ר ע' ו ואילך. ולהעיר גם מאגה\"ק סי\"ט (קכח, א) \"אחוריים שבספירות הן מדריגות החיצונות כו' שיוכלו לירד ולהתפשט למטה\"."],["1938","30","שעהיוה\"א רפ\"ד. וראה גם זח\"ג רנז, סע\"ב (ברע\"מ). פרדס שער א (שער עשר ולא תשע) פ\"ט."],["1939","31","המשך תרס\"ו שם. סה\"מ תרע\"ח ע' שפ. קונטרסים ח\"א קצג, ב ואילך."],["1940","32","בראשית א, א."],["1941","33","תהלים קמח, ה."],["1942","34","סה\"מ קונטרסים שם קצד, רע\"א. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381187\" data-slug=\"likkutei-torah\" data-id=\"4001381187\">לקו\"ת שה\"ש יד, ג</a>: צוה ונבראו ממילא, שאין להם ערך ויחוס כלל אליו ית'."],["1943","35","המשך תרס\"ו שבהערה 27. ולהעיר ממ\"ש \"אתה הוא עד שלא נברא העולם ואתה הוא משנברא העולם\", דלכאורה, מכיון שבמאמר זה עצמו הלשון הוא \"נברא העולם\", נברא בדרך ממילא (כמבואר בארוכה ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381161\" data-slug=\"likkutei-torah\" data-id=\"4001381161\">לקו\"ת</a> שבהערה הקודמת), מהו החידוש בזה שהבריאה אינה פועלת שינוי בו ית'*? והביאור בזה, כי גם פעולה הבאה בדרך ממילא מורה שהדבר שממנו באה הפעולה הוא בגדר מקור להפעולה (שלכן באה ממנו פעולה זו דוקא), דפעולה שבאה מ\"מקור\" (גם כשהיא באופן דבדרך ממילא) עושה שינוי (בדקות עכ\"פ) בו, ובזה <b>מחדש</b> \"אתה הוא עד שלא נברא העולם ואתה הוא משנברא העולם\" בשוה <b>ממש</b>. והטעם על זה הוא, כי הבריאה (גם הבריאה באופן דבדרך ממילא) היא רק מבחינת שמו, הארה בלבד (לקו\"ת שה\"ש ח, א. ובכ\"מ)."],["1944","36","להעיר, שבנוגע להארת נקודת הלב מבואר ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380860\" data-slug=\"likkutei-torah\" data-id=\"4001380860\">לקו\"ת (תצא לה, ד</a>) ששרשה הוא מאור הסובב, ובנוגע לעצמות נקודת הלב מבואר שם (לו, ב) ששרשה הוא בבחינת \"פניך הוי'\" שנמשך ע\"י תומ\"צ. ומזה משמע שהחילוק שבין שתי הבחינות הוא גם בעצם מהותם."],["1945","37","תצא כא, י."],["1946","38","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380859\" data-slug=\"likkutei-torah\" data-id=\"4001380859\">לקו\"ת שם לה, ג</a>.\n*) <b>ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310025\" data-slug=\"tanya\" data-id=\"3401310025\">תניא רפ\"כ (כה</b>,<b> סע\"ב</a> ואילך)</b>,<b> דפירוש </b>\"<b>אתה הוא עד שלא נברא העולם ואתה הוא משנברא העולם</b>\"<b> הוא</b>,<b> שהבריאה אינה פועלת </b>\"<b>שום שינוי </b>באחדותו<b> ית'</b>\".<b> אבל ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380212\" data-slug=\"likkutei-torah\" data-id=\"4001380212\">לקו\"ת אמור (לא</b>,<b> ג</a>)</b>,<b> שאינו </b>נתפס<b> בזה</b>.<b> וכ\"מ ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381161\" data-slug=\"likkutei-torah\" data-id=\"4001381161\">לקו\"ת שה\"ש ח</b>,<b> א</a></b>.<b> ובכ\"מ</b>.<b> וראה לקמן הערה 49</b>."],["1947","39","לקו\"ת שם לו, א."],["1948","40","תצא כא, יא."],["1949","41","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381273\" data-slug=\"likkutei-torah\" data-id=\"4001381273\">לקו\"ת שם לו, ב</a>."],["1950","42","כן משמע מהמשך הענינים ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381275\" data-slug=\"likkutei-torah\" data-id=\"4001381275\">לקו\"ת שם לו, ד</a> ואילך."],["1951","43","יבמות קכב, א. וש\"נ. לקו\"ת שם לז, ג. וראה גם שם לו, ג. מאמרי אדהאמ\"צ שם ס\"ע תקמב ואילך."],["1952","44","ראה עד\"ז ד\"ה פדה בשלום ה'תשל\"ט סוף ס\"ה (תו\"מ סה\"מ כסלו ח\"ב ע' מב)."],["1953","45","סהמ\"צ להצ\"צ מצות מילה פ\"ג (ו, ב). ובכ\"מ."],["1954","46","המשך תרס\"ו ע' רכב. ובכ\"מ. וראה גם סהמ\"צ להצ\"צ (סב, א), דהוי' הוא סובב ואלקים ממלא."],["1955","47","המשך תרס\"ו וסה\"מ תרע\"ח שבהערה 31."],["1956","48","להעיר מקונטרס עץ החיים פ\"ז, שבהעבודה דיחו\"ת, להיותה רק ביטול היש, \"בנקל הוא שיפול ממדריגתו ח\"ו ויהי' יש גמור\"."],["1957","49","ראה גם ד\"ה שובה ישראל ה'תשמ\"א (תו\"מ סה\"מ תשרי ע' קטו ואילך). ולהעיר מ<a class=\"ft-cite\" href=\"#/read/tanya/3401310025\" data-slug=\"tanya\" data-id=\"3401310025\">תניא רפ\"כ</a> (נעתק לעיל בשוה\"ג להערה 35) דפירוש \"אתה הוא עד שלא נברא העולם ואתה הוא משנברא העולם\" הוא, שהעולמות אינם פועלים שינוי <b>באחדותו</b> ית'. דמזה מוכח, שגם עולמות שנבראו באופן דבדרך ממילא (\"<b>נברא</b> העולם\") יש להם תפיסת מקום, ולכן צריך <b>לחדש</b> שהעולמות אינם פועלים שינוי באחדותו ית'.\nועפ\"ז יש לבאר זה ש\"בנוסחא הישנה הי' כתוב אתה הוא עד שלא בראת ועתה הוא הנוסחא עד שלא נברא\" (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381187\" data-slug=\"likkutei-torah\" data-id=\"4001381187\">לקו\"ת שה\"ש יד, ג</a>) – כי בדורות הראשונים הי' מקום לקס\"ד שישנה גם מציאות ממש, והי' צריך לשלול קס\"ד זה. אבל לאחרי שנתגלתה תורת הקבלה, שזה הי' גם הקדמה לגילוי תורת החסידות שבה מודגש ענין אחדותו ית' – בנוגע למציאות ממש, אין מקום לקס\"ד כזה, וזה שצריך לשלול הוא שלא ישנו אפילו \"מציאות\" שבתכלית הדקות, \"אתה הוא עד שלא <b>נברא</b> כו' אתה הוא <b>משנברא</b> כו'\"."],["1958","50","יתרו כ, ג."],["1959","51","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא רפ\"ד</a> \"ובלעדה אין להן קיום אמיתי\". ובפרט בנדו\"ד – נצחון המלחמה, דהנצחון הוא כשמקבץ עניני הנשמה שנתפזרו בהלבושים (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380861\" data-slug=\"likkutei-torah\" data-id=\"4001380861\">לקו\"ת תצא לו, א</a>), שזהו ע\"י עקירת <b>הרצון</b> (שם לז, א)."],["1960","52","ראה בארוכה לקו\"ש ח\"ג ע' 817."],["1961","53","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381151\" data-slug=\"likkutei-torah\" data-id=\"4001381151\">לקו\"ת שה\"ש ה, ג</a>-ד. וראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310024\" data-slug=\"tanya\" data-id=\"3401310024\">תניא פי\"ט (כה, א</a>)."],["1962","54","תו\"מ סה\"מ אב ע' קצ. שם ע' קמט."],["1963","55","סה\"מ עת\"ר ע' יד. ה'תש\"י ע' 32."],["1964","56","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, ב</a>)."],["1965","57","לקו\"ד כרך ב שלד, א. ספר השיחות תרצ\"ז ע' 171."],["1966","58","לקו\"ד שם שלו, א. ספר השיחות שם ע' 173."],["1967","59","אגה\"ק ס\"כ (קל, ריש ע\"ב)."],["1968","60","סה\"מ תרפ\"ה ע' קנ (וראה שם ע' קמח ואילך כמה ענינים בירידת האור)."],["1969","61","ע\"ד שנת\"ל ס\"ח בהדרגות דנשמה."],["1970","62","נוסף להעלי' שעי\"ז נשלמת הכוונה דדירה בתחתונים ע\"י עבודת האדם."],["1971","63","ראה לעיל ס\"ח."],["1972","64","להעיר מזה שארז\"ל (ב\"ר פ\"ח, יא. ועוד) שהאדם נברא מן העליונים ומן התחתונים. וראה בארוכה תו\"מ סה\"מ שבט ע' שיא."],["1973","65","ראה <b>עד\"ז</b> <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041343\" data-slug=\"likkutei-sichot\" data-id=\"1300041343\">לקו\"ש ח\"ד ע' 1344</a>."],["1974","66","ראה בארוכה לקו\"ש שם."],["1975","67","בסופו – סה\"מ ה'ש\"ת ע' 167."],["1976","68","כמו כל הפירושים שבפסוק אחד ששייכים זה לזה, כידוע הראי' לזה מ\"שעטנז\" (נדה סא, ב) – ראה לקו\"ש ח\"ג ע' 782."],["1977","69","איוב ב, א."],["1978","70","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381172\" data-slug=\"likkutei-torah\" data-id=\"4001381172\">לקו\"ת שה\"ש י, ד</a>."],["1979","1","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310082\" data-slug=\"tanya\" data-id=\"3401310082\">תניא אגה\"ת פי\"א</a>."],["1980","2","תהלים כז, ח. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380896\" data-slug=\"likkutei-torah\" data-id=\"4001380896\">לקו\"ת נצבים מד, ב</a>-ג. דרושי ש\"ש סו, ג ואילך. ובכ\"מ."]]],[1400350035,"<b>לשלוח לאנ\"ש שי' בכל מרחבי תבל</b>\n<b>לקראת ראש-השנה, ה'תשכ\"א</b>\nלשנה טובה תכתבו ותחתמו.\n<b>מנחם שניאורסאהן</b>"],[1400350036,"<b>מפתח ענינים למאמרים</b>\n<b>מפתח ענינים לשיחות</b>"],[1402160002,"התוועדויות\n(יום ב' דראש השנה – ש\"פ וארא, מבה\"ח שבט)"],[1402160003,"(הנחה בלתי מוגה)\n<b>תקעו</b> בחודש שופר בכסה ליום חגנו<sup data-n=\"1\">1</sup>, ופירש\"י בכסה יום מועד קבוע לכך, וכן ליום הכסא יבוא ביתו<sup data-n=\"2\">2</sup>, למועד הקבוע<sup data-n=\"3\">3</sup>. וצריך להבין, הרי ישנם כמה לשונות המורים על זמן מיועד, ולמה נאמר בכסה דוקא. ובפרט שלשון זמן מיועד הוא כסא באל\"ף, וכאן כתיב כסה בה\"א, וכדאיתא במפרשים<sup data-n=\"4\">4</sup> שכסה בה\"א הוא כמו כסא באל\"ף. וכללות הענין בזה, דמ\"ש בכסה דוקא הוא להורות על ענין הכיסוי, וכמארז\"ל<sup data-n=\"5\">5</sup> איזהו חג שהחודש מתכסה בו, הוי אומר זה ראש השנה, וזהו בכסה, שהוא כמו בכסא (באל\"ף), כס א', שבחי' אל\"ף הוא מכוסה ונעלם. וזהו גם מ\"ש<sup data-n=\"6\">6</sup> ארץ אשר גו' עיני הוי' אלקיך בה מרשית השנה ועד אחרית שנה, מרשית חסר א'<sup data-n=\"7\">7</sup>, והיינו כמו כסא, כס א', שהא' הוא בכיסוי<sup data-n=\"8\">8</sup>. ועל זה היא העבודה דר\"ה להמשיך אור חדש, שזהו ענינו של ראש השנה, שכשמו כן הוא, כמבואר בעטרת ראש<sup data-n=\"9\">9</sup> שכשם שהראש שבאדם כולל את החיות של כל אברי הגוף, ואח\"כ נמשך ממנו החיות לכל אבר ואבר בפרט, כמו\"כ בראש השנה נכלל חיות כל ימי השנה, ואח\"כ נמשך ממנו חיות פרטי לכל יום ויום (החל מר\"ה עצמו), והחיות שנמשך בר\"ה על כל השנה הוא אור חדש שלא הי' מאיר עדיין מימי עולם, כמבואר באגה\"ק<sup data-n=\"10\">10</sup>. ועז\"נ מרשית גו' ועד אחרית גו', כפירוש רז\"ל<sup data-n=\"11\">11</sup> כל שנה שרשה בתחילתה (שישראל עושין עצמן רשין בר\"ה לדבר תחנונים ותפלה) מתעשרת בסופה, שנאמר מראשית השנה, מרשית כתיב, ועד אחרית, סופה שיש לה אחרית, והיינו<sup data-n=\"12\">12</sup> שכאשר היא רשה בתחילתה הנה עי\"ז גופא היא מתעשרת בסופה.וכפירוש הבעש\"ט (ששמענו כמ\"פ מרבינו נשיאינו כ\"ק מו\"ח אדמו\"ר<sup data-n=\"13\">13</sup>) ע\"פ<sup data-n=\"14\">14</sup> והי' ראשיתך מצער ואחריתך ישגה מאד, שעי\"ז שראשיתך מצער אזי אחריתך ישגה מאד, וכל שהמצער הוא יותר, הנה יותר ישגה מאד לעילא ולעילא.\nב) <b>והענין</b> בזה, דהנה, פשטות הכתוב ארץ גו' אשר עיני ה\"א בה מרשית השנה גו', קאי על ארץ ישראל. ובפנימיות הענינים הנה ארץ קאי על ספירת המלכות [וכידוע בפירוש פנימיות הענין, שאין זה ענין אחר, אלא הוא אותו הענין עצמו בפנימיותו, היינו, שפנימיות ענין הארץ הוא ספירת המלכות, שהיא ארץ העליונה, ולמטה יותר הוא בחינת ארץ החיים, ולמטה יותר הוא ארץ התחתונה שהוא עולם העשי', והיינו, לא רק בחינת המלכות דעולם העשי', אלא עולם העשי' עצמו, והוא ארץ ישראל, שהיא מכוונת כנגד ארץ העליונה ונקראת על שמה, כמ\"ש באגה\"ק<sup data-n=\"15\">15</sup>]. ועז\"נ מרשית גו' עד אחרית גו', שע\"י שהיא רשה מתחילתה אזי מתעשרת בסופה, שזהו\"ע בנין המלכות. ובפרטיות יותר, כמבואר בהגהות הצ\"צ<sup data-n=\"16\">16</sup> לתו\"א בתחילתו<sup data-n=\"17\">17</sup> בענין ארץ ארץ ארץ שמעי דבר הוי'<sup data-n=\"18\">18</sup>, שג\"פ ארץ קאי על ג' השרשים של המלכות שנקראת ארץ, כי שרש המלכות בג' מקומות, בנה\"י, בחג\"ת ובחב\"ד. והנה, יש עוד פירוש במ\"ש ארץ גו', שקאי על ישראל שנקראים בשם ארץ חפץ&lt;12&gt;, וכמו שפירש הבעש\"ט<sup data-n=\"19\">19</sup> ע\"פ<sup data-n=\"20\">20</sup> כי תהיו אתם ארץ חפץ, שכשם שבארץ ישנם אוצרות גדולים אשר ככל שיגלו אותם לא יוכלו לעולם לגלות את כולם, כמו\"כ ישנם אוצרות טובים שנמצאים בכל אחד ואחד מישראל, אלא שצריך לגלותם, וסיים הבעש\"ט, שעבודתו היא לפעול שבנ\"י יתנו את היבול שיכולה להצמיח הארץ חפץ של הקב\"ה, והיינו, לגלות את האוצרות שישנם בכל אחד מישראל, ע\"י הפצת תורת החסידות חוצה, שעי\"ז יתגלו האוצרות שבכאו\"א מישראל, גם באלו שנמצאים חוצה. ובפרטיות יותר, כמבואר בתו\"א בתחלתו, ששלשה נקראו ארץ, כנסת ישראל ותורה שבע\"פ ומצוות, וכולן נרמזין במקרא אחד, ארץ ארץ ארץ שמעי דבר הוי'. והענין בזה, שע\"י ג' בחי' ארץ הנ\"ל, דהיינו, העבודה של כנס\"י בקיום מצוותמעשיות, בחי' ארץ, כפי שנתבארו בתושבע\"פ (שהרי ההוראה על עשיית המצוות היא בתושבע\"פ דוקא, כי, ההוראה שבתושב\"כ היא הוראה כללית, וההוראות פרטיות הם בתושבע\"פ דוקא), אזי ממשיכים אור חדש להיות בנין המלכות (שנקראת ארץ), שהו\"ע שמעי דבר הוי'. וזהו גם מה שאמרו רז\"ל<sup data-n=\"21\">21</sup> מצות היום בשופר, שהו\"ע תקיעת שופר בעשי' בגשמיות דוקא, והיינו, שלא מספיק אמירת פסוקי מלכיות, אף שעקימת שפתיו הוי מעשה<sup data-n=\"22\">22</sup>, אלא צריך להיות מעשה ממש, בחי' ארץ, ודוקא עי\"ז פועלים בנין המלכות, שלא זו בלבד שיהי' קיום העולמות כמקודם, ושלא יהי' בזה רפיון ידים<sup data-n=\"23\">23</sup>, אלא שתהי' גם המשכת אור חדש שלמעלה מהשתלשלות.\nג) <b>וזהו</b> ג\"כ מה שאמרו רז\"ל<sup data-n=\"24\">24</sup> אמרו לפני מלכיות כדי שתמליכוני עליכם, דלכאורה אינו מובן<sup data-n=\"25\">25</sup>, הרי כתיב<sup data-n=\"26\">26</sup> הוי' ימלוך לעולם ועד, וכתיב<sup data-n=\"27\">27</sup> והיתה להוי' המלוכה, שמלכותו של הקב\"ה היא בתמידות, וא\"כ, מהי תוכן בקשת הקב\"ה שתמליכוני עליכם. אך הענין הוא, שהמשכת המלכות שמצד עצמו היא מבחי' כי חפץ חסד הוא<sup data-n=\"28\">28</sup>, אמנם, ע\"י העבודה דתומ\"צ ממשיכים אור חדש נעלה יותר. וזהו ג\"כ מה שאמרו רז\"ל<sup data-n=\"29\">29</sup> כל האומר ויכולו נעשה שותף להקב\"ה במע\"ב, דאף שמע\"ב ישנם בתמידות, מ\"מ, ע\"י אמירת ויכולו שהו\"ע עבודת האדם, אזי ההמשכה דמע\"ב היא נעלית יותר. וזהו ג\"כ תוכן הבקשה אמרו לפני מלכיות כו', שתהי' המשכת אור חדש מבחי' שלמעלה מהשתלשלות, שזהו אמרו לפני כו', לפני דייקא. ומסיים, ובמה בשופר, והיינו, שדוקא ע\"י המעשה דתק\"ש פועלים המשכת האור חדש שלמעלה מהשתלשלות, מבחי' לפני, ובאופן שאור זה יומשך למטה, שזהו עוד טעם על הצורך בתק\"ש בעשי' דוקא, לפי שהכוונה היא שתהי' המשכת האור חדש למטה דוקא, שעי\"ז תושלם הכוונה שנתאוה הקב\"ה להיות לו ית' דירה בתחתונים דוקא<sup data-n=\"30\">30</sup>. וזהו כללות ענין אמירת פסוקי מלכיות בר\"ה, שמביאים ראי' (שהיא גם נתינת כח) מן התורה<sup data-n=\"31\">31</sup> על ענין המלכות, שענינה הוא המשכת האור למטה דוקא.ועפ\"ז מבאר כ\"ק אדמו\"ר מהר\"ש<sup data-n=\"32\">32</sup> טעם הדיעה<sup data-n=\"33\">33</sup> שפסוק שמע ישראל<sup data-n=\"34\">34</sup> אינו בכלל פסוקי מלכיות, לפי שענין שמע ישראל גו' אחד הוא בחי' יחו\"ע<sup data-n=\"35\">35</sup>, וכיון שענין המלכות הוא המשכת האור למטה דוקא, הנה הפסוק שמע ישראל גו' אחד שהו\"ע יחו\"ע שבעולמות העליונים, אינו בכלל פסוקי מלכיות. אבל לדעת ר' יוסי, וכ\"ה ההלכה<sup data-n=\"36\">36</sup>, גם פסוק זה הוא בכלל פסוקי מלכיות, ולא עוד אלא שהוא פסוק העשירי שבו מסיימים וחותמים כל ענין המלכיות, לפי שהכוונה ביחו\"ע היא שיומשך ביחו\"ת, וכמו\"כ מלמטלמ\"ע, שהכוונה ביחו\"ת היא שיורגש בה גם היחוד דיחו\"ע, שזה נותן כח בהיחוד דיחו\"ת, כמבואר בקונטרס עץ החיים<sup data-n=\"37\">37</sup>. ויתירה מזה, שהתכלית דיחו\"ת היא שיתעלה ביחו\"ע. וזהו הטעם שפסוק שמע ישראל הוא סיום וחותם ענין המלכיות, לפי שהכוונה דבחי' אחד היא שיומשך בבחי' ועד, דאחד הוא ועד בחילופי אתוון<sup data-n=\"38\">38</sup>, והמשכה זו נעשית ע\"י ארץ חפץ דישראל דוקא, כמ\"ש בתחילת הכתוב שמע ישראל גו', והיינו, שישראל הם הפועלים היחוד דאחד שענינו הוא ג\"כ המשכת היחוד בעולמות, וכמארז\"ל<sup data-n=\"39\">39</sup> כד אמליכתי' למעלה ולמטה ולד' רוחות.\nד) <b>וביאור</b> הענין<sup data-n=\"40\">40</sup>, דהנה, כללות הענין דאחד הוא היחוד שמצד העולמות. וזהו הטעם שנאמר אחד ולא יחיד<sup data-n=\"41\">41</sup>, דלכאורה, מצד ההבנה בענין היחוד, הרי תיבת יחיד מורה על מעלת היחוד יותר מאשר תיבת אחד. אך הענין הוא, שיחיד מורה על היחוד מצד עצמו ית', ומ\"ש אחד הרי זה כדי להורות על היחוד שמצד העולמות. והענין בזה, דהנה, מצד ידיעתו ית', בחי' יחיד, הרי לא שייך מציאות עולמות כלל, וכמ\"ש בעץ חיים<sup data-n=\"42\">42</sup> שבתחילה הי' אוא\"ס ממלא מקום החלל ולא הי' מקום לעמידת העולמות, ואח\"כ הי' צמצום והסתלקות האור ונמשך קו קצר ודק כו', ומאחר שהצמצום הוא רק לגבינו, אבל לגבי' ית' הנה גם עכשיו ממלא אוא\"ס את החלל, הרי אין מקום לעמידת העולמות. ועניןהעולמות בידיעתו ית' הוא כפי שהם בבחי' עליית הרצון באוא\"ס שלפני הצמצום, שאינם בבחי' מציאות כלל וכלל. ולמעלה יותר, הרי זה כפי שהם בבחי' שם אלקים שלמעלה מעליית הרצון. דהנה, לכאורה אינו מובן, איך אפשר שתהי' עליית הרצון על עולמות, הרי הם באין ערוך לגמרי. אך הענין הוא, שזהו מצד בחי' שם אלקים שבאוא\"ס ב\"ה, שהוא מז' השמות שאינם נמחקים<sup data-n=\"43\">43</sup>, וענינו הוא התגלות פרטים, שזהו אלקים לשון רבים<sup data-n=\"44\">44</sup>, והרי ענין הפרטים הוא היפך ענין אחד ויחיד, ולכן, הנה ענין הפרטים שבשם אלקים הוא הסיבה לעליית הרצון שיהיו עולמות. וכל זה הוא בבחי' יחיד. אך בחי' אחד הוא היחוד שמצד העולמות, והיינו, שגם מצד הצמצום כפי שהוא לגבינו, שעל ידו נעשית מציאות העולמות, ישנו היחוד דבחי' אחד.\n<b>והענין</b> בזה, דהנה, האורות שאחר הצמצום שרשם מאוא\"ס שלפני הצמצום<sup data-n=\"45\">45</sup>, שהרי לאחר הצמצום חזר והאיר האוא\"ס ונמשך בחי' הקו שהוא נוגע ודבוק באוא\"ס כו', ומצד הדביקות באוא\"ס שלפני הצמצום הרי הוא בבחי' ביטול במציאות ממש. ויתירה מזה, שמצד הדביקות שבהקו נרגשת בו ידיעת הבורא שלפני הצמצום, שלגבי' הרי כל העולמות הם כמו שהיו בעלות הרצון, ולמעלה יותר בשם אלקים, ומצד זה נעשה ביטול נעלה יותר מביטול האור מצד עצמו. אך מ\"מ הרי זה עדיין בחי' אחד ולא בחי' יחיד, לפי שאינו דומה לגבי ידיעתו ית' לפני הצמצום, שאז לא היו מציאות עולמות כלל, משא\"כ אחר הצמצום, שנתהוו עולמות, אלא שהם מיוחדים לגמרי. והיינו, שכל ענין המציאות הוא בכדי שיהי' שייך היחוד דבחי' אחד, שהרי אי אפשר להיות היחוד דבחי' אחד כי אם כאשר ישנו מציאות העולם דוקא. וע\"ד דוגמא בנגלה דתורה, הנודר ואומר לכשאדור יהי' מופר, שכל חלות הנדר הוא רק בכדי שיתבטל. ועד\"ז בענין המציאות שמצד האורות, שכל ענין המציאות הוא רק בכדי שיהי' שייך ענין הביטול והיחוד דבחי' אחד.\n<b>וכמו\"כ</b> גם לאחרי שהאורות נמשכים בכלים, הנה, אף שהתהוות הכלים היא מהצמצום עצמו, היינו מהתגלות נקודת הרשימו<sup data-n=\"46\">46</sup>,כח הגבול שבא\"ס, שהוא שרש הכלים<sup data-n=\"47\">47</sup>, וגם התהוות הכלים בפועל שהיא מהאור<sup data-n=\"48\">48</sup>, הרי זה מהעביות שבאור, דמהתעבות האורות נעשו הכלים<sup data-n=\"48\">48</sup>, שלכן הכלים הם בדביקות בלתי ניכרת, מ\"מ, הרי גם הכלים הם בתכלית היחוד, שהרי גם הם בעולם האצילות שהוא מיוחד, וכמאמר<sup data-n=\"49\">49</sup> איהו וגרמוהי חד, שגם גרמוהי שהם הכלים הם בתכלית היחוד, אף שהם בבחינת מציאות. והביאור בזה, שבהכלים נרגש ששרשם הוא מכח הגבול שבא\"ס, והיינו, שמצד הא\"ס הרי לא הי' מקום לעולמות, אלא שמצד שלימות הא\"ס כחו גם בגבול, שאם לא תאמר כן, הרי אתה מחסר שלימותו<sup data-n=\"50\">50</sup>, והיינו, שיש בו גם כח הגבול, שהוא שרש הכלים. וכיון שכל מציאותם היא מצד כח הגבול שבא\"ס, הרי הם בטלים לגמרי, אלא שהביטול הוא באופן של העדר תפיסת מקום, שאינם תופסים מקום כלל לגבי הא\"ס, והיינו, שאף שישנה מציאותם מצד כח הגבול שבא\"ס, מ\"מ, אין להם תפיסת מקום כלל, וכמו חכם קטן לגבי חכם גדול, שאינו מדבר לפניו ומתבטל לפניו לגמרי (ער פאַרלירט זיך אינגאַנצן), דהגם שבעצם הוא מציאות, מ\"מ, מצד העדר תפיסת מקום הרי הוא בטל לגמרי. ובאמת יש מעלה בביטול הכלים על ביטול האורות, שהגם שבעצם הם מציאות, מ\"מ, הרי הם בטלים בתכלית. וזהו כללות הענין דאחד שהוא היחוד שמצד העולמות, שהיחוד הוא גם בבחי' המציאות. ועי\"ז נעשה ממוצע גם להיחוד דבחי' ועד, ועד הוא אחד בחילופי אתוון&lt;38&gt;, היינו, שהמשכת היחוד בבחי' המציאות, נעשה ממוצע להמשכת היחוד גם בבי\"ע, וכמאמר<sup data-n=\"51\">51</sup> כגונא דאינון מתייחדין לעילא באחד אוף הכי איהי אתייחדת לתתא ברזא דאחד, דהגם שהוא רק ברזא דאחד, מ\"מ הרי זה כגונא דילי'.\nה) <b>והנה</b> ענין האמצעות דאחד יובן גם מהאותיות דתיבת אחד, א' ח' ד'. דהנה, אות א' הוא ממוצע, וכמבואר בסידור שער התקיעות ד\"ה להבין ענין תק\"ש ע\"פ כוונת הבעש\"ט ז\"ל<sup data-n=\"52\">52</sup>, שאות א' הוא הממוצע בין קול ודיבור, שהקול הנמשך מהבל הלב הוא קול פשוט, והדיבור הוא ציור והתחלקות, שהם ב' הפכים, וצריך להיות ממוצע ביניהם, שהממוצע כלול מהעליון והתחתון. וע\"ד רב ותלמיד שאינם בערך זל\"ז, שצריךלהיות ממוצע ביניהם, והיינו המתורגמן שכלול משניהם. והממוצע בין קול ודיבור הוא אות א', שהרי כל הברה תחילתה היא אות א' כפי שהיא ללא המילוי. וענין אות א' למעלה הוא בחי' הכתר שהוא הממוצע בין המאציל לאצילות. ובאמת הנה הכתר אינו אמיתית ענין הממוצע<sup data-n=\"53\">53</sup>, כי, מצד בחינת עתיק שבכתר הרי הוא נעתק ונבדל מעולמות, שזהו פירוש עתיק יומין שהוא בבחי' העתקה והבדלה לגמרי. וגם לפי הפירוש שעתיק הוא מלשון העתקה ממקום למקום, וכמו אשר העתיקו אנשי חזקי'<sup data-n=\"54\">54</sup>, הרי פירושו שבכתר נמצא אותו המהות דבחי' הא\"ס שלמעלה מהכתר, שזהו למעלה מהשתלשלות, ואינו ממוצע. וגם מצד בחינת אריך שבכתר, הרי ידוע שאריך הוא דוגמת הרצון, שהוא בחי' מקיף שאינו נמשך בפנימיות, וא\"כ הוא למעלה מהשתלשלות, ואינו ממוצע. אך אמיתית ענין הממוצע הוא בחי' חכמה סתימאה, שהיא כלולה מן העליון ומן התחתון. והדוגמא לזה בנפש האדם הוא כח המשכיל<sup data-n=\"55\">55</sup>, דהנה, כח המשכיל הוא מושלל מכל מיני מציאות שבשכל, שהרי הוא כח היולי על שכל, ואם הי' בו איזה מציאות אינו היולי. אבל מ\"מ אינו מושלל מענין השכל לגמרי, שהרי הוא כללות ענין השכל, ולכן הוא היולי לשכל. ולכן הוא ממוצע שכלול מן העליון ומן התחתון, והיינו, שלהיותו מושלל ממציאות שכל, הרי הוא שייך להעליון, ולהיותו בגדר ענין השכל, הרי הוא שייך להתחתון. וזהו\"ע אות א' שקאי על ח\"ס<sup data-n=\"56\">56</sup>, דפירוש אלף הוא מלשון אאלפך חכמה<sup data-n=\"57\">57</sup>, שהוא לשון עתיד, וכידוע בענין אות א' דשם אהי' שמורה על העתיד<sup data-n=\"58\">58</sup>, והיינו, שעם היותו למעלה מחכמה הגלוי', שהרי אבא יונק ממזלא<sup data-n=\"59\">59</sup>, שהמשכת החכמה גלוי' מח\"ס היא רק הארה דהארה, שזוהי המשכה בדרך דילוג והפסק עצם הגולגולת, שהו\"ע השערות, אבל מ\"מ הרי הוא היולי לחכמה הגלוי', וזהו לשון עתיד, שעתיד להיות ממנו חכמה הגלוי'. ועל זה מורה ג\"כ תמונת אות א' שהוא בציור ב' קוצין וקו באמצע, שקוץ העליון מורה על שרש הח\"ס, שדוגמתו בנפש הוא כח שכל היולי העצמי שהוא מושלל מענין השכל לגמרי, והיינו, שאין זה כמו כח המשכיל שהוא מושלל רק ממציאות שכל, משא\"כ כח שכל היולי העצמי שהוא מושלל מענין השכללגמרי, אלא כיון שבנפש האדם יש כל המיני שלימות, יש בו גם השלימות דשכל, אבל עדיין אינו בגדר של שכל כלל, והמשכת כח המשכיל מכח השכל היולי העצמי הוא רק מבחי' אחרונה שבו, שזהו\"ע קוץ העליון, שהוא בחינה האחרונה ונקודה בלבד מכח היולי העצמי, וכמו ברב ותלמיד שאינם בערך זל\"ז, שהרב צריך לצמצם את כל שכלו ולמצוא בעצמו איזה נקודה שבערך התלמיד. ואח\"כ הוא הקו, שמורה על כללות ענין ההמשכה. ואח\"כ הוא קוץ התחתון, דקאי על הבחינה שבכח המשכיל שהיא שרש לשכל הגלוי. ולמטה יותר הנה בחי' אות א' קאי על חכמה הגלוי', וקוץ העליון מורה על שרש ההמשכה, שהוא מקום יניקת השערות, והקו הוא המשכת השערה, וקוץ התחתון הוא בחי' חכמה הגלוי' עם כל הספירות שבה עד לבחי' המלכות, דאבא יסד ברתא<sup data-n=\"60\">60</sup>. וזהו ענין אחד, שמהא' נמשך ע\"י הח' (כפי שיתבאר להלן<sup data-n=\"61\">61</sup>) לבחי' הד', שהיא המלכות. ובזה גופא הנה כאשר המלכות הוא באצילות עדיין הרי היחוד הוא בבחי' יחו\"ע, ואח\"כ נמשך לבחי' ועד, שיהי' היחוד גם בבי\"ע, שלכן הד' דועד אינו ד' רבתי, לפי שענינה הוא בבי\"ע, וזוהי הכוונה שתהי' המשכת האחדות גם בהמציאות דבי\"ע.\nו) <b>אמנם</b> הענין דר\"ה הוא בכסא, כס א', שהא' הוא בכיסוי (כנ\"ל), והיינו, שכללות הממוצע בין אוא\"ס לעולמות, שהתחלתו הוא מאות א', הוא בכיסוי<sup data-n=\"62\">62</sup>, ולזאת צריך לפעול המשכת אור חדש, והמשכה זו היא ע\"י תקיעת שופר, שהו\"ע המעשה דוקא כנ\"ל. ויובן&lt;8&gt; ע\"פ משל המגיד<sup data-n=\"63\">63</sup> מצפור המדברת, דהנה, לב מלכים אין חקר<sup data-n=\"64\">64</sup>, ולכן אי אפשר להגיע ולעורר את המלך ע\"י דיבור האדם או ע\"י אוצרות כו', לפי שאינם בערך אל המלך, כי אם ע\"י צפור המדברת דוקא, שלהיותה דבר חידוש, הנה עי\"ז מגיעים ומעוררים עצמות המלך. והדוגמא מזה למעלה, שבכדי להגיע לבחי' שלמעלה מהשתלשלות ולפעול שיומשך משם להיות בנין כל סדר ההשתלשלות, אי אפשר שיהי' זה ע\"י החכמה או ע\"י המדות, מאחר שהם בסדר השתלשלות, וכמו\"כ לא מספיק אמירת פסוקי מלכיות בשביל לבנות את עולם הדיבור<sup data-n=\"65\">65</sup>, אלא ההמשכה היא ע\"י המעשה דוקא, ובעבודההו\"ע הכפי' וקבלת עול, שענין זה מגיע בעצם הנשמה, ועי\"ז ממשיכים את האור חדש. וכידוע מ\"ש כ\"ק מו\"ח אדמו\"ר<sup data-n=\"66\">66</sup> בההפרש בין העבודה דר\"ה להעבודה שבכל השנה, שבר\"ה כל ענין העבודה הוא בהעצם, היינו, שהעבודה הוא בעצם הנשמה, ועי\"ז מגיעים בהעצמות שלמעלה, וכמשנת\"ל<sup data-n=\"67\">67</sup> בפירוש בקשו פני את פניך הוי' אבקש<sup data-n=\"68\">68</sup>, ועי\"ז בונים את העצם של כל ההשתלשלות שצריך לבנותו מחדש, והו\"ע המשכת התענוג והרצון בכללות סדר ההשתלשלות, שזהו\"ע בנין המלכות.\n<b>וזהו</b> תקעו בחודש שופר בכסה ליום חגנו, דהנה, בר\"ה חוזרים כל הדברים לקדמותם, הן כללות ההמשכה שבעולמות מלמעלה, והן ההמשכה שנפעלה ע\"י העבודה דנש\"י במשך כל השנה [ולהעיר, שגם אם הי' חסר בעבודה שבמשך כל השנה, הרי השלימו זאת במשך ימי חודש אלול<sup data-n=\"69\">69</sup>, ובפרט בי\"ב ימים האחרונים שמח\"י אלול עד ר\"ה<sup data-n=\"70\">70</sup>. וגם אם הי' חסר בעבודת ימים אלו, הרי ברגע האחרונה של שנה העברה, בשעתא חדא וברגעא חדא<sup data-n=\"71\">71</sup>, השלימו את העבודה של כל השנה], הנה כל ענינים אלו מסתלקים וחוזרים לקדמותם, למעלה גם מאות א' שהוא התחלת הממוצע, שזהו\"ע כס א'. ואח\"כ נעשית ההמשכה ע\"י תקיעת שופר בגשמיות ובמעשה דוקא, שעי\"ז בונים את המלכות, והיינו ע\"י המשכת התענוג בכללות ענין ההשתלשלות, וכמארז\"ל<sup data-n=\"72\">72</sup> שענין השופר הוא מלשון שפרו מעשיכם, והרי פירוש שפרו הו\"ע המשכת התענוג. אמנם בר\"ה הרי זה בכיסוי ובהעלם עדיין, וההמשכה בגילוי היא ליום חגנו, שזהו חג הסוכות<sup data-n=\"73\">73</sup>, שמיני עצרת ושמחת תורה, שאז נעשית ההמשכה בגילוי<sup data-n=\"74\">74</sup>, שנמשכת כתיבה וחתימה טובה לשנה טובה ומתוקה, בטוב הנראה והנגלה, בבני חיי ומזוני רויחי.\n**********",[["1","1","תהלים פא, ד."],["2","2","משלי ז, כ."],["3","3","ראה גם סנהדרין צו, ב. וראה אוה\"ת (יהל אור) עה\"פ (ע' רפה ואילך). רד\"ה תקעו תרכ\"ט (סה\"מ תרכ\"ח ע' קעג). תרס\"א (סה\"מ תרס\"א ע' קסא), תרצ\"א, תרח\"ץ (סה\"מ תרח\"ץ ע' יא)."],["4","4","ראה מצו\"צ עה\"פ: הה\"א תמורת האל\"ף."],["5","5","ר\"ה ח, סע\"א ואילך. לד, סע\"א. סנהדרין יא, סע\"ב."],["6","6","עקב יא, יב. וראה תניא אגה\"ק סי\"ד."],["7","7","ראה אוה\"ת דרושים לר\"ה ע' א'שסט. סה\"מ תרל\"ד ע' שיז. סה\"מ תר\"ס ע' ב."],["8","8","ראה סד\"ה תקעו תרכ\"ט (סה\"מ תרכ\"ח ע' קעז)."],["9","9","שער ר\"ה בתחילתו."],["10","10","שם."],["11","11","ר\"ה טז, ב (ובפרש\"י)."],["12","12","ראה ד\"ה ארשב\"נ דש\"פ נצבים תר\"ץ."],["13","13","ד\"ה ארשב\"נ הנ\"ל. וראה ספר השיחות קיץ ה'ש\"ת ע' 21. וראה גם רד\"ה תקעו תרכ\"ח (סה\"מ תרכ\"ז ע' תכח)."],["14","14","איוב ח, ז."],["15","15","סוס\"ח. סי\"ד."],["16","16","אוה\"ת בראשית ח\"ו תתרלז, א."],["17","17","א, ג."],["18","18","ירמי' כב, כט."],["19","19","ראה אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ג ע' קפ. קפח. רפה (הועתק ב\"היום יום\" יז אייר). ספר השיחות תרצ\"ו ע' 41. וש\"נ."],["20","20","מלאכי ג, יב."],["21","21","ר\"ה כו, ב."],["22","22","סנהדרין סה, א. וראה ב\"מ צ, ב."],["23","23","ראה ד\"ה להבין ענין תק\"ש ע\"פ כוונת הבעש\"ט ז\"ל – סידור עם דא\"ח רמה, ד ואילך."],["24","24","ר\"ה טז, א. לד, ב."],["25","25","ראה רד\"ה תקעו תרכ\"ט."],["26","26","בשלח טו, יח."],["27","27","עובדי' א, כא."],["28","28","מיכה ז, יח. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380908\" data-slug=\"likkutei-torah\" data-id=\"4001380908\">לקו\"ת נצבים מז, ב</a>. ובכ\"מ."],["29","29","שבת קיט, רע\"ב."],["30","30","ראה תנחומא בחוקותי ג. נשא טז. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. תניא רפל\"ו. ובכ\"מ."],["31","31","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380945\" data-slug=\"likkutei-torah\" data-id=\"4001380945\">לקו\"ת</a> דרושים לר\"ה נו, ג. סידור עם דא\"ח רלח, ב. רמא, ג. מאמרי אדה\"ז תקס\"ד ע' ריז-ריח."],["32","32","המשך וככה תרל\"ז סוף פרק פ. וראה גם רד\"ה שמע ישראל דיום ב' דר\"ה תש\"כ (תו\"מ חכ\"ז ע' 3)."],["33","33","ר\"ה לב, א."],["34","34","ואתחנן ו, ד."],["35","35","זהר ח\"א יח, ב."],["36","36","טור או\"ח סתקצ\"א."],["37","37","פרק ז."],["38","38","ראה זהר ח\"ב קלד, א וברמ\"ז – הובא בנצו\"א שם. מק\"מ שם. אג\"ק ח\"ב ע' קטז ואילך. אמרי בינה שער הק\"ש פרק סב."],["39","39","ברכות יג, ב."],["40","40","בהבא לקמן – ראה ד\"ה כל המאריך באחד תרע\"ח (סה\"מ תרע\"ח ע' שפד ואילך)."],["41","41","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370248\" data-slug=\"torah-or\" data-id=\"3901370248\">תו\"א וארא נה, ב</a> ואילך. סהמ\"צ להצ\"צ קכד, א ואילך."],["42","42","שער א (דרוש עגולים ויושר) ענף ב."],["43","43","שבועות לה, סע\"א. רמב\"ם הל' יסוה\"ת פ\"ו ה\"ב."],["44","44","פרש\"י: וירא כ, יג; וישלח לה, ז. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370252\" data-slug=\"torah-or\" data-id=\"3901370252\">תו\"א וארא נו, ב</a>. סהמ\"צ להצ\"צ קיג, א. ובכ\"מ."],["45","45","ראה סה\"מ תרס\"א ע' קסא ואילך. תרח\"ץ ע' מא ואילך. ובכ\"מ."],["46","46","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380308\" data-slug=\"likkutei-torah\" data-id=\"4001380308\">לקו\"ת</a> הוספות לויקרא נד, א. מקומות שבהערה הבאה."],["47","47","בכ\"ז – ראה סה\"מ תרס\"א ע' קעט. עת\"ר ע' לג. תרפ\"ט ע' 256 ואילך. ד\"ה אל יפטר ספ\"ג ואילך (לקמן ע' 176 ואילך). וראה ספר הערכים – חב\"ד ח\"ד ע' לה ואילך. וש\"נ."],["48","48","ע\"ח שער העקודים פ\"ג."],["49","49","תקו\"ז בהקדמה (ג, ב). תניא אגה\"ק ס\"כ."],["50","50","עבוה\"ק ח\"א רפ\"ח."],["51","51","זח\"ב קלה, סע\"א."],["52","52","רמד, ג ואילך."],["53","53","ראה גם אמרי בינה שער הק\"ש פס\"ב. המשך תער\"ב ח\"א פקצ\"ו. פרכ\"ג."],["54","54","משלי כה, א."],["55","55","ראה גם המשך תרס\"ו ע' עט ואילך. סה\"מ תרפ\"ט ע' 62 ואילך."],["56","56","ראה גם אמרי בינה שבהערה 53."],["57","57","איוב לג, לג. שבת קד, א."],["58","58","ראה זהר ח\"ג יא, סע\"א. סה, ב. וראה גם ד\"ה שמע ישראל דיום ב' דר\"ה תש\"כ פ\"ה (תו\"מ חכ\"ז ע' 8)."],["59","59","ראה זהר ח\"ג (אד\"ר) רפט, ב. עץ חיים שער הכללים פ\"ה. ועוד."],["60","60","זח\"א רמח, א. רנו, ב. רנח, א. ועוד."],["61","61","בד\"ה חסידים ואנשי מעשה פ\"ה ואילך (לקמן ע' 30 ואילך)."],["62","62","ראה גם אוה\"ת וסה\"מ תרל\"ד שבהערה 7."],["63","63","ראה או\"ת להה\"מ פג, רע\"א. פו, ד. צח, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380388\" data-slug=\"likkutei-torah\" data-id=\"4001380388\">לקו\"ת ס\"פ במדבר (כ, א</a>). סה\"מ תרל\"ד ע' רנו. תרל\"ה ח\"ב ע' תפד. וש\"נ."],["64","64","משלי כה, ג."],["65","65","ראה עטרת ראש שער ר\"ה פי\"ב."],["66","66","ראה ד\"ה אר\"א למה תוקעין דיום ב' דר\"ה תרצ\"א פ\"א. ד\"ה עלה אלקים בתרועה תרצ\"ט פ\"ב."],["67","67","ד\"ה לך אמר לבי דליל ג' דסליחות תש\"כ (תו\"מ חכ\"ח ע' 308 ואילך. תו\"מ סה\"מ אלול ע' רפא ואילך)."],["68","68","תהלים כז, ח."],["69","69","ראה סה\"מ תרצ\"ו ס\"ע 141 ואילך (וש\"נ). סה\"מ ה'ש\"ת ע' 153. רד\"ה אחרי ה\"א תלכו דש\"פ ראה תש\"כ (תו\"מ חכ\"ח ע' 280)."],["70","70","ראה ספר השיחות תש\"ג ע' 177. שם ע' 179."],["71","71","ראה זהר ח\"א קכט, סע\"א ואילך."],["72","72","ויק\"ר פכ\"ט, ו."],["73","73","ראה לקו\"ת דרושים לר\"ה נד, ריש ע\"ד. ובכ\"מ."],["74","74","ראה אוה\"ת סוכות ס\"ע א'תשסב ואילך. רד\"ה ביום השמע\"צ תש\"כ (תו\"מ חכ\"ז ע' 95). ובכ\"מ."]]]]});
